INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-19', 'పద్యాలమాల', 'జ్ఞానమాల', 'పొదుపు', 'ఆయమెంతో పద్దులందు లెక్కించుచు
