INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-21', 'పద్యాలమాల', 'జ్ఞానమాల', 'బాల్యం', 'బాల్యమందునుంచి బాలబాలికలకు
