INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-22', 'పద్యాలమాల', 'జ్ఞానమాల', 'భారం', 'బరువులెత్తుకొంచు పరుగెత్తగారాదు !
