INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-23', 'పద్యాలమాల', 'జ్ఞానమాల', 'మంచితనం', 'షాకు కొట్టు చుండు చక్కని విద్యుత్తు !
