INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-24', 'పద్యాలమాల', 'జ్ఞానమాల', 'మనసు', 'ఖలుని చూపుపడిన శిలలుకూడ పగులు !
