INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-34', 'పద్యాలమాల', 'జ్ఞానమాల', 'సుఖం', 'ఓర్పు మించు సద్గుణోన్నతి ఎక్కడ ?
