INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-37', 'మిరా', 'జ్ఞానమాల', 'తెలుగు భాష', 'వేనవేల కవుల వెలుగులో రూపొంది
