INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-138', 'శతకాలమాల', 'జ్ఞానమాల', 'తెలుగుబాల! పద్యం 99', 'మనసు, మధుకరంబు, మద్యంబు, మత్స్యంబు,
మదము, మర్కటంబు, మారుతంబు
చంచలంబు లివ్వి, సప్తమకారముల్
లలితసుగుణజాల! తెలుగుబాల!!', 'జంధ్యాల పాపయ్య శాస్త్రి', '', NULL, 'b9a9730846d3da727276ac6dc63d71c8a6c1ef9215192dc127f841c236db84b8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-139', 'శతకాలమాల', 'జ్ఞానమాల', 'తెలుగుబాల! పద్యం 100', 'జనని, జన్మభూమి, జనకుండు, జాతీయ
కేతనంబు, జాహ్నవీతటంబు
పరమపావనములు పంచజకారముల్
లలితసుగుణజాల! తెలుగుబాల!!', 'జంధ్యాల పాపయ్య శాస్త్రి', '', NULL, '8677acc8afbe23b04b8ec70e10aebd238f4d398756f6644a6bd314da451a99ba') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-140', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 1', 'శ్రీ రాముని దయచేతను
నారూఢిగ సకల జనులు నౌరా యనగా
ధారాళమైన నీతులు
నోరూరగ జవులు పుట్ట నుడివెద సుమతీ', 'బద్దెన', '', NULL, 'bd175d1e890a4e2c76ad7579508294c941ae8e307fbac64a980aca42d1a3bfa1') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-141', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 2', 'అక్కరకు రాని చుట్టము,
మ్రొక్కిన వరమీని వేల్పు, మోహరమున దా
నెక్కిన బారని గుర్రము
గ్రక్కున విడవంగవలయు గదరా సుమతీ', 'బద్దెన', '', NULL, 'e849ba7ef30e317ff13ef471943170e30e16fc55dbd5ca6e79c823b5216e04be') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-142', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 3', 'అడిగిన జీతంబియ్యని
మిడిమేలుపు దొరను గొల్చి మిడుకుట కంటెన్‌
వడిగల యెద్దుల గట్టుక
మడి దున్నుకు బ్రతుక వచ్చు మహిలో సుమతీ', 'బద్దెన', '', NULL, '5ad5cf64b1b2f1604b477c320936199be4dd447e1c17d010beb8b9fd32fa93c9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-143', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 4', 'అడియాస కొలువు గొలువకు,
గుడి మణియము సేయబోకు, కుజనుల తోడన్‌
విడువక కూరిమి సేయకు,
మడవిని దో డరయ కొంటి నరుగకు సుమతీ', 'బద్దెన', '', NULL, '934480a8fcce661e7712f46e4a4366fdfcdfd941ccfa3de58eddf22fe09584e2') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-144', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 5', 'అధరము గదలియు, గదలక
మధురములగు భాష లుడుగి మౌన వ్రతుడౌ
అధికార రోగ పూరిత
బధిరాంధక శవము జూడ బాపము సుమతీ', 'బద్దెన', '', NULL, '8bf86692894576045d914fb56d523d5348d42252c747a071c997da73f9dbf1ab') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-145', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 6', 'అప్పు కొని చేయు విభవము,
ముప్పున బ్రాయంపుటాలు, మూర్ఖుని తపమున్‌,
దప్పరయని నృపు రాజ్యము
దెప్పరమై మీద గీడు దెచ్చుర సుమతీ', 'బద్దెన', '', NULL, '20937da3aae2ce383890384b93e57a83d66d1ba702f61b8f638af22f9fa133bf') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-146', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 7', 'అప్పిచ్చువాడు, వైద్యుడు
నెప్పుడు నెడతెగక పారు నేరును, ద్విజుడున్‌
జొప్పడిన యూర నుండుము
చొప్పడకున్నట్టి యూరు చొరకుము సుమతీ', 'బద్దెన', '', NULL, '4dfd254e94d08634f52f91cf38e6963ac35beaedb27c17718f985745715e5ca7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-147', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 8', 'అల్లుని మంచితనంబును,
కాపు సాహిత్య విద్య, కోమలి నిజమున్‌,
బొల్లున దంచిన బియ్యము,
దెల్లని కాకులును లేవు తెలియుము సుమతీ', 'బద్దెన', '', NULL, '8d62fa6b4f2f87783ea9f8e59627def2a262c3b6db9d50075e0b5266e281cbd3') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-148', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 9', 'ఆకొన్న కూడె యమృతము,
తాకొందక నిచ్చువాడె దాత ధరిత్రిన్‌,
సోకోర్చువాడె మనుజుడు,
తేకువ గలవాడె వంశ తిలకుడు సుమతీ', 'బద్దెన', '', NULL, '87b9e8bacd861c0be2f8d7ee30e1fbc3a5182e90840b5236fec9558e570a8cb9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-149', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 10', 'ఆకలి యుడుగని కడుపును,
వేకటియగు లంజ పడుపు విడువని బ్రతుకున్‌,
బ్రాకొన్న నూతి యుదకము,
మేకల పాడియును రోత మేదిని సుమతీ', 'బద్దెన', '', NULL, '3f82b4fdd3f696bddf63087f3383443edafa893defd635468829ee403e78f243') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-150', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 11', 'ఇచ్చునదె విద్య, రణమున
జొచ్చునదే మగతనంబు, సుకవీశ్వరులున్‌
మెచ్చునదే నేర్చు, వదుకు
వచ్చునదే కీడు సుమ్ము వసుధను సుమతీ', 'బద్దెన', '', NULL, '116dbd423db46a00dcddc6c0a6c0589714da6762aed2b142125916198ba736e0') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-151', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 12', 'ఇమ్ముగ జదువని నోరును,
నమ్మా యని బిలిచి యన్న మడుగని నోరున్‌,
దమ్ముల బిలువని నోరును
గుమ్మరి మను ద్రవ్వినట్టి గుంటర సుమతీ', 'బద్దెన', '', NULL, 'a74a3cfb6de46493cc033586b74e60d5827b9ed6d83b280177851a82cd663d9f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-152', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 13', 'ఉడుముండదె నూరేండ్లును,
బడియుండదె పేర్మి బాము పదినూరేండ్లున్‌,
మడువున గొక్కెర యుండదె,
కడు నిల బురుషార్థ పరుడు గావలె సుమతీ', 'బద్దెన', '', NULL, '3320b289096a2a38b13db70678270998af91e75bf5e88d968f13a7d44fdd4521') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-153', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 14', 'ఉత్తమగుణములు నీచున
కెత్తెఱగున గలుగ నేర్చు; నెయ్యెడలం దా
నెత్తిచ్చి కరగి పోసిన
నిత్తడి బంగారమగునె యిలలో సుమతీ?', 'బద్దెన', '', NULL, '9e03e4432076a23d8512625602f540bd960a4ecfc6d14bbaa7d4e1e70fbff38a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-154', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 15', 'ఉదకము ద్రావెడు హయమును,
మదమున నుప్పొంగుచుండు మత్తేభంబున్‌,
మొదవు కడ నున్న వృషభము,
జదువని యానీచు గడకు జనకుర సుమతీ', 'బద్దెన', '', NULL, '07cce5c62757267fda3b441e12a7a97c1bac5dfbadc79492a835e8b0a88c2406') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-155', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 16', 'ఉపకారికి నుపకారము
విపరీతము గాదు సేయ వివరింపంగా;
అపకారికి నుపకారము
నెపమెన్నక సేయువాడు నేర్పరి సుమతీ', 'బద్దెన', '', NULL, '3be86f4d1a1b753b846c42bcaddbaf6efaf59a39eb519648fb73d5b6c6c54e1f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-156', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 17', 'ఉపమింప మొదలు తియ్యన
కపటం బెడనెడను జెఱకు కై వడినే పో
నెపములు వెదకును గడపట
గపటపు దుర్జాతి పొందు గదరా సుమతీ', 'బద్దెన', '', NULL, '3e008e3ab2665c737bdfb94bb3d85e68b4686732e296e9285822b48f482894e8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-157', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 18', 'ఎప్పటి కెయ్యది ప్రస్తుత
మప్పటికా మాటలాడి, యన్యుల మనముల్‌
నొప్పించక, తా నొవ్వక,
తప్పించుక తిరుగువాడు ధన్యుడు సుమతీ', 'బద్దెన', '', NULL, '2ad7eaa766d7e5f573ef61be748b6e2b5c2fcf095bfd04431725de49b301d459') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-158', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 19', 'ఎప్పుడు దప్పులు వెదకెడు
నప్పురుషుని గొల్వగూడ దది యెట్లన్నన్‌
సర్పంబు పడగ నీడను
గప్ప వసించిన విధంబు గదరా సుమతీ', 'బద్దెన', '', NULL, '4d9b6a16a7dffc855f9693232267dd7b4fab2f88b3ead2fa3f33b37cac9448f7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-159', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 20', 'ఎప్పుడు సంపద కలిగిన
నప్పుడు బంధువులు వత్తు రది యెట్లన్నన్‌
తెప్పలుగ జెఱువు నిండిన
గప్పలు పదివేలు చేరు గదరా సుమతీ', 'బద్దెన', '', NULL, '9540ce1548ca96bdb9edcb4e93b2c0beb1f3cc4f1ecebbf5efa9f7ab135c8d18') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-160', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 21', 'ఏఱకుమీ కసుగాయలు,
దూఱకుమీ బంధుజనుల దోషము సుమ్మీ,
పాఱకుమీ రణమందున,
మీఱకుమీ గురువు నాజ్ఞ మేదిని సుమతీ', 'బద్దెన', '', NULL, '0dca5d53ec4f704681206d15ade83ff79dfa5819890444f6c2b07a966bdef122') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-161', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 22', 'ఒక యూరికి నొక కరణము,
నొక తీర్పరియైన గాక, నొగి దఱుచైనన్‌,
గకవికలు గాక యుండునె
సకలంబును గొట్టువడక సహజము సుమతీ', 'బద్దెన', '', NULL, 'b6fb0368770987c9cfe1b050cf53340d32b6a71fcb0381613e7726916b19b917') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-162', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 23', 'ఒరు నాత్మ దలచు సతి విడు,
మఱుమాటలు పలుకు సతుల మన్నింపకుమీ,
వెఱ పెఱుగని భటునేలకు,
తఱచుగ సతి గవయ బోకు, తగదుర సుమతీ', 'బద్దెన', '', NULL, '44059036889412e6c4f3f4270466275ee7e8f68c419a3e6f7c827734d2b22ad9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-163', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 24', 'ఒల్లని సతి నొల్లని పతి,
నొల్లని చెలికాని విడువ నొల్లని వాడే
గొల్లండు, కాక ధరలో
గొల్లండును గొల్లడౌనె గుణమున సుమతీ', 'బద్దెన', '', NULL, 'ffc298055febc32fde4cf0f2d45b8bacc1e711dcc7b99248426410ab60b05bc7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-164', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 25', 'ఓడల బండ్లును వచ్చును,
ఓడలు నాబండ్లమీద నొప్పుగ వచ్చున్‌,
ఓడలు బండ్లును వలనే
వాడంబడు గలిమి లేమి వసుధను సుమతీ', 'బద్దెన', '', NULL, 'c370f720830eb9a7f52858b0d000a6d59e52270a4625671e6b479d20be9a60a5') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-165', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 26', 'కడు బలవంతుడైనను
బుడమిని బ్రాయంపుటాలి బుట్టిన యింటన్‌
దడవుండ నిచ్చెనేనియు
బడుపుగ నంగడికి దానె బంపుట సుమతీ', 'బద్దెన', '', NULL, '5d5b5c1200daac0d6abb0f88674a69c6fd97988a6c1df1b44d48de0b66443e92') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-166', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 27', 'కనకపు సింహాసనమున
శునకము గూర్చుండబెట్టి శుభ లగ్నమునం
దొనరగ బట్టము గట్టిన
వెనుకటి గుణమేల మాను వినరా సుమతీ', 'బద్దెన', '', NULL, '45a359b639c465b8beae9a03efa8133d5fe80176b0ebbabd68d119928346c299') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-167', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 28', 'కప్పకు నొరగాలైనను,
సర్పమునకు రోగమైన, సతి తులువైనన్‌,
ముప్పున దరిద్రుడైనను,
తప్పదు మఱి దుఃఖ మగుట తథ్యము సుమతీ', 'బద్దెన', '', NULL, 'e7a22487ffdddcd79ee29665bf031088793a1b65960e141ad806a72b406ef25d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-168', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 29', 'కమలములు నీట బాసిన
కమలాప్తుని రశ్మి సోకి కమలిన భంగిన్‌
తమ తమ నెలవులు దప్పిన
తమ మిత్రులు శత్రులౌట తథ్యము సుమతీ', 'బద్దెన', '', NULL, '93d93784b32cce9d9a860dd525a35ad5f39ff2b96158c5a204e5e59644ffe435') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-169', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 30', 'కరణము గరణము నమ్మిన
మరణాంతక మౌను గాని మనలేడు సుమీ;
కరణము దన సరి కరణము
మఱి నమ్మక మర్మ మీక మనవలె సుమతీ', 'బద్దెన', '', NULL, 'e9981c9728255a95dff97499d7bfc83590c5818a1cce60a36d7f5bdd34cf98ea') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-170', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 31', 'కరణముల ననుసరింపక
విరసంబున దిన్న తిండి వికటించు జుమీ
యిరుసున కందెన బెట్టక
పరమేశ్వరు బండి యైన బారదు సుమతీ', 'బద్దెన', '', NULL, '5b3250c9720fc6a1424b9e92e147306cc9d3ca9cd13efd4bab71b52d1c6b5850') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-171', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 32', 'కరణము సాదైయున్నను,
గరి మద ముడిగినను, బాము గఱవక యున్నన్‌,
ధర దేలు మీటకున్నను,
గర మరుదుగ లెక్క గొనరు గదరా సుమతీ', 'బద్దెన', '', NULL, '414bacee783e494de9cc7ca2c0352071b4141d8e9b8693246571f69e5ec00129') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-172', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 33', 'కసుగాయ గఱచి చూచిన
మసలక పస యొగరు రాక మధురంబగునా;
పస గలుగు యువతులుండగ
పసి బాలల బొందువాడు పశువుర సుమతీ', 'బద్దెన', '', NULL, '6d5fa0d408a298cee89dc9fe55dbcef6ca63b142c2ed397eb3a07622735dbc90') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-173', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 34', 'కవి కాని వాని వ్రాతయు,
నవరస భావములు లేని నాతుల వలపున్‌,
దవిలి చను పంది నేయని
వివిధాయుధ కౌశలంబు వృధరా సుమతీ', 'బద్దెన', '', NULL, '3eea95b13c3998c61e9d2e1b61cfd258efec42965117ee7e8bdd64b0d1dfade5') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-174', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 35', 'కాదు సుమీ దుస్సంగతి,
పోదుసుమీ "కీర్తి" కాంత పొందిన పిదపన్‌,
వాదు సుమీ యప్పిచ్చుట,
లేదు సుమీ సతుల వలపు లేశము సుమతీ', 'బద్దెన', '', NULL, '22f76b52c8098209114e0d62f1e29007cd3298927b23c486a9b051ffed139074') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-175', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 36', 'కాముకుడు దనిసి విడిచిన
కోమలి బరవిటుడు గవయ గోరుట యెల్లన్‌
బ్రేమమున జెఱకు పిప్పికి
చీమలు వెస మూగినట్లు సిద్ధము సుమతీ', 'బద్దెన', '', NULL, '9c0611bb2a803c6b984dff31932d22c24291bbec84b18fe17881986eb516e6e5') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-176', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 37', 'కారణము లేని నగవును,
బేరణము లేని లేమ, పృథివీ స్థలిలో
బూరణము లేని బూరెయు,
వీరణము లేని పెండ్లి వృధరా సుమతీ', 'బద్దెన', '', NULL, '48f5479f12c4500f2ba37eabc67801f0ccedae4a4a4fdb279111dc2deb111fa6') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-177', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 38', 'కులకాంత తోడ నెప్పుడు
గలహింపకు, వట్టి తప్పు ఘటియింపకుమీ,
కలకంఠి కంట కన్నీ
రొలికిన సిరి యింట నుండ నొల్లదు సుమతీ', 'బద్దెన', '', NULL, 'bd08da8344f90c078f5648f8defdce2bcfce03c164bd9b2ea8878e1e36c037c7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-178', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 39', 'కూరిమి గల దినములలో
నేరము లెన్నడును గలుగ నేరవు మఱి యా
కూరిమి విరసంబైనను
నేరములే తోచు చుండు నిక్కము సుమతీ', 'బద్దెన', '', NULL, 'e0d596fdd6fdbf823a2bc2d866315d86acee5d6e7d593ac2798540599a527471') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-179', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 40', 'కొంచెపు నరు సంగతిచే
నంచితముగ గీడు వచ్చు నది యెట్లన్నన్‌
గించిత్తు నల్లి కుట్టిన
మంచమునకు జేటు వచ్చు మహిలో సుమతీ', 'బద్దెన', '', NULL, '56bb39fd8e09afbee8bcaf9d713fc84b3c6e6d5f67151b5ed0a47785a1cc94ef') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-180', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 41', 'కొక్కోకమెల్ల జదివిన,
చక్కనివాడైన, రాజ చంద్రుండైనన్‌,
మిక్కిలి రొక్కము లియ్యక,
చిక్కదురా వారకాంత సిద్ధము సుమతీ', 'బద్దెన', '', NULL, 'b8c8be1624734b76b4e804db92dfe58d7ebdecd7a43163a16244d381d513da77') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-181', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 42', 'కొఱ గాని కొడుకు బుట్టిన
కొఱ గామియె కాదు, తండ్రి గుణముల జెఱచున్‌
చెఱకు తుద వెన్ను బుట్టిన
జెఱకున తీపెల్ల జెఱచు సిద్ధము సుమతీ', 'బద్దెన', '', NULL, 'ee9a5a3c5e7d89923626ece63fcc633a4cb3ffd69fd1343e739d5e190fdb4f03') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-182', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 43', 'కోమలి విశ్వాసంబును,
బాములతో జెలిమి, యన్య భామల వలపున్‌,
వేముల తియ్యదనంబును,
భూమీశుల నమ్మికలును బొంకుర సుమతీ', 'బద్దెన', '', NULL, '6b82988e843426184317f55c5ab77ada3ecfd083738f86c9f111dfe9dbb07035') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-183', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 44', 'గడన గల మగని జూచిన
నడుగడుగున మడుగు లిడుదు రతివలు దమలో;
గడ నుడుగు మగని జూచిన
నడ పీనుగు వచ్చె నంచు నగుదురు సుమతీ', 'బద్దెన', '', NULL, '1b368140ff57c5a6575a052b40f66a0a3d11743f15705f8354671a8a3b14205c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-184', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 45', 'చింతింపకు కడచిన పని,
కింతులు వలతురని నమ్మ కెంతయు మదిలో,
నంతఃపుర కాంతలతో
మంతనముల మాను మిదియె మతముర సుమతీ', 'బద్దెన', '', NULL, '6371c37636c0050bdeb7f2814a0bae76d52a48e75e98a1215d50ccf08c0d6d6c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-185', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 46', 'చీమలు పెట్టిన పుట్టలు
పాముల కిరవైనయట్లు పామరుడు దగన్‌
హేమంబు గూడ బెట్టిన
భూమీశుల పాల జేరు భువిలో సుమతీ', 'బద్దెన', '', NULL, '9a10582fa0acc8513613a04be1e2ba173c2c17fe023e92e27abf9b70d8dbba48') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-186', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 47', 'చుట్టములు గాని వారలు
చుట్టములము నీకటంచు సొంపు దలిర్పన్‌
నెట్టుకొని యాశ్రయింతురు
గట్టిగ ద్రవ్యంబు గలుగ గదరా సుమతీ', 'బద్దెన', '', NULL, 'bb126f303d95461685514528f1b994fbd7c1305ec7d30a53ce5bcc6f76b0faa2') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-187', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 48', 'చేతులకు దొడవు దానము,
భూతలనాథులకు దొడవు బొంకమి ధరలో,
నీతియె తొడవెవ్వారికి,
నాతికి మానంబు తొడవు నయముగ సుమతీ', 'బద్దెన', '', NULL, 'b6fd454c35b4e0dfacf0f3fcec7a1ef2ed15f7104d3402c7ebb2353f28ec16c4') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-188', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 49', 'తడ వోర్వక, యొడ లోర్వక,
కడు వేగం బడిచి పడిన గార్యం బగునే;
తడ వోర్చిన, నొడ లోర్చిన,
జెడిపోయిన కార్యమెల్ల జేకుఱు సుమతీ', 'బద్దెన', '', NULL, '1e692a3f653aaba29408d4cfc311708129258d1fd62ac0f3a6ba5614224a20e9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-189', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 50', 'తన కోపమె తన శత్రువు,
తన శాంతమె తనకు రక్ష, దయ చుట్టంబౌ
తన సంతోషమె స్వర్గము,
తన దుఃఖమె నరక మండ్రు తథ్యము సుమతీ', 'బద్దెన', '', NULL, 'a83871e9a9420575e9bda7a0ac4dfdbb4d30de17b20de5d76e2478b01ed6dd24') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-190', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 51', 'తన యూరి తపసి తపమును,
తన పుత్రుని విద్య పెంపు, దన సతి రూపున్‌,
దన పెరటి చెట్టు మందును,
మనసున వర్ణింపరెట్టి మనుజులు సుమతీ', 'బద్దెన', '', NULL, '6b3c831fa43124a7f89afaef7e09ee90d09969f963dbf3008d40484b15f9fb64') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-191', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 52', 'తన కలిమి యింద్ర భోగము,
తన లేమియె స్వర్గలోక దారిద్ర్యంబున్‌,
దన చావు జల ప్రళయము,
తను వలచిన యదియె రంభ తథ్యము సుమతీ!', 'బద్దెన', '', NULL, 'd25f8b07b170af6cc579e39076cd4e60c430155330f7c2f1ce3b7b8392e45ae0') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-192', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 53', 'తన వారు లేని చోటను,
జనమించుక లేని చోట, జగడము చోటన్‌,
అనుమానమైన చోటను,
మనుజునకును నిలువ దగదు మహిలో సుమతీ', 'బద్దెన', '', NULL, 'cdb0f9544250a5fc33fe0c3e772411841c058426944a89e02f8a61e33d5e8063') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-193', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 54', 'తమలము వేయని నోరును,
విమతులతో చెలిమి చేసి వెతబడు తెలివిన్‌,
గమలములు లేని కొలకును,
హిమధాముడు లేని రాత్రి హీనము సుమతీ', 'బద్దెన', '', NULL, 'dd321e498d54062e04cee29aba2bfa5115d5215b084bfee53d0fbfd7068adecf') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-194', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 55', 'తలనుండు విషము ఫణికిని,
వెలయంగా దోక నుండు వృశ్చికమునకున్‌,
తలతోక యనక యుండును
ఖలునకు నిలువెల్ల విషము గదరా సుమతీ!', 'బద్దెన', '', NULL, 'a4f854a8ade8a831926f8fb7b28c600af3d7f9df3fefd70cfd22c46bbdfef442') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-195', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 56', 'తలపొడుగు ధనము పోసిన
వెలయాలికి నిజము లేదు వివరింపంగా
దల దడివి బాస జేసిన
వెలయాలిని నమ్మరాదు వినరా సుమతీ', 'బద్దెన', '', NULL, '2d7198087e750f66e62b3ad0bbc6585901aef5056b8a20c87edb9943d152f4de') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-196', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 57', 'తల మాసిన, నొలు మాసిన,
వలువలు మాసినను బ్రాణ వల్లభునైనన్‌
గులకాంతలైన రోతురు
తిలకింపగ భూమిలోన దిరముగ సుమతీ!', 'బద్దెన', '', NULL, '38db36a74770102d6b2d3477f7eaa7b54ca8af50a65db5b859f0fba9f3856998') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-197', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 58', 'తాను భుజింపని యర్థము
మానవ పతి జేరు గొంత మఱి భూగతమౌ
గానల నీగలు గూర్చిన
తేనియ యొరు జేరునట్లు తిరముగ సుమతీ!', 'బద్దెన', '', NULL, '7f6fe531ce0612e431c22c41e7073d02f4800fdfc3031d47386965a1121e92ae') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-198', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 59', 'దగ్గఱ కొండెము సెప్పెడు
ప్రెగ్గడ పలుకులకు రాజు ప్రియుడై మఱి దా
నెగ్గు బ్రజ కాచరించుట
బొగ్గులకై కల్పతరువు బొడుచుట సుమతీ!', 'బద్దెన', '', NULL, 'ffc7a3f1f298f3eda0ece6342529603046aa682a7cbd7a9fbec94120f36f05c9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-199', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 60', 'ధనపతి సఖుడైయుండగ
నెనయంగా శివుడు భిక్షమెత్తగ వలసెన్‌;
దన వారి కెంత గలిగిన
దన భాగ్యమె తనకు గాక తథ్యము సుమతీ!', 'బద్దెన', '', NULL, 'ef0616d4ddc4d8bb4cb747b68fe4bc5c91deeeeb0bc98a2f29dea62547190637') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-200', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 61', 'ధీరులకు జేయు మేలది
సారంబగు నారికేళ సలిలము భంగిన్‌
గౌరవమును మఱి మీదట
భూరి సుఖావహము నగును భువిలో సుమతీ!', 'బద్దెన', '', NULL, 'eaf8a7e260330ea83c8489acf5e39807f17792bd6aee82ea1425af367a850bd1') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-201', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 62', 'నడువకుమీ తెరువొక్కట,
గుడువకుమీ శత్రు నింట గూరిమి తోడన్‌,
ముడువకుమీ పరధనముల,
నుడువకుమీ యొరుల మనసు నొవ్వగ సుమతీ', 'బద్దెన', '', NULL, 'fa6a5d15d4630ed6a45df6e0f5b8d82734e9c26d4075d23a993846c944aef5ce') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-202', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 63', 'నమ్మకు సుంకరి, జూదరి,
నమ్మకు మొగసాల వాని, నటు వెలయాలిన్‌,
నమ్మకు మంగడి వానిని,
నమ్మకు మీ వామ హస్తు నవనిని సుమతీ!', 'బద్దెన', '', NULL, '043a19bab89d9e38eaa268c5a0eecb68c15cdd9a677ee43eadd1d4a84177f684') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-203', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 64', 'నయమున బాలుం ద్రావరు,
భయమునను విషమ్మునైన భక్షింతురుగా;
నయమెంత దోషకారియొ,
భయమే జూపంగ వలయు బాగుగ సుమతీ!', 'బద్దెన', '', NULL, 'a11c5a8083ee27312557dc71ccbcd44ba96ffdf2ee1672a1ab5f0893c1ecfada') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-204', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 65', 'నరపతులు మేఱ దప్పిన,
దిరమొప్పగ విధవ యింట దీర్పరి యైనన్‌,
గరణము వైదికుడైనను,
మరణాంతక మౌనుగాని మానదు సుమతీ!', 'బద్దెన', '', NULL, '5765ac613ec262c1b95d3cde040a97d9113ebba1d5e74e7bcd6bc34bcd440a56') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-205', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 66', 'నవరస భావాలంకృత
కవితా గోష్టియును, మధుర గానంబును దా
నవివేకి కెంత జెప్పిన
జెవిటికి శంఖూదినట్లు సిద్ధము సుమతీ!', 'బద్దెన', '', NULL, '5ca6a1934c0871f02ce2fbb39e1d786b04104b073e76d127a172d2a2dd99d09a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-206', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 67', 'నవ్వకుమీ సభ లోపల;
నవ్వకుమీ తల్లి, దండ్రి, నాథుల తోడన్‌;
నవ్వకుమీ పరసతితో;
నవ్వకుమీ విప్రవరుల నయమిది సుమతీ', 'బద్దెన', '', NULL, '7538100960553980f23e0d01d7c417c353f401d5577e28847b52855602c2bcd5') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-207', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 68', 'నీరే ప్రాణాధారము
నోరే రసభరితమైన నుడువుల కెల్లన్‌
నారియె నరులకు రత్నము
చీరయె శృంగారమండ్రు సిద్ధము సుమతీ!', 'బద్దెన', '', NULL, 'be6867587819d4010ee5b8ac05df89b8c4509138083cc03ee13495b1b081694f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-208', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 69', 'పగవల దెవ్వరి తోడను,
వగవంగా వలదు లేమి వచ్చిన పిదపన్‌,
దెగ నాడ వలదు సభలను
మగువకు మనసియ్య వలదు మహిలో సుమతీ', 'బద్దెన', '', NULL, 'c510731065a3ea3f8250dcca393d031e4fe8189c2591cf0574e278ba21ab1946') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-209', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 70', 'పతికడకు, దన్ను గూరిన
సతికడకును, వేల్పు కడకు, సద్గురు కడకున్‌,
సుతుకడకు రిత్తచేతుల
మతిమంతులు చనరు నీతి మార్గము సుమతీ!', 'బద్దెన', '', NULL, 'cd0466d06cab866e2eb75d0880e637aa8ef730a13be3687aea3cd32a52e7ffda') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-210', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 71', 'పనిచేయునెడల దాసియు,
ననుభవమున రంభ, మంత్రి యాలోచనలన్‌,
దనభుక్తి యెడల దల్లియు,
నన్‌ దన కులకాంత యుండు నగురా సుమతీ!', 'బద్దెన', '', NULL, '195dba8facb41be9b2c500ac5b0c064cbbdde3297eddb4daeaede208dd1f4dec') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-211', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 72', 'పరనారీ సోదరుడై,
పరధనముల కాసపడక, పరులకు హితుడై,
పరులు దను బొగడ నెగడక,
పరు లలిగిన నలుగ నతడు పరముడు సుమతీ!', 'బద్దెన', '', NULL, 'a119b8e8f910fc4d4b942357ab4596acca6190711d90b1431d035f143afb48b5') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-212', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 73', 'పరసతి కూటమి గోరకు,
పరధనముల కాసపడకు, బరునెంచకుమీ,
సరిగాని గోష్టి సేయకు,
సిరిచెడి చుట్టంబు కడకు జేరకు సుమతీ', 'బద్దెన', '', NULL, '26d3c9606894d129a9d509111afd7022e7b72d51263cb07defbe4e1f5e821d4c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-213', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 74', 'పరసతుల గోష్ఠి నుండిన
పురుషుడు గాంగేయుడైన భువి నింద పడున్‌,
బరసతి సుశీలయైనను
బరుసంగతి నున్న నింద పాలగు సుమతీ!', 'బద్దెన', '', NULL, 'a46ff35b04c3d529baab5bff17aae5ab094ca504f42f679835e4fa8036a8d643') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-214', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 75', 'పరులకు నిష్టము సెప్పకు,
పొరుగిండ్లకు బనులు లేక పోవకు మెపుడున్‌,
బరు గదిసిన సతి గవయకు,
మెఱిగియు బిరుసైన హయము లెక్కకు సుమతీ', 'బద్దెన', '', NULL, '53c368bdcadeea4b041206b7a458d86e3af845d0abef83c100be49e1e6d9f848') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-215', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 76', 'పర్వముల సతుల గవయకు,
ముర్వీశ్వరు కరుణ నమ్మి యుబ్బకు మదిలో,
గర్వింప నాలి బెంపకు,
నిర్వహణము లేని చోట నిలువకు సుమతీ', 'బద్దెన', '', NULL, '9e29eb119c5544071d324d6c14271dce46c4d6f217cba539c2f9636839953a33') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-216', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 77', 'పలు దోమి సేయు విడియము,
తలగడిగిన నాటి నిద్ర, తరుణులయెడలన్‌
బొల యలుక నాటి కూటమి
వెల యింతని చెప్పరాదు వినరా సుమతీ!', 'బద్దెన', '', NULL, '7d46ff8c84311454d556db63a719f5cc9f741290b499264634cbe1a6c4afaffa') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-217', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 78', 'పాటెఱుగని పతి కొలువును,
గూటంబున కెఱుకపడని కోమలి రతియున్‌,
బేటెత్త జేయు చెలిమియు,
నేటికి నెదురీదినట్టు లెన్నగ సుమతీ', 'బద్దెన', '', NULL, 'c492ab18d979bbc9dd23c057f260f3662bf28962a9562e9fcb4a7894fd6d48f3') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-218', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 79', 'పాలను గలసిన జలమును
పాల విధంబుననె యుండు బరికింపంగా
పాల చవి జెఱచు గావున
పాలసుడగు వాని పొందు వలదుర సుమతీ', 'బద్దెన', '', NULL, 'df8979bc9af18f2c4a6906806f1ae31953df6bfbcb2597d59e4c702b4cb06c9a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-219', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 80', 'పాలసునకైన యాపద
జాలింబడి తీర్ప దగదు సర్వజ్ఞునకున్‌
తేలగ్ని బడగ బట్టిన
మేలెఱుగునె మీటు గాక మేదిని సుమతీ', 'బద్దెన', '', NULL, 'ec12544c9b4ba5552798013a5998d03efe29b8363deb9b01b7357fef21427b9d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-220', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 81', 'పిలువని పనులకు బోవుట,
గలయని సతి గతియు, రాజు గానని కొలువుం,
బిలువని పేరంటంబును,
వలువని చెలిమియును జేయ వలదుర సుమతీ', 'బద్దెన', '', NULL, '6eb647d4309797d53f13645af6896f4c5cad3ba1b7c5090249da0ece37889b45') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-221', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 82', 'పుత్రోత్సాహము తండ్రికి
పుత్రుడు జన్మించినపుడె పుట్టదు, జనులా
పుత్రుని కనుగొని బొగడగ
పుత్రోత్సాహంబు నాడు పొందుర సుమతీ!', 'బద్దెన', '', NULL, '0d97f9b8151a432c2dfc96b851f02acfc8b003317aecb93382c9a2a5b1f22983') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-222', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 83', 'పురికిని ప్రాణము గోమటి,
వరికిని ప్రాణంబు నీరు వసుమతి లోనన్‌,
గరికిని ప్రాణము తొండము,
సిరికిని ప్రాణంబు మగువ సిద్ధము సుమతీ!', 'బద్దెన', '', NULL, 'a233ac694b69b9fdb5ed5f47483c0b7214162b2152a84d19c8d5b0b74b456e2e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-223', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 84', 'పులి పాలు దెచ్చి యిచ్చిన,
నలవడగా గుండె గోసి యఱచే నిడినన్‌,
దలపొడుగు ధనము బోసిన,
వెలయాలికి గూర్మి లేదు వినరా సుమతీ!', 'బద్దెన', '', NULL, '64765ae6768cf01b730169adf019288c80ed1805a5bf45ea601af80034734038') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-224', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 85', 'పెట్టిన దినముల లోపల
నట్టడవులనైన వచ్చు నానార్థములున్‌,
బెట్టని దినముల గనకపు
గట్టెక్కిన నేమి లేదు గదరా సుమతీ! [85]', 'బద్దెన', '', NULL, 'be71858e3e384f1d2cef5374ac703b7e7a7e9e2517e5732295645c7aa49bf96a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-225', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 86', 'పొరుగున బగవాడుండిన,
నిరవొందక వ్రాతకాడె యేలిక యైనన్‌,
ధర గాపు కొండెమాడిన,
గరణాలకు బ్రదుకు లేదు గదరా సుమతీ!', 'బద్దెన', '', NULL, 'f2724b7307f2e7688694539548b7971ec59398dbff32a37def017ac694a51ffd') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-226', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 87', 'బంగారు కుదువ బెట్టకు,
సంగరమున బాఱిపోకు సరసుడవైతే,
నంగడి వెచ్చము వాడకు,
వెంగలితో జెలిమి వలదు వినరా సుమతీ', 'బద్దెన', '', NULL, '73d69dd688133fd8a6871af9e73da1faab5a2bbba17fc3d8f111339dcc478275') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-227', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 88', 'బలవంతుడ నాకేమని
పలువురతో నిగ్రహించి పలుకుట మేలా;
బలవంత మైన సర్పము
చలి చీమల చేత జిక్కి చావదె సుమతీ!', 'బద్దెన', '', NULL, '4b6e2720dcef726ac3b4e1791a856cc66c2d083feaeb14bbbc303a4c1e2b2fd4') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-228', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 89', 'మదినొకని వలచి యుండగ
మదిచెడి యొక క్రూర విటుడు మానక తిరుగున్‌
బది చిలుక పిల్లి పట్టిన
జదువునె యాపంజరమున జగతిని సుమతీ', 'బద్దెన', '', NULL, '562faf93b8189965c477544e8e0a97731e79ce3ccf80585403d0edb280206121') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-229', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 90', 'మండల పతి సముఖంబున
మెండైన ప్రధాని లేక మెలగుట యెల్లన్‌
గొండంత మదపు టేనుగు
తొండము లేకుండినట్లు దోచుర సుమతీ', 'బద్దెన', '', NULL, 'e30a60183bea0aa0b5dbfa4cacc4c9a3ac66e39bea395692c59dde514bd85d3b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-230', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 91', 'మంత్రిగలవాని రాజ్యము
తంత్రము సెడకుండ నిలుచు దఱచుగ ధరలో
మంత్రి విహీనుని రాజ్యము
జంత్రపు గీలూడినట్లు జరుగదు సుమతీ!', 'బద్దెన', '', NULL, '088a1c16376b59ad525f98b467494c063d2244d5ef12ba3741d88ba8db96fa42') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-231', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 92', 'మాటకు బ్రాణము సత్యము,
కోటకు బ్రాణంబు సుభట కోటి, ధరిత్రిన్‌
బోటికి బ్రాణము మానము,
చీటికి బ్రాణంబు వ్రాలు సిద్ధము సుమతీ!', 'బద్దెన', '', NULL, 'a13f644c29ac9283561dde73d1027f95436e3444091706a2d5d2087679784c96') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-232', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 93', 'మానధను డాత్మధృతి చెడి
హీనుండగు వాని నాశ్రయించుట యెల్లన్‌
మానెడు జలముల లోపల
నేనుగు మెయి దాచినట్టు లెఱుగుము సుమతీ!', 'బద్దెన', '', NULL, 'e08499b1966e4ad74ecb65bac472b8a624591cb20d82f0680b3ae0a5afcd5bef') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-233', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 94', 'మేలెంచని మాలిన్యుని,
మాలను, మొగసాలెవాని, మంగలి హితుగా
నేలిన నరపతి రాజ్యము
నేల గలసి పోవుగాని నెగడదు సుమతీ!', 'బద్దెన', '', NULL, '1c26aeedd6846d5c9a34391a37caadadf4e555499ad372c2a7c594daeb30ba58') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-234', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 95', 'రాపొమ్మని పిలువని యా
భూపాలుని గొల్వ భుక్తి ముక్తులు గలవే
దీపంబు లేని యింటను
జేపున కీళ్ళాడినట్లు సిద్ధము సుమతీ!', 'బద్దెన', '', NULL, '8196cce5b56eca48b75bc0c4f74854a1f25b43e24a85bf405417e05c023be40e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-235', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 96', 'రూపించి పలికి బొంకకు,
ప్రాపగు చుట్టంబు నెగ్గు పలుకకు మదిలో,
గోపించు రాజు గొల్వకు,
పాపపు దేశంబు సొఱకు పదిలము సుమతీ!', 'బద్దెన', '', NULL, 'da3ca487bdba63cf27ac71a8c2b8988e5662f4aa996966a4d80ddf08fac019e3') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-236', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 97', 'లావుగలవాని కంటెను
భావింపగ నీతిపరుడు బలవంతుండౌ
గ్రావంబంత గజంబును
మావటివాడెక్కినట్లు మహిలో సుమతీ!', 'బద్దెన', '', NULL, '377d23adb827ae9e02934ad9f49c228cd9c75107cf8946a31c9b8f2c3e141262') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-237', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 98', 'వఱదైన చేను దున్నకు,
కఱవైనను బంధుజనుల కడ కేగకుమీ,
పరులకు మర్మము చెప్పకు,
పిరికికి దళవాయి తనము పెట్టకు సుమతీ!', 'బద్దెన', '', NULL, '1163c4959ba970cf332da1f47bff9df159709bc9a33d78c9727e4a6db9ac73d7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-238', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 99', 'వరిపంట లేని యూరును,
దొర యుండని యూరు, తోడు దొరకని తెరువున్‌,
ధరను పతి లేని గృహమును
నరయంగా రుద్రభూమి యనదగు సుమతీ!', 'బద్దెన', '', NULL, '7ab8dd32e44da594e666fb9f16da7202a5dfbddb2f8bcc4f8d9f0767bf48dad6') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-239', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 100', 'వినదగు నెవ్వరు జెప్పిన
వినినంతనె వేగ పడక వివరింప దగున్‌
కని కల్ల నిజము దెలిసిన
మనుజుడె పో నీతిపరుడు మహిలో సుమతీ!', 'బద్దెన', '', NULL, '89219e92db39859dc6d08e1925bc174d6e659ebc3006fec596fec4a52da32431') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-240', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 101', 'వీడెము సేయని నోరును,
జేడెల యధరామృతంబు సేయని నోరున్‌,
పాడంగరాని నోరును
బూడిద కిరవైన పాడు బొందర సుమతీ!', 'బద్దెన', '', NULL, '25c94f90ceec342167ad15a99cd124e3b53aee7463e7672214e5b4dd2148a939') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-241', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 102', 'వెలయాలి వలన గూరిమి
గలగదు, మఱి గలిగెనేని కడతేఱదుగా;
బలువురు నడచెడు తెరువున
మొలవదు పువు, మొలిచెనేని పొదలదు సుమతీ!', 'బద్దెన', '', NULL, '2b2c59a24694a94454e85bb486596a11d7b6c312da2511bad9e84c248b01e2a9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-242', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 103', 'వెలయాలు చేయు బాసలు,
వెలయగ మొగసాల బొందు వెలమల చెలిమిన్‌,
గలలోన గన్న కలిమియు
విలసితముగ నమ్మరాదు వినరా సుమతీ!', 'బద్దెన', '', NULL, 'ece644be6bede1376e73008de965db6dd2e4dae5b09bf362ee594c39245c36ce') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-243', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 104', 'వేసరపు జాతి గానీ,
వీసము దా జేయనట్టి వీరిడి గానీ,
దాసి కొడుకైన గానీ,
కాసులు గల వాడె రాజు గదరా సుమతీ!', 'బద్దెన', '', NULL, 'eafb36421e6a36d74d4fb49b55938d6563e8e22cc1a2c1af3d1e09cba44c9194') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-244', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 105', 'శుభముల పొందని చదువును,
నభినయముగ రాగరసము నందని పాటల్‌,
గుభ గుభలు లేని కూటమి,
సభ మెచ్చని మాటలెల్ల జప్పన సుమతీ [105]', 'బద్దెన', '', NULL, 'ffb698ed1b7d9162adec1e2ce2dfbc19dade601d4d509cd216bcfe8dff6b2cda') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-245', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 106', 'సరసము విరసము కొఱకే,
పరిపూర్ణ సుఖంబు లధిక బాధల కొఱకే,
పెరుగుట విరుగుట కొఱకే,
ధర తగ్గుట హెచ్చు కొఱకె తథ్యము సుమతీ!', 'బద్దెన', '', NULL, 'b813b88cf162dac5f1f5d40be76eb1dc3f0fc4562b3bb4daa75d1ba31281c18d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-246', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 107', 'సిరి తా వచ్చిన వచ్చును
సరళముగ నారికేళ సలిలము భంగిన్‌,
సిరి తా బోయిన బోవును
కరి మ్రింగిన వెలగ పండు కరణిని సుమతీ!', 'బద్దెన', '', NULL, 'dd010d265205a8027a538f52a3861a1272fc49d518b0f01c8a19f652cb26180b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-247', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 108', 'స్త్రీల యెడ వాదులాడకు,
బాలురతో జెలిమిచేసి భాషింపకుమీ,
మేలైన గుణము విడువకు,
మేలిన పతి నింద సేయ కెన్నడు సుమతీ!', 'బద్దెన', '', NULL, '2a2a93df12f811cbc0af7a8a505723863c2919a3aeb1577f452ce5b5877dd452') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-248', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 109', 'అడియాసకొలువు గొలువకు
గుడిమణియము సేయబోకు కుజనుల తోడన్
విడువక కూరిమి సేయకు
మడవిని దొడరయ కొంటి నరగకు సుమతీ!', 'బద్దెన', '', NULL, '757f873603b15057681ef2befeee2b49ed0f766b1780775bd5180f1c4bd51c66') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-249', 'శతకాలమాల', 'జ్ఞానమాల', 'పద్యం 110', 'కనకపు సింహాసనమున
శునకము గూర్చుండబెట్టి శుభలగ్నమున
దొనరగ బట్టము గట్టిన
వెనుకటి గుణమేల మాను వినరా సుమతీ!', 'బద్దెన', '', NULL, '855c3d92612cece4bc522bc4f401c0a770d6d3e5c84dad4aa0906160a6c58018') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-250', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 1', 'శార్దూలవిక్రీడితము

   వాణీవల్లభ దుర్లభంబగు భవద్ద్వారంబున న్నిల్చి ని
   ర్వాణశ్రీఁ జెఱపట్టజూచిన విచారద్రోహమో నిత్యక
   ల్యాణక్రీడలఁబాసి దుర్దశలపాలై రాజలోకాధమ
   శ్రేణీద్వారము దూరఁజేసెదిపుడో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నిత్యమూ దుర్దశల పాలు చేయునట్టి రాచవిలాసములయందు తనివి చాలించి నేను నీ ద్వారము ముందు నిలిచి ఉన్నాను ప్రభో. బ్రహ్మదేవునికైనా దుర్లభంబైన మోక్షమును గోరుచున్నాను.', 'ధూర్జటి', '', NULL, 'af654ef2d4e6753e05ce8bcc92d74a707d86fb16dd9cc5d3a9032ddf4461cccb') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-251', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 2', 'శార్దూలవిక్రీడితము

   అంతామిథ్య తలంచిచూచిన నరుండట్లౌటెఱింగిన్‌ సదా
   కాంతల్పుత్రులు నర్థమున్‌ తనువు నిక్కంబంచు మోహార్ణవ
   భ్రాంతింజెంది చరించుఁగాని పరమార్థంబైన నీయందుఁ దాఁ
   జింతాకంతయుఁ జింతనిల్పఁడు గదా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ప్రపంచమంతా మిథ్య అని తెలిసి కూడా సంసారభవభందనములు వీడలేక కాంతాపుత్రనిజగృహ మోహమును విడిచి నీయందు ఒక చింత ఆకు సమమైన భక్తిని కూడా నిలపడు కదా ప్రభో కాళహస్తీశ్వరా!', 'ధూర్జటి', '', NULL, '8dcb31539b225d26f43f090b2b8ff5fee083de5d20464250f7620bf52616dd24') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-252', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 3', 'శార్దూలవిక్రీడితము

   నీనా సందొడబాటు మాట వినుమా! నీచేత జీతంబునేఁ
   గానింబట్టక సంతతంబు మదివేడ్కన్గొల్తు నంతస్సప
   త్నానీకంబున కొప్పగింపకుము నన్నాపాటియే చాలుఁదే
   జీనొల్లం గరినొల్ల నొల్లసిరులన్‌ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో శ్రీకాళహస్తీశ్వరా! నీకూ నాకూ, ఒక ఒడబాటు మాట వినుము. నేను జీతమూ, భత్యమూ లేక నిన్ను సేవించెదను. నన్ను పగవారికి (నరకానికి) ఒప్పగించవద్దు. ఇది ఒక్కటే నా కోరిక. నేను అది తప్ప వేరొకటి అడుగను, నాకు జీవితము వద్దు, సిరులు, హస్తిశ్రేణి వద్దు.', 'ధూర్జటి', '', NULL, 'fb5cca4b6c290902f143e793873f578a884865ab1b777c8192995ed79b0aeec6') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-253', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 4', 'మత్తేభవిక్రీడితము

    భవకేళీ మదిరామదంబున మహాపాపాత్ముఁడై వీఁడు న
    న్ను వివేకింపఁడటంచు నేను నరకార్ణోరాశిపాలైనఁ బ
    ట్టవు? బాలుండొకచోట నాటతమితోడన్నూతఁ గూలంగఁ దం
    డ్రి విచారింపకయుండునా కటకటా! శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో శ్రీకాళహస్తీశ్వరా! భవబంధములు చుట్టుముట్టి నేను మాయలో మునిగి, మదిరాసక్తుడినై నిన్ను పట్టకుండా చరించువాడను అగుదునేని, నన్ను నీవు ఉపేక్షించుట భావ్యమా? అట్లు ఉపేక్షించి నన్ను మహాపాపాత్ముడిని నరకము పాలు చేయుట తగునా? బాలుడు తెలియక ఆటలాడుచూ నూతిలో పడిన, అతని గన్నతండ్రి విచారింపక, దండించునా?', 'ధూర్జటి', '', NULL, '97b0af5623c22ba5e3f75825ef02facbcb20e6eb6694b0420fa99197196694f7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-254', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 5', 'శార్దూలవిక్రీడితము

    స్వామిద్రోహముఁజేసి యేనొకని గొల్వంబోతినో కాక నే
    నీమాటన్విన నొల్లకుండితినొ నిన్నేదిక్కుగాఁ జూడనో
    యేమీ యిట్టి వృథాపరాధినగు నన్నీ దుఃఖవారాశి వీ
    చీమధ్యంబున ముంచియుంపఁదగునా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో శ్రీకాళహస్తీశ్వరా! నేనేమి స్వామిద్రోహము చేసితినని నమ్మితివో, లేక నీమాటను వినలేదని ఊరకుండితివో, లేక దేనికీ కొరగాకుంటినని కినుక బూనితివో కానీ నన్ను ఇవ్విధంబుగా దుఃఖ సముద్రమునందు పడవైచి నీవు ఊరకుండుట నీకు న్యాయమా?', 'ధూర్జటి', '', NULL, '1592777c7f5ce338d476c2e5697ceb9985a8a33a8bd7ade4f3b10aadc0595e23') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-255', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 6', 'మత్తేభవిక్రీడితము

    దివిజక్ష్మారుహధేనురత్న ఘనభూతి ప్రస్ఫురద్రత్న సా
    నువు నీ విల్లు, నిధీశ్వరుండు సఖుఁ, డర్ణోరాశి కన్యావిభుం
    డు విశేషార్చకుఁ డింక నీకెన ఘనుండుం గల్గునే నీవు చూ
    చి విచారింపవు లేమి నెవ్వఁడుడుపున్‌ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో శ్రీకాళహస్తీశ్వరా! నీ ఐశ్వర్యము అంతింత గాదు. కల్పవృక్షము, కామధేనువు నీ సంపద, రత్నఖచితమైన విల్లు నీ స్వంతము. కుబేరుడు నీ స్నేహితుడు. నీ అర్చకుడు సాక్షాత్ శ్రీమహావిష్ణువు. అట్టి నీవు చూసి విచారించకయున్న ఎవ్వడు మా దారిద్ర్యమును పోగొట్టును ప్రభో?', 'ధూర్జటి', '', NULL, '95d47d76ae0854fac0d6ac1e2edd414ddf8cc8be5570eb31e53b75d077dc52a2') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-256', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 7', 'శార్దూలవిక్రీడితము

    నీతో యుద్ధముఁ జేయనోప, గవితా నిర్మాణశక్తిన్నినుం
    బ్రీతుంజేయఁగలేను, నీకొఱకుఁ దండ్రిం జంపఁగాజాల నా
    చేత న్రోకట నిన్ను మొత్త వెఱతుం జీకాకు నాభక్తియే
    రీతి న్నాకిఁక నిన్నుఁ జూడఁగలుగున్‌ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో శ్రీకాళహస్తీశ్వరా! అర్జునుని మాదిరి నీతో యుద్ధము చేయలేను, నత్కీరుడు తదితర కవుల మాదిరి నిన్ను నా కవితా శక్తితో సంప్రీతున్ని చేయలేను, ఒకానొక శివభక్తునివలె తండ్రిని జంపలేను; మరొక్క శివభక్తురాలి వలె నిన్ను రోకలితో మొత్తలేను. నా భక్తియే నాకు అడ్డమై నీ దయను పొందనీయకున్నది. నిన్ను జూచెడి అవకాశమింక నాకెట్లు కలుగును?', 'ధూర్జటి', '', NULL, 'a19da87351263c17f597a15c4ebe4d85b6c1a8d7eabede6b7118f5d486fa8d74') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-257', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 8', 'మత్తేభవిక్రీడితము

    ఆలుంబిడ్డలు దలిదండ్రులు ధనంబంచు న్మహాబంధనం
    బేలా నామెడఁగట్టినాఁడవిఁక నిన్నేవేళఁ జింతింతు ని
    ర్మూలంబైన మనంబులోనఁ గడుదుర్మోహాబ్ధిలోఁ గ్రుంకి యీ
    సీలామాలపుఁజింత నెట్లుడిపెదో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో శ్రీకాళహస్తీశ్వరా! భార్యాపుత్రులు, తల్లిదండ్రులు, ధనములు అనెడి పాశములను నా మెడకు చుట్టినావేమి? ఈ వ్యామోహములో బడి నిన్ను నేనెట్లు స్మరింపగలను? ఈ భరింపరాని దుఃఖము నెట్లు పోగొట్టెదవో కదా?', 'ధూర్జటి', '', NULL, '8ce28158459b2a6c409e78432f4f8d795b89d217306d7d5214d7b338de63bd8a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-258', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 9', 'శార్దూలవిక్రీడితము

    నిప్పై పాతకతూల శైలమడఁచు న్నీనామమున్మానవుల్‌
    తప్పన్‌ దవ్వులవిన్న నంతకభుజాదర్పోద్ధత క్లేశముల్‌
    తప్పుందారును ముక్తులౌదురని శాస్త్రంబుల్మహాపండితుల్‌
    చెప్పంగాఁ దమకింక శంకవలెనా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో శ్రీకాళహస్తీశ్వరా! నీ నామమును స్మరించినంతనే కొండలవంటి పాపములు నశించుననియు, యముని వల్ల కలుగు నరకబాధలు తప్పుననియు వేదశాస్త్రములు, పండితులు చెప్పుచుండగా ఈ మానవులకింకను సందేహమెందుకు?', 'ధూర్జటి', '', NULL, 'd10b5f74261e973c274194f1879eeba4dc59aea19dee65b714800c9a7e90e134') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-259', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 10', 'శార్దూలవిక్రీడితము

    వీడెంబబ్బినయప్పుడుం దమ నుతుల్విన్నప్పుడుం బొట్టలోఁ
    గూడున్నప్పుడు శ్రీవిలాసములుపైకొన్నప్పుడుం గాయకుల్‌
    పాడంగా వినునప్పుడున్‌ జెలగు దంభప్రాయవిశ్రాణన
    క్రీడాసక్తుల నేమి చెప్పవలెనో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో శ్రీకాళహస్తీశ్వరా! తమకు భోగములు అబ్బినప్పుడు, తమను వేఱెవ్వరో పొగిడినప్పుడు, కడుపునిండా తిండి ఉన్నప్పుడు, సమస్త విలాసములు చేకూరినప్పుడు, గాయకులు పాడుచున్నప్పుడు, తమ గొప్పదనమును చూపించుకొనుటకు ఆడంబరములకు పోయి దానధర్మములు చేయువారిని ఏమందునో కదా?', 'ధూర్జటి', '', NULL, '31388ff42bcbe95ddc8ac34790958ffbff67eaba5da081f1674d941e7b32fe8f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-260', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 11', 'మత్తేభవీక్రీడితము

    నిను సేవింపగ నాపదల్ పొడమనీ, నిత్యోత్సవం బబ్బనీ
    జనమాత్రుండననీ, మహాత్ము డననీ, సంసార మోహంబు పై
    కొననీ, జ్ఞానము గల్గనీ, గ్రహగతుల్ కుందింపనీ, మేలు వ
    చ్చిన రానీ, యవి నాకు భూషణములే, శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో శ్రీకాళహస్తీశ్వరా! నేను నిన్ను సేవించుచున్నప్పుడు, నాకు ఆపదలే రానీ, లేక సుఖములు కలగనీ, సామాన్యమానవుడు అని జనులు అనుకొననీ లేక మహాత్ముడు అని పొగడనీ, సంసారము మీద మోహము కలగనీ లేక వైరాగ్యమబ్బనీ, గ్రహములు అద్దము తిరగనీ లేక మంచి జరగనీ అవి నాకు మంచే చేయునని భావించెదను.', 'ధూర్జటి', '', NULL, 'd9890cacaf5036ac6cf1bac54d1a661348271c5f6f2bb5fc8c7c4291581ed025') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-261', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 12', 'శార్దూలవిక్రీడితము

    ఏ వేదంబు పఠించె లూత? భుజంగ బే శాస్త్రముల్ సూచె దా
    నే విద్యాభ్యసనం బొనర్చెగరి; చెంచే మంత్ర మూహించె? బో
    ధావిర్భావ నిదానముల్ చదువులయ్యా? కావు;  నీ పాద సం
    సేవాసక్తియే కాక జంతు తతికిన్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో శ్రీకాళహస్తీశ్వరా! సాలెపురుగు ఏ వేదములు పఠించినది? పాము ఏ శాస్త్రములు చదివినది? ఏనుగు ఏ విద్యలు నేర్చినది? బోయవాడు ఏ మంత్రములు నేర్చినాడు? వేదవిద్యాతతులవల్లనా ప్రభో మోక్షము సాధింపదగినది? నీ పాద సేవాసక్తి ఉన్న చాలదా?', 'ధూర్జటి', '', NULL, 'f28ab908274064e7c76125186fc15f353b4bde6e730ff9cccf8b62463271d2b2') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-262', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 13', 'శార్దూలవిక్రీడితము

    కాయల్గాచె వధూ నఖాగ్రములచే గాయంబు, వక్షోజముల్
    రాయన్ ఱాపడె ఱొమ్ము, మన్మథవిహారక్లేశ విభ్రాంతిచే
    బ్రాయంబాయెను, బట్టగట్టె దల, చెప్పన్ రోత సంసారమే
    జేయంజాల విరక్తు జేయ గదవే శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో శ్రీకాళహస్తీశ్వరా! స్త్రీల గోళ్ళగాటులచే నా శరీరము కాయలు గాచినది. వారి స్తనముల రాపిడిచే నా రొమ్ము రాయివలె గట్టిపది పోయినది. మన్మథక్రీడలందలి వ్యామోహములో బడి వయసు గడిచిపోయినది. తల బట్టతలయై వెంట్రుకలు రాలిపోయినవి. చెప్పగా సంసారమే ఒక రోత కదా. ఇకనైనా నాకు విరక్తిని కలుగచేసి నన్ను కాచు.', 'ధూర్జటి', '', NULL, '594684ffbaceb28eb440cfb5127c3048d00c6f3c63e90fc36553486b4604f2a4') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-263', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 14', 'శార్దూలవిక్రీడితము

    నిన్నే రూపముగా భజింతు మదిలో నీ రూపు మోకాలో? స్త్రీ
    చన్నో? కుంచమొ? మేక పెంటియొ? యీ సందేహముల్ మాపి, నా
    కన్నారన్ భవదీయమూర్తి సగుణాకారంబుగా జూపవే
    చిన్నీరేజ విహారమత్త  మధుపా!  శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో శ్రీకాళహస్తీశ్వరా! మోకాలో (అర్జునునికి శ్రీకృష్ణుడు తన మోకాలిని చూపి అందు శివలింగమును గాంచమనినది), స్త్రీ యొక్కస్తనమో (ఒక మహారాజు వేశ్యాలోలుడయ్యి కూడా వేశ్య స్తనములో శివున్ని చూసినట్టు), కుంచమొ (కుంచేశ్వరుడు అని పేరు ఆ లింగమునకు), మోకపెంటియో (కోటయ్య అను గొల్లవాడు మేకపెంటికను శివలింగాకృతిగా భావించి పూజించగా అది కోటేశ్వరలింగముగా మారినట్లు) నీ రూపము ఏదని నమ్మి భావించి సేవింతును? నా యీ సందేహములన్నియు పోగొట్టి నీ సగుణమూర్తిని నాకు చూపి ధన్యుని జేయుము ప్రభో.', 'ధూర్జటి', '', NULL, '1678cdbd3fa8dea74d1d2f593290f7abcbeb2575cc1b35b60176884f3f759fb6') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-264', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 15', 'శార్దూలవిక్రీడితము

    నిను నావాఁకిలి గావుమంటినొ? మరున్నీలాలకభ్రాంతిఁ గుం
    టెన పొమ్మంటినొ? యెంగిలిచ్చి తిను తింటేఁగాని కాదంటినో
    నిను నెమ్మిందగ విశ్వసించు సుజనానీకంబు రక్షింపఁ జే
    సిన నావిన్నపమేల గైకొనవయా! శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో శ్రీకాళహస్తీశ్వరా! బాణాసురునివలె నిన్ను నా వాకిట కాపలా ఉండమంటినా? దేవతా స్త్రీవ్యామోహముచే వారి వద్దకు వెళ్ళమంటినా? భక్తకన్నప్ప మాదిరి ఎంగిలి తిండి తినమంటినా? సజ్జనులను మన్నింపమనిన నా విన్నపమునేల గైకొనవు ప్రభో?', 'ధూర్జటి', '', NULL, '3bc2e64e3f827a9c94325f1f464959ca26232d7abf58845cdff17e16d51fa61a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-265', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 16', 'శార్దూలవిక్రీడితము

    ఱాలన్ రువ్వఁగ చేతులాడవు, కుమారా! రమ్మురమ్మంచునే
    చాలన్ చంపగ, నేత్రముల్దివియగా శక్తుండనేఁ గాను,నా
    శీలంబేమని చెప్పనున్న దిక నీ చిత్తంబు, నా భాగ్యమో
    శ్రీ లక్ష్మీపతి సేవితాంఘ్రియుగళా! శ్రీ కాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో శ్రీకాళహస్తీశ్వరా! ఒక కిరాతకుడు పూలులేవని రాళ్ళతో పూజించినట్లు నేను చేయలేను. భక్తసిరియాళునివలె కుమారుని చంపి వంటచేసి నీకు నైవేద్యమిడలేను. భక్తకన్నప్ప మాదిరి నేను నీకు నా నేత్రములను సమర్పించలేను. నా భక్తి ఎంత గొప్పదో చెప్పవలెనన్న అది నీ చిత్తము, నా భాగ్యము. సాక్షాచ్ఛ్రీమన్నారణుని చేత సేవింపబడు పాదములు కలిగినట్టివాడా!', 'ధూర్జటి', '', NULL, 'a92dd17f16daeae7ce3ee045ed699d315bc8dd425aca1f880e9769d44d441560') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-266', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 17', 'శార్దూలవిక్రీడితము

    రాజుల్మత్తులు, వారి సేవ నరకప్రాయంబు, వారిచ్చు నం
    భోజాక్షీ చతురంత యాన తురగీ భూషాదులాత్మ వ్యధా
    బీజంబుల్, తదపేక్ష చాలుఁ, పరితృప్తింబొందితిన్, జ్ఞానల
    క్ష్మీ జాగ్రత్పరిణామ మిమ్ము, దయతో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! రాజులు ఉన్మత్తులు, వారి సేవ నరకతుల్యము. వారిచేత నేను పొందు వనితా, విత్త, యానములు వృథా పరికరములు. వాటియందు తనివి చాలించితిని. నాకు నీ దయ చేత జ్ఞానలక్ష్మి యబ్బి, తెలివినొందెదను గాక.', 'ధూర్జటి', '', NULL, 'b16ac97bd17e0ae34cd84d30b9f516c710e64cf3ed2237266800cb44d4811528') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-267', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 18', 'శార్దూలవిక్రీడితము

    నీ రూపంబు దలంపగాఁ తుదమొదల్నేగాన, నీవై నచో
    రా రా రమ్మని యంచుఁ చెప్పవు, వృథారంభంబులింకేటికిన్
    నీరన్ముంపుము పాలముంపు మిక నిన్నే నమ్మినాడం జుమీ
    శ్రీ రామార్చిత పాదపద్మయుగళా! శ్రీ కాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నీ రూపము ఊహించవలెనన్న దాని అద్యంతములు నాకు తెలియవు. నీవు నన్ను రమ్మని పిలవవు. ఇంక ఏటికి ఈ పాట్లు? నీట ముంచినా, పాల ముంచినా నీదే భారమని నేను నమ్మితిని. శ్రీరామచంద్రుడు నమ్మిన నీ పాదయుగళమునే నేను కూడా నమ్మితి ప్రభో.', 'ధూర్జటి', '', NULL, '963f18983b8dc51966066bb4d390ed71868900b23aa5d239bffc7638a55210ef') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-268', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 19', 'శార్దూలవిక్రీడితము

    నీకున్, మాంసము వాంఛయేని కఱవా? నీ చేత లేడుండగా
    జోకైనట్టిగా కుఠారముండ, ననలజ్యోతుండ, నీరుండగా
    పాకరంబొప్ప ఘటించి, చేతిపునుకన్ భక్షింప కా బోయచేఁ
    చేకొంటెంగిలి మాంసమిట్లు తగునా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! మాంసమే నీకు రుచించిన, నీకేమి కఱువు? నీ చేతియందు లేడి కలదు. ఇంకొక చేతియందు వాడియైన కుఠారమున్నది. ముఖమున అగ్నిలీను కన్ను ఉన్నది. తలపై గంగ ఉన్నది. ఈ సామగ్రి గల నీవు శుచిగా వండుకొని నీ చేతిలోనే ఉన్న పుఱ్ఱెలో తినక ఒక బోయవాని ఎంగిలికూటినేల తగొంటివి? (భక్త పరాధీనుడవైన నీకు ఇది ఆ బోయయందు కల వాత్సల్యమే కాని మఱొండు కాదని కవి నిందాస్తుతి.)', 'ధూర్జటి', '', NULL, '11be5a7c330fc52d7c2da7fb21a801d63ca42c86fbab6aa5cf815b1ebfe87bd9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-269', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 20', 'శార్దూలవిక్రీడితము

    రాజై దుష్కృతిజెందెఁ జందురుఁడు రారాజై కుబేరుండు దృ
    గ్రాజీవంబునఁగాంచె దుఃఖము కురుక్ష్మాపాలుఁడామాటనే
    యాజింగూలె సమస్త బంధువులతో నా రాజశబ్దంబు చీ,
    చీ జన్మాంతరమందు నొల్లనుజుమీ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! రాజులై చంద్రుడు మచ్చబడినాడు, కుబేరుడు రావణుని చేతిలో ఒడి ఏకాక్షి అయినాడు. దుర్యోధనుడు యుద్ధమునందు సమస్త బంధువులతో గూడి మరణించినాడు. నా జన్మజన్మాంతరములయందు కూడా నేను రాజశబ్దమును ఒల్లను, నిన్ను తత్పదవి కొఱకు యాచించను దేవా.', 'ధూర్జటి', '', NULL, '64eabdaf2c7aa281e83e957811ac700cdf040fff31ca4f2e00d3a7a697701510') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-270', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 21', 'శార్దూలవిక్రీడితము

    రాజర్థాతురుఁడైనచో నెచట ధర్మంబుండు నేరీతి నా
    నాజాతి క్రియలేర్పడున్‌ సుఖము మాన్యశ్రేణి కెట్లబ్బు రూ
    పాజీవాళికి నేది దిక్కు ధృతి నీభక్తుల్‌ భవత్పాదనీ
    రేజంబుల్‌ భజియింతురే తెఱఁగునన్‌ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! రాజు ధనలోభి అయిన, ధర్మమెక్కడుండును? వర్ణాశమ పద్దతి ఎట్లు నిలబడును? బ్రాహ్మణులు సుఖముగా ఎట్లు జీవించగలరు? ఆఖరికి వేశ్యావృత్తులవారికి దిక్కేది? నీ పాదసేవాతత్పరులగు భక్తులు నిర్భయముగా నీ మీద ఎట్లు మనస్సు లగ్నము చేయగలరు? ప్రభో!', 'ధూర్జటి', '', NULL, '727d67de4d10e10eafe439428ad4cc4062e131c9aabc3424fb79d5497bd8c774') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-271', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 22', 'శార్దూలవిక్రీడితము

    తరఁగల్‌ పిప్పల పత్త్రముల్‌ మెఱుఁగుటద్దంబుల్‌ మరుద్దీపముల్‌,
    కరికర్ణాంతము లెండమావులతతుల్‌ ఖద్యోత కీట ప్రభల్‌
    సురవీథీ లిఖితాక్షరంబు లసువుల్‌ జ్యోత్స్నాపయఃపిండముల్‌
    సిరులందేల మదాంధులౌదురు జనుల్‌ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! మనిషి ప్రాణములు నీటి కెరటముల వంటివి, రావిచెట్టు ఆకులవంటివి, మెఱుగు దిద్దిన అద్దములవంటివి, గాలిలోని దీపకళికలవంటివి, ఏనుగు చెవులవంటివి, ఎండమావులవంటివి, మిణుగురుపురుగుల వంటివి, ఆకాశపు అక్షరములవంటివి, వెన్నెలముద్దల వంటివి. అట్టి అశాశ్వతమైన జీవితములలో సిరులను చూసి జనాలు ఏల మదాంధకారులవుచున్నారు? ప్రభో?', 'ధూర్జటి', '', NULL, '30d6a4776370645ecbdba61afce9871debf3e20cdd93c735f1d65c798686a140') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-272', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 23', 'శార్దూలవిక్రీడితము

    నిన్నున్నమ్మినరీతినమ్మనొరులన్‌, నీకన్న నాకెన్నలే
    రన్నల్దమ్ములు తల్లిదండ్రులు గురుండాపత్సహాయుండు నా
    యన్నా! యెన్నడు నన్ను సంస్కృతి విషాదాంభోధి దాఁటించి య
    చ్ఛిన్నానంద సుఖాబ్ధిఁ దేల్చెదొ కదే శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నిన్ను నమ్మిన విధముగా నేను ఇంకొకరిని నమ్మను, నాకు నీకన్నా ఎన్నదగిన అన్నతమ్ములు, తల్లిదండ్రులు, గురువులు, స్నేహితులు లేరు. ఎప్పుడు నన్ను ఈ సంసార సాగరము దాటించి మోక్షసుధావారాశి చేర్చెదవో కదా. ప్రభో!', 'ధూర్జటి', '', NULL, '4cb9973c084c71f587916e88bc614462b4471eb5e1454caf9649f1c0f6600f62') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-273', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 24', 'శార్దూలవిక్రీడితము

    నీపంచం బడియుండఁగాఁ గలిగిన న్భిక్షాన్నమే చాలు ని
    క్షేపంబబ్బిన రాజకీటముల నే సేవింపఁగా నోప నా
    శాపాశంబులఁజుట్టి త్రిప్పకుము సంసారార్థమై బంటుగాఁ
    జేపట్టం దయగల్గెనేని మదిలో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నీచెంత నాకు భిక్షాన్నమైనా చాలును. నిధులు కలిగినా సరే నేను రాజాధముల సేవ చేయనోపను. సంసారమను ఆశాపాశాములందు నన్ను బంధింపక నీ బంటుగా చేర్చుకొని రక్షించు ప్రభో!', 'ధూర్జటి', '', NULL, '8049bdf7e2784f68b2312c7ce6a44e690f4699de82914f4194bd4fadab52fd09') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-274', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 25', 'శార్దూలవిక్రీడితము

    నీపేరున్‌ భవదంఘ్రితీర్థము భవన్నిష్ఠ్యూత తాంబూలముల్‌
    నీ పళ్ళెంబు ప్రసాదముంగొనికదా నే బిడ్డఁడైనాఁడ న
    న్నీ పాటిం గరుణింపు మోపనిఁక నేనెవ్వారికిం బిడ్డఁగాన్‌
    జేపట్టందగుఁ బట్టి మానఁదగదో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నీపేరు పెట్టుకుని, నీ పాదతీర్థ సేవనము చేసి, నీ ఎంగిలి తాంబూలము, నీ శేషప్రసాదము తిని కదా నేను బిడ్డనైతిని. అట్టి నన్ను నీవు కరుణ చూడని వేళ, నేను ఎవ్వరికి బిడ్డనగుదును ప్రభో. నీవీ విధముగా నన్ను పట్టుకొని మరలా విడిచిపెట్టుట న్యాయమా తండ్రీ?', 'ధూర్జటి', '', NULL, 'd4b3b515d7401e137ec836417f3059b198ed06e0b86ced101f77cc56f256cf57') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-275', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 26', 'శార్దూలవిక్రీడితము

    "అమ్మా! యయ్య!" యటంచునెవ్వరిని నేనన్నన్శివా! నిన్ను నే
    సుమ్మీ నీ మదిఁ తల్లిదండ్రులనటంచు న్జూడఁగాఁబోకు నా
    కిమ్మైఁ దల్లియు దండ్రియున్‌ గురుఁడు నీవేకాన సంసారపుం
    జిమ్మంజీకటిఁగప్పకుండఁ గనుమా! శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! అమ్మా, అయ్యా అని నేను ఎవ్వరిని పిలిచినా అది వేరే ఎవరినో అని నీ మదిలో చూడబోకు. ఈ జన్మకు నాకు తల్లీ, తండ్రీ, గురువు, దైవమూ అన్నీ నిన్నుగానే భావించినాను. అట్టి నీవే ఈ సంసారము అనే పెను చీకటి నన్ను ముంచివెయ్యకుండా కాపాడు. ప్రభో!', 'ధూర్జటి', '', NULL, '925de5dcd4c15680914ea82fbab7eabcbe24eb97e16ccf70b027d42f1603868c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-276', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 27', 'మత్తేభవిక్రీడితము

    కొడుకుల్‌ పుట్టరటంచు నేడ్తురవివేకు ల్జీవనభ్రాంతులై
    కొడుకుల్‌ పుట్టరె కౌరవేంద్రున కనేకుల్‌ వారిచే నేగతుల్‌
    వడసెం బుత్రులులేని యా శుకునకున్‌ వాటిల్లెనే దుర్గతుల్‌
    చెడునే మోక్షపదం బపుత్రకునకున్‌ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! కొడుకులు లేరు అని జీవితము మీది అనురాగముతో అవివేకులై జనులు ఏడ్చెదరు. ధృతరాష్ట్రునికి ౧౦౦ మంది కొడుకులు కలిగికూడా ఏ గతులు పొందినవాడయ్యెను. కొడుకులు లేని శుకమహర్షికి దుర్గతులు కలుగలేదు కదా ప్రభో!', 'ధూర్జటి', '', NULL, 'e237c59fc82d8ee45c0522654827fa5a27e8d7e983e2694071c1d7111e2ea31c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-277', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 28', 'మత్తేభవిక్రీడితము

    గ్రహదోషంబులు దుర్నిమిత్తములు నీ కల్యాణనామంబు ప్ర
    త్యహముంబేర్కొను నుత్తమోత్తముల బాధంబెట్టగానోపునే
    దహనుం గప్పఁగఁజాలునే శలభసంతానంబు నీ సేవఁజే
    సి హతక్లేశులుగారుగాక మనుజుల్‌ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఎన్ని గ్రహబాధలు కానీ, దుశ్శకునములు కానీ, నీ నామస్మరణము నిరంతరమూ చేయు భక్తుని ఏమీ చేయనోపవు. ఎన్ని మిడతల మందల చేతనైననేమి అగ్నిని కప్పి ఉంచ శక్యమా? నీ సేవ చేసి పాపములు బాయరు కదా జనులు మూఢులై , ప్రభో!', 'ధూర్జటి', '', NULL, '3cb3fbf1e6a4a4791ebf4fd2178ee484932bd08410bf264d94aec621f878e325') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-278', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 29', 'మత్తేభవిక్రీడితము

    అడుగంబోనిఁక నన్యమార్గరతులం బ్రాణావనోత్సాహినై,
    యడుగంబోయినఁబోదు నీదు పదపద్మారాధకశ్రేణియు
    న్నెడకున్నిన్ను భజింపఁగాఁ గనియు నాకేలా పరాపేక్ష కో
    రెడిదింకేమి? భవత్ప్రసాదమె తగున్‌ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నా ప్రాణములు రక్షింపగోరి నేను నీ భక్తి తప్ప అన్యమార్గములను ఆశ్రయించను. ఒకవేళ ఆశ్రయించినా నీ పాదపద్మభజనతత్పరులైన పరమశైవులను భజించెదను. నీ అనుగ్రహమే ఉన్న నాకు వేరొండు పదార్థములయందు వాంఛ ఏల కలుగును? ప్రభో!', 'ధూర్జటి', '', NULL, 'd9dca1277e85b3aad387dc3d1837298c006f92c22907516f86fdaa05824fcfd3') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-279', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 30', 'మత్తేభవిక్రీడితము

    అదమాతంగము లందలంబులు హరుల్మాణిక్యము ల్పల్లకుల్‌,
    ముదితల్‌, చిత్రదుకూలము ల్పరిమళంబు ల్మోక్షమీఁజాలునేఁ
    మదిలో వీని నపేక్ష సేసి నృపధామ ద్వారదేశంబుఁగా
    చి దినంబుల్‌ వృథపుత్తురజ్ఞులకటా! శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! మదించిన ఏనుగులు, అందలములు, మణిమాణిక్యములు, పల్లకీలు, అందమైన వనితలు, చిత్రవిచిత్రమైన వస్త్రములు, పరిమళలేపనంబు కానీ, ఇవేవైననూ మొక్షమును ప్రసాదింపనొపంపుడు, వీటినాపేక్షించి రాజుల ఇంటివాకిళ్ళముందు దినములు వృథాగా ఎలా గడుపుదురు ప్రభో ఈ జనులు సత్యమూర్తివైన నీ ధ్యానము చేయక.', 'ధూర్జటి', '', NULL, '7fdfac153f431cbc606181c15eb3a70df545ad25f033a5db3ddfe991d3f1bc2e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-280', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 31', 'శార్దూలవిక్రీడితము''

    రోసీరోయదు కామినీజనుల తారుణ్యోరుసౌఖ్యంబులన్‌
    బాసీపాయదు పుత్త్రమిత్రజన సంపద్భ్రాంతి వాంఛాలతల్‌
    కోసీకోయదు నా మనంబకట! నీకుం బ్రీతిగా సత్క్రియల్‌
    చేసీచేయదు దీనిత్రుళ్ళణఁపవే శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! స్త్రీరతియందు, పుత్రామిత్రబాంధవులయందు నాకు తనివితీరినట్టే ఉండి మరల మరల కలుగుచున్నది. ఇటువంటి మనస్సును నాకు ఎందుకు ప్రసాదించితివి. నీ సేవానుతినతిసపర్యలు చేసి కూడా వాటిమీద మనస్సు నిలువదే. ఈ సంసారబంధలతలను వేగముగా త్రెంపి నన్ను కాపాడు ప్రభో!', 'ధూర్జటి', '', NULL, '76106981e13dd316a098389df33305d9f03ca9efcf42bd1ec09e93d82cf91705') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-281', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 32', 'శార్దూలవిక్రీడితము

    ఎన్నేళ్ళుండితి నేమిగంటినిఁక నే నెవ్వారి రక్షించెదన్‌
    నిన్నే నిష్ఠ భజించెద న్నిరుపమోన్నిద్రప్రమోదంబు నా
    కెన్నండబ్బెడు నెంతకాలమిఁక నేనిట్లున్న నేమయ్యెడిం
    జిన్నంబుచ్చక నన్ను నేలుకొనవే శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఇన్నాళ్లుగా జీవించి ఏమి సాధించితిని? ఎవరిని రక్షించితిని? ఇన్నాళ్లుగా ఉన్న నన్ను ఏలుకొని నిర్మలానంద మోక్షమును చేకూర్చు స్వామీ!', 'ధూర్జటి', '', NULL, '924cc44072eeed00eaddc00b09db5724c686897486b6f6539a5e61f8d2c91fba') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-282', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 33', 'శార్దూలవిక్రీడితము

    చావంకాలము చేరువౌటెఱిఁగియుం జాలింపఁగా లేక త
    న్నేవైద్యుండు చికిత్సఁబ్రోవగలఁడో? యేమందు రక్షించునో?
    యే వేల్పుల్‌కృపఁజూతురో?యనుచు నిన్నింతైనఁ జింతింపఁడా
    జీవచ్ఛ్రాద్ధముఁజేసికొన్న యతియున్‌ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! జీవితము మీద చింత తీర్పనోపడి కదా. ఒక సామాన్య గృహస్థుయే కాక జీవన్ముక్తినపేక్షించి తన శ్రాద్ధకర్మను తనే చేసుకొన్న సన్న్యాసి కూడా మరణకాలమందు నిన్నెఱుగక తనను ఏ వైద్యుడు రక్షించునో, ఏ మందు బాగు చేయునో, ఏ దేవతలు రక్షించెదరో అనే ఆలోచిస్తాడు కదా ప్రభో!', 'ధూర్జటి', '', NULL, 'da1a5db0a30188d34a4c1e7f69256d97744296e26ae1cc0c2235bf0d90316afb') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-283', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 34', 'మత్తేభవిక్రీడితము

    దినముంజిత్తములో సువర్ణముఖరీతీరప్రదేశామ్ర కా
    ననమధ్యోపల వేదికాగ్రమున నానందంబునం బంకజా
    సననిష్ఠన్నినుఁ జూడఁగన్న నదివో సౌఖ్యంబు లక్ష్మీవిలా
    సిని మాయానటనల్‌ సుఖంబులగునే శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ప్రతి దినమూ నా చిత్తమున సువర్ణముఖనదీ వాసివైమామిడితోటల మధ్యన ఉన్నత వేదికపైని భూరిపంకజాసనమీదనున్న నీ రూపము చూడుట సౌఖ్యము గానీ, ఈ చంచలమైన ధనమా ప్రభో!', 'ధూర్జటి', '', NULL, 'e20e3f46766f9d3050e9dd6a986dda4ca9d01906c50e13d9fd059c5c1007d1f1') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-284', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 35', 'శార్దూలవిక్రీడితము

    ఆలంచున్మెడఁగట్టి దానికి నపత్యశ్రేణిఁ గల్పించి త
    ద్బాల వ్రాతము నిచ్చిపుచ్చుకొను సంబంధంబుగావించి యా
    మాలర్కంబున బాంధవంబనెడి ప్రేమం గొందఱం ద్రిప్పఁగా
    సీలన్సీల యమర్పినట్లొసంగితో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! పెండ్లామును మెడకు గట్టి, దానికి బిడ్డలను ఇచ్చి, వారి ద్వారా ఇంకంత సంబంధబాంధవ్యాలను పెంచి నా మనస్సుకు ఈ విధముగా చీల పై చీల వేసి ఈ సంసారకూపములో ఇరుక్కొనిపోయే విధముగా చేసితివా ప్రబో!', 'ధూర్జటి', '', NULL, '1bcb13bd33e948ecd094a52b00f9d1eec411ea89a2c535adaacee826f8e240e5') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-285', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 36', 'మత్తేభవిక్రీడితము

    తనువే నిత్యముగానొనర్చు మది లేదా, చచ్చి జన్మింపకుం
    డ నుపాయంబు ఘటింపు, మీ గతుల రెంటన్నేర్పు లేకున్న లే
    దని నాకిప్పుడెచెప్పు; చేయఁగల కార్యంబున్న సంసేవఁజే
    సి నినుంగాంచెదఁగాక కాలముననో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నాకు ఈ తనువును శాశ్వతమొనర్పుము, లేక మఱొక్క జన్మమైనా లేకుండుగా నిశ్చయించుము. ఈ రెండు పనులు చేయకున్న నాకు నీ పాద నిరంతరధ్యానము ఎబ్భంగి కలుగునో వచింపు ప్రభో!', 'ధూర్జటి', '', NULL, '26768df49fbceafe09710fee713a77e1f81602e6bdb831396d1b3f51f73e55a4') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-286', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 37', 'మత్తేభవిక్రీడితము

    పదునాల్గేలె మహాయుగంబులొక భూపాలుండు, చెల్లించె న
    య్యుదయాస్తాచలసంధినాజ్ఞ నొకఁడాయుష్మంతుఁడై వీరి య
    భ్యుదయంబెవ్వరు చెప్పఁగా వినరొ? యల్పుల్మత్తులై యేల చ
    చ్చెదరో రాజులమంచు నక్కటకటా! శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! పదునాలుగు భువనములు ఏలితినని ఒక్కడు, పూర్వాద్రి నుండి పశ్చిమాద్రివరకు దీర్ఘకాలము ఏలితినని మఱొక్కడు అల్పులై నీ మహత్యమెఱుగక మరణ సమయమునందు కూడా గమనింపపరు కదా ప్రభో!', 'ధూర్జటి', '', NULL, '444c0b48de53a21b7ba16eb900dc14a9e350a13ddcf41636d08c63552ec920a3') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-287', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 38', 'శార్దూలవిక్రీడితము

    రాజన్నంతనెపోవునా కృపయు ధర్మంబాభిజాత్యంబు వి
    ద్యాజాత క్షమ సత్యభాషణము విద్వన్మిత్ర సంరక్షయున్‌
    సౌజన్యంబు కృతంబెఱుంగుటయు విశ్వాసంబుగాకున్న దు
    ర్బీజ శ్రేష్ఠులుగా గతంబుగలదే శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! రాచపదవి కలిగిన మాత్రమునే గతములో నేర్చిన / ఉన్న విద్య, దయ, ఆభిజాత్యము, ఓర్పు, రక్షణాశీలత, సుహ్రుద్భావము అన్నీ గతించిపోవునా? అట్టివారు రాజ శబ్దమునకే అనర్హులు కదా, ప్రభో!', 'ధూర్జటి', '', NULL, '537add807824429d8960bacf33fd7d88d6429a2d6170da3767bcc2a531c65a1a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-288', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 39', 'మత్తేభవిక్రీడితము

    మును నీచే నపవర్గ రాజ్యపదవీమూర్ధాభిషేకంబు గాం
    చిన పుణ్యాత్ములు నేను నొక్కసరివో చింతించి చూడంగ నె
    ట్లనినం గీటఫణీంద్రపోతమదవేదండోగ్ర హింసావిచా
    రినిఁగాఁగా నినుఁగానఁగాక మదిలో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ముందు నీవు మోక్షపదవీ సామ్రాజ్యమును ఒసంగిన పాము, సాలెపురుగు, ఏనుగు, కిరాతుడు మొదలైన వారందరూ నేనూ సమానులమే. ఏ విధముగా అన వారు నిన్ను మదిని చూచితిరి. నేను చూడలేకపోతిని.', 'ధూర్జటి', '', NULL, 'a3b8e25d954690fc3cb40f600a4b2d334ffa0a1975497613faeb4ed6990c54c5') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-289', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 40', 'మత్తేభవిక్రీడితము

   పవమానాశనభూషణ ప్రకరముల్భద్రేభచర్మంబు నా
   తవికత్వమ్ముఁబ్రియంబులై భుజగ శున్డాలాచారులన్
   భవదుఃఖములఁ బాపు టొప్పుఁజెలఁదిం బాటించి కైవల్యమి
   చ్చి వినోదించుటకేమి కారణమయా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నీవు సర్పాభరణభూషితుడవు, గజచర్మాంబరధారివి, ఒకప్పుడు కిరాతవేషమును పూనినవాడివి కనుక అహి,గజ,కిరాతులకు మోక్షమిచ్సితివని అనుకొంటిని. కానీ నీకు ఎందుకూ కొరగాని సాలెపురుగుకు కూడా కైవల్యము ఇచ్చినావు. ఈ వినోదమునకు కారణము ఏమి ప్రభో?', 'ధూర్జటి', '', NULL, 'be13df6e970de20ef462c159e276bbee6ff4a20dfc02308cc0723222007330df') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-290', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 41', 'మత్తేభవిక్రీడితము

   అమరస్త్రీల రమించినన్ జెడదు మోహంబింతయున్ బ్రహ్మ ప
   ట్టము సిద్దించిన నాస దీరదు నిరూఢక్రోధమున్ సర్వలో
   కములన్మ్రింగినమాన దిందుఁగల సౌఖ్యంబొల్ల నీ సేవ చే
   సి మహాపాతక వారిరాశిఁ గడతున్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! రంభాద్యప్సరసలను కూడినా కూడా మోహము చల్లారదు, బ్రహ్మపదవి చేకూరినా కూడా ఆశ చావదు, సమస్త సృష్టిని కబళించినా కూడా లోపలి కోపము తగ్గదు. ఈ ప్రపంచములోని సుఖములు నాకక్కరలేదు. నీ సేవ చేసుకొని నా పాపపంకిలమును కడుగుకుంటాను ప్రభో.', 'ధూర్జటి', '', NULL, '49891ab5b290542c23268c176728392ed485bd3717183e758bf50ec7726f8bdf') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-291', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 42', 'మత్తేభవిక్రీడితము

   చనువారిన్ గని యేడ్చువారు జముఁడా! సత్యంబుగా వత్తు మే
   మనుమానం బిఁకలేదు నమ్ముమని తా రావేళ నా రేవునన్
   మునుగన్ బోవుచు బాసచేయుట సుమీ ముమ్మాటికింజూడగాఁ
   చెనటుల్గానరు దీని భావమిదివో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! చనిపోయిన వారిని చూసి రేవులో మునుగుతూ, "యముడా! మేము మాత్రము శాశ్వతమా? ఏదో ఒకనాడు అనుమానము లేక మేము కూడా వస్తాము" అని ఏడ్చునది ప్రమాణములు చేయుటకు మాత్రమే. దీనిలోని భావమును వివేకహీనులు గ్రహించలేరు. ఆ ఏడుపు ఆ ప్రమాణాల వరకేనని కవి భావము.', 'ధూర్జటి', '', NULL, 'a4223219584cf135fd0e71a3168f6fe2766dbbf3f17652affbf0bd0e527a4c6f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-292', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 43', 'మత్తేభవిక్రీడితము

   భవదుఃఖంబులు రాజకీటముల నే బ్రార్థించినం బాయునే
   భవదంఘ్రిస్తుతిచేతఁగాక విలసద్బాలక్షుధాక్లేశదు
   ష్టవిధుల్మానునె చూడ మేఁకమెడచంటందల్లి కారుణ్య దృ
   ష్టివిశేషంబున నిచ్చు చంటఁబలెనో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! సంసారతాపత్రయములు నీ పాదసంసేవచే మానునా, లేక దుష్టరాజుల ప్రాపకముచే మానునా? బిడ్డ ఆకలి తల్లి చనుబాలతో తీరునే కానీ మేక మెడ క్రింది చన్ను గుడిచిన తీరునా ప్రభో?', 'ధూర్జటి', '', NULL, '4a2dfe3bd5b415fd2a54cfa5212fa87cac8566685c6cfab2bc6797a09526eb73') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-293', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 44', 'శార్దూలవిక్రీడితము

   పవి పుష్పంబగు నగ్నిమంచగు నకూపారంబు భూమీస్థలం
   బవు, శత్రుండతిమిత్రుఁడౌ విషము దివ్యాహారమౌ నెన్నఁగా
   నవనీమండలిలోపలన్ శివశివేత్యాభాషణోల్లాసికిన్
   శివ నీ నామము సర్వవస్యకరమౌ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! వజ్రాయుధము కూడా పుష్పమాలికవుతుంది, అగ్ని మంచులా మారుతుంది, సముద్రము నేలగా పరిణమిస్తుంది, అత్యంతశత్రువు మిత్రుడవుతాడు, విషము ఆహారమౌతుంది కదా ప్రభో "శివ శివా" అని సదా నీ నామ సంస్మరణము చేయువానికి సర్వమూ వశ్యమవుతుంది.', 'ధూర్జటి', '', NULL, '45790dfd5522f3943bdddbdcdd48fe11776cac28850fc67508838e55aaefc030') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-294', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 45', 'శార్దూలవిక్రీడితము

   లేవో కానలఁ గందమూలఫలముల్ లేవో గుహల్ తోయముల్
   లేవో యేఱులఁ బల్లవాస్తరణముల్లేవో సదా యాత్మలో
   లేవో నీవు విరక్తులన్మనుప జాలిన్ బొంది భూపాలురన్
   సేవల్సేయఁగఁ బోదులేరొకో జనుల్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! అడవిలో కందమూలఫలపుష్పాదులు లేవా? పరుండుటకు గుహలు లేవా? యేఱులయందు నీళ్ళు లేవా? పూజించుటకు ఆత్మలో నీవు లేవా? వర్తకవ్యాపారములని ఏలనో ఈ జనులు సేవలు చేయుదమని రాజుల ప్రాపకము కోసము పోయెదరో ప్రభో?', 'ధూర్జటి', '', NULL, '4b557055cee6cf69a8f4928d2c31670119467d92e56bccef9204b36ac8b80e09') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-295', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 46', 'మత్తేభవిక్రీడితము

   మును నేఁ బుట్టినపుట్టులెన్ని గలవో మోహంబుచే నందుఁ జే
   సిన కర్మంబుల ప్రోవులెన్ని గలవో చింతిచినన్ గాన నీ
   జననంబే యని యున్న వాడ నిదియే చాలింపవే నిన్నుఁ గొ
   ల్చిన పుణ్యంబునకుం గృపారతుఁడవై శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ముందు నేను ఎత్తిన జన్మలెన్నో, వాటిలో నేను చేసిన కర్మలెన్నో నాకు తెలియదు.ఎంత ఆలోచించినా నేను తెలుసుకోనలేకున్నను. ఈ జన్మమే పారమార్థికమని భావించుచున్న నాకు ఈ జన్మలో చేసిన నీ ధ్యానపుణ్యముచేత ఇదియే కడగొట్టు జన్మ గావింపుము ప్రభో', 'ధూర్జటి', '', NULL, '1f798ab7251b6ac1e8fbb23ad7986f6c540134e034ae334253ee9120e8e70c5d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-296', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 47', 'మత్తేభవిక్రీడితము

   తనువెందాక ధరిత్రినుండు నను నందాకన్ మహారోగ దీ
   పన దుఃఖాదులఁ బొందకుండ ననుకంపాదృష్టి వీక్షించి యా
   వెనుకన్ నీపదపద్మముల్ దలఁచుచున్ విశ్వప్రపంచంబుఁ బా
   సిన చిత్తంబున నుండఁజేయంగదవే శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఈ శరీరము ఎంతవరకూ భూమియందు ఉండునో అంతవరకూ నీవు నన్ను దయాదృష్టితో వీక్షించి రోగదుఖముల బారిన పడకుండునట్టు కాపాడి ఆ తరువాత నీదివ్యపాదపద్మములే ధ్యాసగా చేసి నన్ను ఉద్దరించు ప్రభో.', 'ధూర్జటి', '', NULL, '0b25462b00cf86ab887e671b4510874400f6665fd920108614ad455c541cefe2') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-297', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 48', 'మత్తేభవిక్రీడితము

   మలభూయిష్ట మనోజధామము సుషుమ్నా ద్వారమో యారు కుం
   డలియో పాదకరాక్షియుగ్మంబులు షట్కంజంబులో మోము దా
   జలజంబో నిటలంబు చంద్రకళయో సంగంబు యోగంబో గా
   సిలి సేవింతురు కాంతలన్ జనుల్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఆడువారి సాంగత్యము కోసము జనులు తాపత్రయము చూడ, వారి యోనిమార్గము సుషుమ్నా ద్వారమయిన మూలాధారమనినట్టు, నూగారు కుండలి అయినట్టు, పద్మములతో పోల్చునట్టి వారి పాద కర, అక్షిద్వయములు షట్చక్రములు అనినట్టు, మొహము సహస్రారమనినట్టు, నుదురు చంద్రకళ అనినట్టు, సంయోగమే యోగమనినట్టు భావించి సేవించెదరు కదా ప్రభో.', 'ధూర్జటి', '', NULL, '9f45a4d228a2cbeafd674947a577655654e39f7e561c14998862acec23ad2986') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-298', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 49', 'మత్తేభవిక్రీడితము

   జలకంబుల్ రసముల్ ప్రసూనములు వాచాబంధముల్ వాద్యము
   ల్కలశబ్దధ్వను లంచితాంబర మలంకారంబు దీప్తుల్మెఱుం
   గులు నైవేద్యము మాధురీ మహిమగాఁ గొల్తున్నిన్నున్ భక్తిరం
   జిల దివ్యార్చన గూర్చి నేర్చిన క్రియన్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! కావ్యరసములే స్నానముగా, పద్యములే పూలుగా, అర్థమే భేరీకాహళవాద్యములుగా, అలంకారములు వస్త్రములుగా, కవితాసౌందర్యమే దీపములుగా, మాధుర్యమే నైవేద్యముగా కూర్చి నా చేతనయినట్టుగా నీ కైంకర్యము చేసెదను స్వామీ.', 'ధూర్జటి', '', NULL, 'a2c869e8a89f3e35941343ab8d1474076efbbc5a1978b7780f3c23508dac94e9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-299', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 50', 'శార్దూలవిక్రీడితము

   ఏలీలన్నుతియింపవచ్చు నుపమోత్ప్రేక్షాధ్వని వ్యంగ్య శ
   బ్దాలంకార విశేషభాషల కలభ్యంబైన నీ రూపమున్
   జాలుంజాలుఁ గవిత్వముల్ నిలుచునే సత్యంబు వర్ణించుచో
   చీ లజ్జింపరు కదా మాదృశకవుల్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఉపమాది అర్థాలంకారములతో, నానావిధ శబ్దాలంకారములతో నిన్ను నావంటి కవులు వర్ణింపచూస్తారు. భాషకు దొరకనట్టి నీ రూపము వచిన్చాదము సాధ్యమా? సత్యము వర్ణించేటప్పుడు కవిత్వములు నిలుచునా ప్రభో?', 'ధూర్జటి', '', NULL, '95cbbd0a8f97285353b32f1f3b57d87e808893a1410568d5ac9cb94542627be6') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-300', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 51', 'శార్దూలవిక్రీడితము

   పాలున్ బువ్వయుఁ బెట్టెదన్ గుడవరా పాపన్న రాయన్న లే
   లే లేమ్మన్న నరంటిపండు కొని తే లేకున్న నొల్లనం
   టే లాలింపరే తల్లితండ్రులపుడట్లే తెచ్చి వాత్సల్య ల
   క్ష్మీ లీలావచనంబులన్ మనుపవే శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! చిన్నపిల్లలు పాలు, అన్నము తెచ్చి తినమంటే, కాదు అరటిపండు కావాలని ఎలా మారాం చేస్తారో, అదే విధముగా నేను కూడా నాకు ఇచ్చిన ఇహలోక సౌఖ్యములను వద్దని మోక్షమార్గము కోసము నిన్ను వేడితిని. తల్లితండ్రులు ఏ విధముగా ఆ మొండి బాలుని కోరికను తీరుస్తారో అదే విధముగా నీవు నన్నుద్ధరించు ప్రభో', 'ధూర్జటి', '', NULL, '4ac76ba4b88ad8a772a08e7a3c0104c430427b154336bb9d97b3c6f0e3e74dd0') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-301', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 52', 'మత్తేభవిక్రీడితము

   కలకంచున్శకునంబులంచు గ్రహయోగంబంచు సాముద్రికం
   బు లటంచు న్దెవులంచ రిష్టమనుచున్ భూతంబులంచు న్విషా
   దులటంచున్ నిమిషార్ద జీవనములందున్ బ్రీతిఁబుట్టించి యీ
   సిలుగుల్ ప్రాణులకెన్ని చేసితివయా, శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! కళలు, శకునములు, గ్రహయోగములు, సాముద్రికము, రోగములు, అరిష్టములు, భూతములు, విషాదమని ఇన్ని విధముల వెతలు కల్పించితివేమయ్యా ఈ అర్ధనిమిషపరిమాణ జీవితములకు ప్రభో.', 'ధూర్జటి', '', NULL, 'fe7e4c2414d050d1ea496d3407593f5746eabc6c566e997007f9a544efe2b081') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-302', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 53', 'మత్తేభవిక్రీడితము

   తలమీఁదం గుుసుమ ప్రసాద మలికస్థానంబు పై భూతియున్
   గళసీమంబున దండ, నాసిక తుదన్ గంధప్రసారంబు లో
   పల నైవేద్యముఁ జేర్చునే మనుజుడా భక్తుండు నీకెప్పుడున్
   జెలికాఁడై విహరించు రౌప్యగిరిపై శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఎవడైతే సదా తలమీద నీ నిర్మాల్యమును, నుదుట విభూతిని, మెడలో రుద్రాక్షలను, ముక్కుయందు నీ అభిషేకజల సుగంధమును, ఉదరములో నైవేద్యమును కలిగి ఉంటాడో అతడు వెండికొండపై నీ స్నేహితుడితో సమముగా వర్తించగలడు.', 'ధూర్జటి', '', NULL, 'e0c68f65c59345ca9a96b232ca4849a7271c7031061d708b3b83eb61d4930c5a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-303', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 54', 'శార్దూలవిక్రీడితము

   ఆలుం బిడ్డలు మిత్రులున్ హితులు నిష్టార్థంబులీ నేర్తురే
   వేళన్ వారి భజింప జాలిబడకావిర్భూతమోదంబునన్
   గాలంబెల్ల సుఖంబు నీకు నిఁక భక్తశ్రేణి రక్షింప కీ
   శ్రీలెవ్వారికిఁ గూడఁబెట్టెదవయా, శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నీ ఆలుబిడ్డలు (పార్వతీదేవి, కుమారగణనాయకులు), స్నేహితుల (కుబేరాదులు), హితులు (మహావిష్ణువు) నీకు మోదము చేకూరునట్టుగా నీవు కోరినవి నీకు సమకూర్చుతూ ఉండగా, నీవు నీ భక్తకోటిని రక్షింపక సిరిసంపదలు ఎవరికోసమని కూడబెడుతున్నావు ప్రభో?', 'ధూర్జటి', '', NULL, '48ce95843d84074854e60fe65baf210c3ff136ca6ba2941e622ea85c64b09223') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-304', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 55', 'మత్తేభవిక్రీడితము

   సులభుల్ మూర్ఖులు నుత్తమోత్తములు రాజుల్ కల్గి యేవేళ న
   న్నలఁతం బెట్టిన నీ పదాబ్జములఁ బాయంజాల, నేమిచ్సినం
   గలధౌతాచల మేలు టంబునిధిలోఁ గావుండు టబ్జంబు పైఁ
   జెలువొప్పన్ సుఖియింపఁ గాంచుట సుమీ, శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! రాజులు భిన్నమనస్కులు. కొందఱు మంచివారు, కొందఱు మూర్ఖులు, మరి కొందఱు ఉత్తమోత్తములు. వారు నాకు ఏ విధమైన ప్రలోభములకు లోను చేసినా నేను నీ పాదారవిందములను విడువబోను. నీవు నాకు ఏ పదవి ఇచ్చినా ఇవ్వకపోయినా సంతోషమే ప్రభో.', 'ధూర్జటి', '', NULL, 'a406e7dd361009870d02e944ce9e40002ade408c94cade86e8c4f788dbf9853a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-305', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 56', 'మత్తేభవిక్రీడితము

   కలధౌతాద్రియు, నస్థిమాలికయు, గోగంధర్వమున్బున్కయన్
   బులితోలున్ భసితంబుఁ బాపతోడవుల్పోకుండఁ దోఁబుట్లకై
   తొలి నేవారాలతోడఁ బుట్టవు కళాదుల్ కల్గ మేలయ్యె నా
   సిలువున్ దూరము చేసికొంటెఱిఁగియే శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! తోడబుట్టువులు లేనివాడివి, నీకున్న ఆస్తి అంతా మంచుకొండ, ఎముకల మాలిక, చేతిలోని ఎద్దు, లేడి, పులిచర్మము, భస్మము, సర్పాభరణము, చంద్రకళ. ఇన్నింటిని పోషించుచున్న నీకు నేను భారమా? నన్ను కూడా పోషించలేవా ప్రభో?', 'ధూర్జటి', '', NULL, '66a02b08d9b90988ee9f996540daae5f9f7f496f1e02d5ca47043994dd57fec7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-306', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 57', 'మత్తేభవిక్రీడితము

   శృతులభ్యాసము చేసి శాస్త్రగరిమల్ శోధించి తత్త్వంబులన్
   మతినూహించి శరీరమస్థిరము బ్రహ్మంబెన్న సత్యంబుఁ గాం
   చితిమంచున్ సభలన్ వృధావచనముల్ చెప్పంగనే కాని ని
   ర్జిత చిత్తస్థిరసౌఖ్యముల్ దెలియరో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! వేదాలు చదివితిమని, శాస్త్రములు శోధించితిమని, భగవత్తత్వము తేలియునని, శరీరము అశాశ్వతమని, బ్రహ్మమే సత్యమనీ వృధామాటలు చెప్పుదురే కానీ వాటిని పరిత్యజించిన వారు మాత్రము లేరు కదా.', 'ధూర్జటి', '', NULL, '7e8e1b02ac5c40e09e55fba6ef66183696e1bfd8abf0f09e912a79617142cff8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-307', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 58', 'మత్తేభవిక్రీడితము

   గతి నీవంచుఁ దలంచువార లపవర్గంబొందఁగా నేల సం
   తతమున్ గూటికినై చరింప వినలేదా యాయురన్నం ప్రయ
   చ్ఛతి యంచున్మొఱవెట్టఁగా శృతులు సంసారాంధకారాభి ధూ
   షిత దుర్మార్గులు గానఁ గానఁబడవో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఆయువుంటే అన్నము కలదని శృతివాక్యములు వినికూడా నీవే మోక్షప్రదాతవు అయి ఉండగా, జనులు నిన్ను కొల్చక సంసారకూపములో పడి కొట్టుమిట్టాడుతూ దుర్మార్గులు అని అనిపించుకుంటూ ఉంటారు కదా', 'ధూర్జటి', '', NULL, '6674498e66d222854f2c2b261b1b48be9d534c465e281f91bd4decaf922d75bc') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-308', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 59', 'మత్తేభవిక్రీడితము

   రతిరాజుద్ధతిమీఱ నొక్కతఱి గోరాజాశ్వునిన్ నొక్కఁ బో
   నతఁడా దర్పకు వేగనొత్తఁ గవయంబాఁబోతునుం దాఁకి యు
   గ్రతఁ బోరాడుఁగనున్న యన్నడిమిలేఁగ ల్వోలె శోకానల
   స్థితిపాలై మొఱవెట్టినన్ మనుపవే శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! మా బుద్ధి నీ మీద నిల్పపూనగా ఒక వైపు మన్మథక్లేశము మరొక్క వైపు నీ భక్తి దార్డ్యము గవయమృగము,ఆబోతుల పోరువలె మా మదిలో పోరాడుతుండగా మధ్యలో చిక్కిన లేగపిల్లల స్థితి పాలై మొరపెట్టుకుంటున్న మమ్మల్ని బ్రోవవు కదా స్వామీ', 'ధూర్జటి', '', NULL, '370797d8aa2114405b70fc649c8d847f9f174a209de4fb0c906aaa5dc4fe9cdc') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-309', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 60', 'శార్దూలవిక్రీడితము

   అంతా సంశయమే శరీరఘటనం బంతా విచారంబే లో
   నంతా దుఃఖపరంపరాన్వితమే మేనంతా భయభ్రాంతమే
   యంతా నంత శరీరపోషణమె దుర్వ్యాపారమే దేహికిన్
   జింత న్నిన్నుఁ దలంచి పొందరు నరుల్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! దేహవాసియైన జీవునికి అంతా సంశయమే, విచారమే, దుఃఖభాజనమే, శరీరపోషణార్థం తాపత్రయమే. ఇంత దుర్వ్యాపారము ఉన్ననూ జనులు నిన్ను ఎల తలంచి ముక్తినొందరో ప్రభో?', 'ధూర్జటి', '', NULL, '7d5f7c7934816363b363d9ebafdab2f386e55bf217ea6e434b9134e3522e9269') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-310', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 61', 'శార్దూలవిక్రీడితము

   సంతోషించితిఁ జాలుఁ జాలు రతిరాజ ద్వారసౌఖ్యంబులన్
   శాంతిన్ బొందితిఁ జాలుఁ జాలు బహురాజ ద్వార సౌఖ్యంబులన్
   శాంతిన్ బొందెదఁ జూపు బ్రహ్మపద రాజద్వార సౌఖ్యంబు ని
   శ్చింతన్ శాంతుఁడనౌదు నీ కరుణచే శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! స్త్రీలతో రతిసౌఖ్యములు అనుభవించితిని, పెక్కు రాజుల ప్రాపకమును చవి చూసితి. ఇక చాలును. నీవు కరుణించి నాకు బ్రహ్మపద సౌఖ్యమును కల్పించిన చాలును ఇక నిశ్చింతగా ఉందును ప్రభో.', 'ధూర్జటి', '', NULL, '5f92ddab5c451e694935821e30f1adbda8fda6c10de05fa9fbdc9bfa8f6df3d4') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-311', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 62', 'శార్దూలవిక్రీడితము

   స్తోత్రం బన్యులఁ జేయనొల్లని వ్రతస్థుల్వోలె వేసంబుతోఁ
   బుత్రీపుత్రకళత్రరక్షణ కళాబుద్ధిన్ నృపాలాధమున్
   బాత్రంబంచు భజింపఁబోదు రిదియున్భావ్యంబె యవ్వారి చా
   రిత్రం బెన్నఁడు మెచ్చనెంచ మదిలో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! కొందఱు గర్వముతో ఎవరినీ పొగడని వారివలె నటించుచుందురు కానీ ఆలుబిడ్డల పాలాన కోసమై రాజాధముల ప్రాపకముకు వెంపటలాడుచుందురు. అటువంటి వారిని నేను మెచ్చలేను ప్రభో.', 'ధూర్జటి', '', NULL, '3a651c7a40dd8aada83460049e89e887008b7269fc12897699c6211d628437d8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-312', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 63', 'మత్తేభవిక్రీడితము

   అకలంకస్థితినిల్పి నాదమను ఘంటారావమున్ బిందు దీ
   ప కళాశ్రేణి వివేక సాధనము లొప్పంబూని యానంద దా
   రక దుర్గాటవిలో మనోమృగము గర్వస్ఫూర్తి వారించు వా
   రికిఁగా వీడు భవోగ్రబంధలతికల్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! మనస్సును నాదము అను ఘంటారావముతో జతచేర్చి సదా శ్రీచక్రసంచారిణియగు లలితాపరాభట్టారికయందు నిలిపి మనస్సాను మృగమును ఆమె సాన్నిధ్యములో త్రిప్పువాడికి గర్వాది దుర్వాసనలు నశించి భవబంధ విమోచనము కలుగును ప్రభో', 'ధూర్జటి', '', NULL, '5c703aa2bbdb9a8181a41af207b60d3a7d9ce10711d0afe3a12d4fca8818ef27') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-313', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 64', 'మత్తేభవిక్రీడితము

   ఒకయర్థము నిన్ను నేనడుగఁగా నూహింప నెట్లైనఁ బొ
   మ్ము కవిత్వంబులు నాకుఁ జెందనివి యేమోయంటివా నాడు జి
   హ్వకు నైసర్గిక కృత్యమింతియసుమీ ప్రార్థించుటేకాదు కో
   రికలన్ నిన్నును గాన నాకు వశమా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఈ కవిత్వములు నా జిహ్వకు అలవాటై నిన్ను ప్రార్థించుచున్నాను కానీ నీ స్తోత్రపాఠము చేసి నా కోరికలను తీర్చుకోవలెనని కాదు. కోరికలున్న నిన్ను చేరుట సాధ్యమగునా స్వామీ', 'ధూర్జటి', '', NULL, 'c34abf3277fcdfb6ca5c7c2f3033245e54bf2fef984360a5f1636fe1f3ef94da') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-314', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 65', 'మత్తేభవిక్రీడితము

   శుకముల్కింశుపుష్పముల్గని ఫలస్తోమంబటంచు స్సము
   త్సుకతం జేరఁగఁబోవ నచ్చట మహాదుఃఖంబు సిద్ధించుఁ గ
   ర్మకళాభాషలకెల్లఁ బ్రాపులగు శాస్త్రంబుల్విలోకించు వా
   రికి నిత్యత్వమనీషదూరమగు నో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! మోదుగపూలను చూసి పండ్లు అని భ్రమచెంది చిలుకలు వాటిని తినబోయిన చందమున శాస్త్రములు చదివి నీ స్వరూపమును తెలియగోరు వారు నిరాశ చెందుతున్నారు కదా స్వామీ', 'ధూర్జటి', '', NULL, 'f01bdbe157f3ce92f22467cf59a032bd702b019c28ec6cc966d05a67b9b6dc1c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-315', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 66', 'మత్తేభవిక్రీడితము

   ఒకరిన్ జంపి పదస్థులై బ్రతుకఁ దా మొక్కొక్కరూహింతు రే
   లోకొతా మెన్నఁడుఁ జావరో తమకు బోవో సంపదుల్పుత్ర మి
   త్ర కళత్రాదుల తోడ నిత్య సుఖమందంగందురో యున్నవా
   రికి లేదో మృతి యెన్నఁడున్ గట గటా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఒకరిని చంపి వారి పదవిని కైవశము చేసుకోవలెనని అలోచించెదరే కానీ తమకు ఆ సంపదలు శాశ్వతమా అని ఆలోచించారు కదా. తాము అలుబిడ్డలతో మిత్రులతో శాశ్వతముగా సౌఖ్యమును అనుభవించాలని భావిస్తారు మూర్ఖజనులు స్వామీ', 'ధూర్జటి', '', NULL, '639db64c5b245a6e867ca4f1d401dc8606aa8eb39888a664159537a1bef11255') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-316', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 67', 'శార్దూలవిక్రీడితము

   నీకారుణ్యముఁ గల్గినట్టి నరుఁ డే నీచాలయంబుం జొరం
   డే కార్పణ్యపు మాట లాడ నరుగం డెవ్వారితో వేషముల్
   గైకోఁ డేమతముల్భజింపఁ డిలనే కష్టప్రకారంబులన్
   జీకాకై చెడిపోఁడు జీవనదశన్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నీ కృపాకటాక్షవీక్షణములు ఉన్న నరుడు ఇతర దేవతలను మొక్కడు, అన్యమతములను సేవించాడు, దుష్టసంభాషణములు చేయడు, వేషములు పూనాడు, ఎటువంటి కష్టములు వచ్చినా క్రుంగడు ఏ జీవనదశలోనైనా', 'ధూర్జటి', '', NULL, '722055ebbee65d4572aca372784253dbd38cb76d506112cffb34175c6cb2a902') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-317', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 68', 'శార్దూలవిక్రీడితము

   జ్ఞాతుల్ద్రోహులు వారు సేయు కపటేర్ష్యాది క్రియాదోషము
   ల్మా తండ్రాన సహింపరాదు ప్రతికర్మంబించుకేఁ జేయఁగాఁ
   బోతే దోషము గాన మాని యతినై పోఁగోరినన్ సర్వదా
   చేతః క్రోధము మానదెట్లు నడతున్ శ్రీకాళహస్తీశ్వరా!

తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! దాయాదులు ద్రోహచింతన కలవారు. వారు చేసిన దోషములు అలవికానివి. వారికి ప్రతిక్రియ చేయుదమన్న పాపము తలచెదను. కానీ వాటినన్నింటినీ పోదోసుకుని సన్యాసిగా మారుదామన్న వారిపై కోపము చల్లారుట లేదు. నన్నేమి చేయమందువు స్వామీ.', 'ధూర్జటి', '', NULL, 'b10443054eb36d710c5a7e48c62a19696b57b3ef108be755dff1b8fc98e12e28') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-318', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 69', 'మత్తేభవిక్రీడితము

   చదువుల్ నేర్చిన పండితాధములు స్వేచ్చాభాషణ క్రీడలన్
   వదరన్ సంశయ భీకరాటవులఁ ద్రోవల్దప్పి వర్తింపఁగాఁ
   మదన క్రోధకిరాతులందుఁగని  భీమప్రౌఢి వేఁదాఁకినం
   బెదరుం జిత్తము చిత్తగింపగఁదవే శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! వేదములు చదివితిమని చెప్పుకొనుచున్న ధూర్త పండితులు కొందఱు మాకు భోదలు చేయబోగా వాటిని విని మేము సంశయమను అరణ్యములను పట్టి దోవతప్పి తిరుగాడుతున్నాము. అటువంటి మాపై కామక్రోధములనే మృగములు దాడి చేస్తున్నాయి. మేము ఈ విధముగా మతి తప్పి తిరుగాడుతూ ఉంటే మమ్ము ఆదుకొనక ఉపేక్ష వహించెదవేమయ్యా ప్రభో?', 'ధూర్జటి', '', NULL, 'fa4ec2ae6be83dd392b41ef94e2e05057b302ee65359425fce5e286cb8a70d4a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-319', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 70', 'శార్దూలవిక్రీడితము

   రోసిందేటిది రోఁతలేటివి మనోరోగస్థుఁడై దేహి తాఁ
   బూసిందేఁటిది పూఁతలేటివి మదాపూతంబులీదేహముల్
   మూసిందేటిది మూఁతలేటివి సదా మూఢత్వమేకాని తాఁ
   జేసిందేఁటిది చేఁతలేఁటివి వృథా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! వాంఛలు రోయక రోసిందేమిటి? మనస్సులోని మదము పోగొట్టుకోనక వృథా విభూతి రేఖలేమిటికి? తనలోని మూఢత్వము మానక కనులు మూసియేమి? ధ్యానము చేసినా పైవి లేక చేసిందేమీ స్వామీ?', 'ధూర్జటి', '', NULL, '189633c1dcf4886436170409833931b922d48025b1b1bc0a6a3ac65f33ac9404') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-320', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 71', 'శార్దూలవిక్రీడితము

   శ్రీశైలేశు భజింతునో యభవుఁ గాంచీనాథు సేవింతునో
   కాశీవల్లభుఁ గొల్వబోదునో మహాకాళేషుఁ బూజింతునో
   నాశీలం బణువైన మేరువనుచున్ రక్షింపవే నీ కృపా
   శ్రీశృంగార విలాస హాసములచే శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! శ్రీశైలములో నిన్ను భజించమందువా? కాంచీపురమునందా, లేక వారాణసి లోనా లేక ఉజ్జయిని మహాకాలునిగానా? నీవే రూపమున సేవింపమన్న చేసెదను. నన్ను ణీ కృపాకరుణావీక్షణమందహాసములచే రక్షింపు ప్రభో', 'ధూర్జటి', '', NULL, '69190f607cb908477c2220a419743e0c58e8dec8bac566dd912787656f8e6b4f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-321', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 72', 'మత్తేభవిక్రీడితము

   అయవారై చరింపవచ్చుఁ దనపాదాంభోజ తీర్థంబులన్
   దయతోఁ గొమ్మనవచ్చు సేవకుని యర్థప్రాణదేహాదుల
   న్నియు నా సొమ్మనవచ్చుఁగాని సిరులన్నిందించినిన్నాత్మ ని
   ష్క్రియతంగానఁగారాదు పండితులకున్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! తాము పండితులమని విర్రవీగి తమ పాదతీర్థమును పంచవచ్చు, తమనే ప్రాణధన దేహాదులచేత సేవించమని చెప్పవచ్చు. కానీ సిరిసంపదలు చెడ్డవని చెప్పుచూ వాటికోసమే పాకులాడినంత కాలము నిన్ను ఆత్మలో సాక్షాత్కరింపచేసుకోలేరు స్వామీ', 'ధూర్జటి', '', NULL, '748676e8ce0eb52554e4400916dd5db0796d0681a2d3c7353016b3f09432ca24') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-322', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 73', 'శార్దూలవిక్రీడితము

   మాయాజాండకరండ కోటిఁ బొడిగా మర్దించిరో విక్రమా
  జేయుం గాయజుఁ జంపిరో కపటలక్ష్మీ మోహమున్ బాసిరో
   యాయుర్దాయ భుజంగమృత్యువు ననాయాసంబునన్గెల్చిరో
   శ్రేయోదాయకులౌదురెట్లు రితరుల్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నీ మాదిరి ఇతరులు ప్రళయకాలమందు విశ్వమును సంహరించిరా? మన్మథుని కంటిమంటచే బూడిద చేసిరా? ధనములు వద్దనిరా? సర్పరూపములో ఉన్న మృత్యువును గెలిచిరా? ఇన్ని చేసిన నీవు కాక ఇతరులు నాకు మంచి చేయువారు ఎట్లౌదురు స్వామీ?', 'ధూర్జటి', '', NULL, '1a24e918d88267007cd445df140483689207a34d0915351730135d5eb18ec1b4') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-323', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 74', 'మత్తేభవిక్రీడితము

   చవిగాఁజూడ వినంగ మూర్కొనఁ దనూ సంఘర్షణా స్వాదమొం
   ద వినిర్మించెదవేల జంతువుల నేతత్క్రీడలే పాతక
   వ్యవహారంబులు సేయుదేమిటికి మాయా విద్యచేఁ బ్రొద్దుపు
   చ్చి వినోదింపఁగ దీన నేమిఫలమో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! పంచేంద్రియములు అనువాటితో రుచి, చూపు, వినికిడి, వాసన, స్పర్శ అని భావములు కలుగచేసి వాటితో జంతుకోటి సుఖపడుతూ ఉండగా మరలా శాస్త్రములు సృష్టించి తద్భావములు పాపములనే శంక వాటిలో కలిగించి వినోదము చూస్తున్నావు కదా, దీనివల్ల నీకేమి ఆనందము ప్రభో?', 'ధూర్జటి', '', NULL, '7b4ed1e13c742dbf2551d47d4f3999b82946ee2bd8691d52a35a6c7b7ac7d020') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-324', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 75', 'మత్తేభవిక్రీడితము

   వెనుకం జేసిన ఘోరదుర్దశలు భావింపంగ రోఁతయ్యెడున్
   వెనుకన్ముందుటవచ్చు దుర్మరణముల్వీక్షింప భీతయ్యెడున్
   నను నేఁజూచిన నావిధుల్దలచియు నాకే భయంబయ్యెడున్
   జినుకుం జీఁకటి యాయెఁ గాలమునకున్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నేను చేసిన పూర్వకర్మములు ఆలోచించిన అసహ్యమేయుచున్నది. వాటి పరిణామములు ముందు ఆలోచించిన భయమేస్తున్నది. నేను ఆచరించిన విధివిధానములు నాకే భయము గొల్పుచున్నవి. నా అంత్యకాలమందు అంతా చీకటే అనిపించుచున్నది. నన్ను కరుణించు ప్రభో.', 'ధూర్జటి', '', NULL, '63dc3e0f8f709da53e7006c46d05efaf7198895b2d9961051f28a7160015ffa9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-325', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 76', 'మత్తేభవిక్రీడితము

   పరిశీలించితి మంత్రతంత్రములు చెప్పన్వింటి సాంఖ్యాది యో
   గ రహస్యంబులు వేదశాస్త్రముల్ వక్కాణించితిన్ శంక వో
   దరయన్ గుమ్మడికాయలోన యవగింజంతైన నమ్మించి సు
   స్థిర విజ్ఞానము త్రోవఁజూపఁగదవే శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! మంత్రతంత్రములు పరిశీలించితి యోగరహస్యములు పెద్దలు చెప్పగా వింటి వేదశాస్త్రములు చదువచెప్పితి కానీ గుమ్మడికాయలోని ఆవగింజంత విజ్ఞానము చేకూరలేదు. అంతమాత్రమైనా భోదించి నాకు దారి చూపుము ప్రభో', 'ధూర్జటి', '', NULL, '1eb38cad318b8ad674f43dfd6bf04121f490d1eed32de2541e9f3a2ecce38c30') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-326', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 77', 'మత్తేభవిక్రీడితము

   మొదలం జేసినవారి ధర్మములు నిర్మూలంబుగాఁ జేసి దు
   ర్మదులై యిప్పుడు వారి ధర్మములొనర్పం దమ్ముదైవంబు న
   వ్వదె రానున్న దురాత్ములెల్లఁ దమత్రోవం బోవరే యేల చే
   సెదరో మీఁదు దలంచి చూడకధముల్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! సనాతన ధర్మములు తప్పని, తాము నేర్చినవి ధర్మములని చెప్పేవారిని చూసి దైవము నవ్వదా? ముందు తరాలవారు అవి నమ్మి చెడిపోరా? ముందు ఆలోచించక ఈ విధముగా చెప్పి ఏల అధములగుదురో కదా ప్రజలు స్వామీ', 'ధూర్జటి', '', NULL, '5d32df0ee09ac290111f32871dcfe23f9a9df351756ec86edeadf06355e5d568') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-327', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 78', 'శార్దూలవిక్రీడితము

   కాసంతైన సుఖంబోనర్చునొ మనఃకామంబులీడేర్చునో
   వీసంబైనను వెంటవచ్చునొ జగద్విఖ్యాతి గావించునో
   దోసంబుల్వెడఁబాపునో వలసినం దొడ్తో మిముంజూపునో
   చీ సంసారదురాశేలుడుపవో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఈ సంసారవ్యామోహము కొంచెమైనా సుఖదాయకమా? కోరిన కోర్కెలు తీర్చునా? వెంట వచ్చు పుణ్యమా? యశఃదాయకమా? దోషనాశకమా? లేక నిన్ను చేరు మార్గమా? దీనిని ఏల తొలగింపవు ప్రభో?', 'ధూర్జటి', '', NULL, 'd5c6ee7c0d0115a816a7cf8090395a1b6078514a999c97a7f44a0dce927c09a1') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-328', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 79', 'మత్తేభవిక్రీడితము

   ఒకపూఁ టించుక కూడు తక్కువగునే నోర్వంగలేఁ డెండకో
   పక నీడన్వెదకున్ జలిన్ జడిసి కుంపట్లెత్తుకోఁ జూచు వా
   నిల్లిల్లును దూఱు నీ తనువు దీనన్వచ్చు సౌఖ్యంబు రో
   సి కడాసింపరు గాక మర్త్యులకటా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఈ శరీరముకు భోజనము ఒకపూట కొంచెము తక్కువైనా, ఎండ తగిలినా, చలి కలిగినా వానయందు తడిసినా తట్టుకోలేదు. నీడపట్టుకోసమో, కుంపట్లకొ, వానకు జడిసి ఇంటిచూరో వెతుక్కొంటారే కానీ ఈ జనులు ఈ శరీరవాంఛ పోగొట్టుకోరు కదా ప్రభో', 'ధూర్జటి', '', NULL, '61f4c57c8fb1524755b6f32aa6b2ccbfa94ca7d3b9a950d19d29c1ce20a11568') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-329', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 80', 'శార్దూలవిక్రీడితము

   కేదారాది సమస్త తీర్థములు కోర్కిం జూడఁ బో నేటికిన్
   గాదా ముంగిలి వారణాసి కడుపే కైలాసశైలంబు నీ
   పాదధ్యానము సంభవించునపుడే భావింప నజ్ఞాన ల
   క్ష్మీ దారిద్ర్యులు గారే లోకులటా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నీ ధ్యానము మనస్సులో కలిగినప్పుడే ఇంటి ముంగిలి కాశీ క్షేత్రము కాదా? కడుపే కైలాసము కాదా. ఇది చేయక కేదారాది పుణ్య క్షేత్రములు సేవించుటకు పోవుదురే అజ్ఞానజనులు?', 'ధూర్జటి', '', NULL, '47ba12cc49d55a7e44518a7a6e9848ce6cc51258dd2f6825b244523bbc7363e9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-330', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 81', 'మత్తేభవిక్రీడితము

   తమకంబొప్పఁ బరాంగనాజన పరద్రవ్యంబులన్ మ్రుచ్చిలం
   గ మహోద్యోగముసేయు నెమ్మనము దొంగంబట్టి వైరాగ్య
   పాశములంజుట్టి బిగించి నీదుచరణ స్తంభమునన్ గట్టి వై
   చి ముదం బెప్పుడుఁగల్గఁజేయఁగదవే శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నా మనస్సు అనెడు దొంగ ఒకడు సదా పరస్త్రీ, పరద్రవ్యములను దొంగలించవలెనను గొప్ప పథకముతో ఉన్నాడు. అట్టివానిని పట్టి వైరాగ్యమను తాళ్ళతో కత్తి ణీ పాదములనెడు స్తంభమునకు కట్టి నాకెప్పుడు ఆనందము కలుగజేసెదవు స్వామీ', 'ధూర్జటి', '', NULL, '4b2934a46eceb5e5178401eaf0848e1559b9e79ace3674403a7b3abd99cd1f17') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-331', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 82', 'శార్దూలవిక్రీడితము

   వేధం దిట్టగరాదు భువిలో విద్వాంసులం జేయునే
   లా ధీచాతురిఁ జేసెఁ జేసినగులా మాపాటనే పోక క్షు
   ద్బాధాదుల్ కలిగింపనేల యది కృత్యంబైన దుర్మార్గులన్
   జే ధాత్రీశులఁ జేయనేటికకటా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! బ్రహ్మదేవున్ని తిట్టకూడదు కానీ, ఈ సృష్టిలో ఆయన విద్వాంసులను సృష్టించుట ఎందుకు? పోనీ సృష్టించినా వారికి ఆకలి బాధలు కలుగజేయుట ఎందుకు? వీటిని తీర్చగలిగికూడా తీర్చని దుష్టులను రాజులు చేయుట ఎందుకు స్వామీ', 'ధూర్జటి', '', NULL, 'f9652251bdaecae7058fbafa1c29f0b70f2b36af9a571677b9741c3265039211') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-332', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 83', 'మత్తేభవిక్రీడితము

   పుడమిన్నిన్నొక బిల్వపత్రమున నేఁ బూజించి పుణ్యంబునున్
   బడయన్నేరక పెక్కు దైవములకున్ బప్పుల్ ప్రసాదంబులున్
   గుడుముల్ దోసెలు సారెసత్తులడుకుల్ గుగ్గిళ్ళునుం బెట్టుచున్
   జెడి యెందుం గొఱగాకపోదు రకటా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! జనులు భూమిలో భక్తసులభుడవైన నిన్ను ఒక్క బిల్వపత్రముతో పూజించక ఇతర దేవతలకు నానావిధములైన ప్రసాదములు పెట్టి చెడి ఎందుకూ కొరగాకుండా పోవుచున్నారు కదా', 'ధూర్జటి', '', NULL, '2923811d6486d4143fac0f9c4a90b53406db363238050f6d7a562fac6056143f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-333', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 84', 'శార్దూలవిక్రీడితము

   విత్తజ్ఞానము పాదు చిత్తము భవావేశంబు రక్షాంబువుల్
   మత్తత్వంబు తదంకురం బనృతముల్ మాఱాకులత్యంత దు
   ర్వృత్తుల్పువ్వులు పండ్లు మన్మథ ముఖావిర్భూత దోషంబులున్
   జిత్తాభ్యున్నత నింబ భూజమునకున్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నా మనస్సు చేదు వేపవృక్షము వంటిది. దీనికి పాదు ధనమందు ఆశ, అహంకారము నీరు, మదము దీని మొలకలు, అసత్యములు మారాకులు, అత్యంత క్రూరపనులు పువ్వులు, కామవికారము పండ్లు. (ఇది నీ చింతనామృతము ఎట్లు స్వీకరించునయ్యా)', 'ధూర్జటి', '', NULL, 'df99b6ae6f6295eacb96b7679d054bc2709ff873d759c69736e2ad48f473854c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-334', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 85', 'మత్తేభవిక్రీడితము

   నీపైఁ గావ్యము చెప్పుచున్న యతఁడు న్నీపద్యముల్ వ్రాసియి
   మ్మా పాఠంబొనరింతునన్నయతఁడు మంజుప్రబందంబు ని
   ష్టాపూర్తినబఠియించుచున్న యతఁడున్సద్బాందవుల్గాక చీ
   చీ పృష్ఠాగతబాంధవంబు నిజమా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నీపైని పద్యములు వ్రాసి ఇచ్చిన చదివెదనని చెప్పువాడు, నిన్నుగురించిన పురాణముల పఠనము చేయగోరువాడు నిజమైన బంధువులు కానీ నాకు వెనుకటి సంబంధముల, పుట్టుకవల్ల అయినవారు నాకు బంధువులా ప్రభో?', 'ధూర్జటి', '', NULL, '87fd346158cd6c3587f8cb10a6e85d9dc821b4a72b44e42877700c418b7bec8b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-335', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 86', 'శార్దూలవిక్రీడితము

   సంపద్వర్గముఁ బాఱద్రోలి రిపులన్ జంకించి యాకాంక్షలన్
   దంపుల్వెట్టి కళంకముల్నఱికి బంధక్లేశదోషంబులన్
   జింపుల్చేసి వయోవిలాసములు సంక్షేపించి భూతంబులన్
   జెంపల్వేయక నిన్నుఁగాననగునా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! సంపదలను త్యజించి, అరిషడ్వర్గములను భేదించి, ఆశలను పక్కకుపెట్టి, పాపములను ప్రక్షాళన గావించుకుని, బంధుబాధలను విడిచి, వయస్సు దాని విలాసములను వదులుకుని, పంచభూతాత్మకమైన వాసనలను పారద్రోలిన గానీ నిన్ను చూడగలనా ప్రభో?', 'ధూర్జటి', '', NULL, 'a60adeeb7262e4aa1333f16241328626cbec302dc40cbe7943c97df6a3e5ce88') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-336', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 87', 'శార్దూలవిక్రీడితము

   రాజశ్రేణికి దాసులై సిరులఁ గోరం జేరఁగా సౌఖ్యమో
   యీ జన్మంబు తరింపఁ జేయఁగల నిన్నేపొద్దు సేవించు ని
   ర్వ్యాజాచారము సౌఖ్యమో తెలియలేరౌ మానవుల్పాపరా
   జీజాతాతి మదాంధబుద్ధులగుచున్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ధనముకై రాజుల పంచన పడి బ్రతుకుట సుఖమా నిరంతర సుఖదాయకుడవగు నీ సేవ సౌఖ్యమా? ఈ విషయమును తెలుసుకోలేక మనుషులు పాపముల వలన గ్రుడ్డివారై జీవించుచున్నారు కదా ప్రభో', 'ధూర్జటి', '', NULL, 'c897d1289550d643d8163b201edfe20eef2d2ef198fff4fcc15c862581867020') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-337', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 88', 'శార్దూలవిక్రీడితము

   నిన్నంజూడరో మొన్నఁజూడరొజనుల్ నిత్యంబుఁజావంగ నా
   పన్నుల్గన్న నిధానమయ్యెడి ధనభ్రాంతి న్విసర్జింప లే
   కున్నా రెన్నఁడు గందురిఁకమర్త్యుల్ గొల్వరేమో నినున్
   జిన్నంబుచ్చక ప్రోవకుండు నెడలన్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! రోజూ చస్తున్నవారిని చూసి కూడా మనుషులు నిన్ను కొలవలేక ధనభ్రాంతి విసర్జించలేక ఉన్నారు. వారికింక ఎప్పటికి వచ్చునొ నీ పాదసంసేవాసక్తి. కానీ నీవు మాత్రము వారు నిన్ను కొలువని కారణమున వారి చేయి విడువకు ప్రభో', 'ధూర్జటి', '', NULL, 'eaba0e54dc83760d0faa9427d34129859b6b414a10cb3e69d93aa28d5986c357') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-338', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 89', 'శార్దూలవిక్రీడితము

   వన్నే యేనుఁగుతోలు దుప్పటము బువ్వా కాలకూతంబు చే
   గిన్నే బ్రహ్మకపాల ముగ్రమగు భోగే కంఠహారంబు మే
   ల్నిన్నీలాగున నుంటయున్ దెలిసియు న్నీపాదపద్మంబు చే
   ర్చె నారాయణుఁడెట్లు మానసముఁ దా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నీవు కట్టునది ఏనుగుచర్మము, ఆహారమా కాలకూటవిషము, చేతిలో బ్రహ్మదేవుని కపాలము, మెడలో భీకరమైన సర్పము. ఇంత ఉగ్రమైన ఆకారము కలిగిన నిన్ను చూసి కూడా ఆ శ్రీమన్నారాయణుడు సదా తన మనస్సును నీ ధ్యానమందు ఏ విధముగా నిలిపినాడో కదా ప్రభో?', 'ధూర్జటి', '', NULL, '9175398e5e2723de82a71f7d1ab9028e4a616a55f6461fa5e769e95a539a0bf3') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-339', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 90', 'శార్దూలవిక్రీడితము

   ద్వారద్వారములందుఁ గంచుకి జనవ్రాతంబు దండంబులున్
   దోరంతస్థలి బగ్గనం బొడుచుచున్ దుర్బాషలాడన్మఱిన్
   వారిన్ బ్రార్థనచేసి రాజులకు సేవల్సేయగాఁ బోరు ల
   క్ష్మీరాజ్యంబును గోరి నీ పరిజనుల్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! రాజసందర్శనార్థము పోవు జనులు అక్కడ కావలివాడు కట్టె తీసుకుని అదిలిస్తూ లోనికి విడువక నానా దుర్భాషలు ఆడుచూ ఉన్నా వారిని బ్రతిమాలి లోనికి వెళ్లి రాజాశ్రయము పొంది సంపదలు పొందవలెనని జనులు ఆశిస్తూ ఉంటారు. కానీ నీ సేవాసక్తులైన జనులు మాత్రము అట్టి తుచ్చ సుఖములను ఆశింపరు.', 'ధూర్జటి', '', NULL, '0ee30dcef192e2a6c335345076bb46f8673aaff615b5ea3a7f5830560bcf1ef8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-340', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 91', 'శార్దూలవిక్రీడితము

   ఊరూరన్ జనులెల్ల భిక్షమిడరో యుండన్ గుహల్గల్గవో
   చీరానీకము వీధులన్దొరకదో శీతామృతస్వచ్ఛ వాః
   పూరం బేఱులఁపాఱదో తపసులం బ్రోవంగ నీవోపవో
   చేరం బోవుదురేల రాజుల జనుల్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! తిండికి ప్రజలు ఊరూరా భిక్ష పెట్టరా? ఉండుటకు గుహలు లేవా? కట్టుకొను బట్టలు వీధి అంగళ్ళలో దొరకవా? ఊరి సెలయేళ్లయందు త్రాగుటకు స్వచ్ఛమైన నీరు పారదా? తపస్సు చేసుకునే వారికి నీవు అండగా లేవా? ఇన్ని ఉన్నా రాజుల ప్రాపకము గోరి జనులు ఎందుకు తిరిగెదరో స్వామీ?', 'ధూర్జటి', '', NULL, '568cca54286311e21bc811e2c548bb7b19b6498d5197859af757de5f863fd008') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-341', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 92', 'మత్తేభవిక్రీడితము

   దయసేయండని కొందఱాడుదురు నిత్యంబున్నినున్గొల్చుచున్
   నియమంబెంతొ ఫలంబు నంతియకదా నీవీయు పిండెంతొయం
   తియకా రొట్టె మదిం దళంబశనబుద్ధిం జూడనేలబ్బు స
   త్క్రియలన్నిన్ను భజింపకిష్టసుఖముల్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! "మాపై దయ లేదా" అని కొందఱు నిన్ను నిత్యమూ కొలుచుచూ, కానీ వారి భక్తి ఏపాటిదో నీ కరుణా వారిపై అంతే కదా. పిండెంతో రొట్టె అంతే అన్న చందమున.', 'ధూర్జటి', '', NULL, 'd7172ad557a1f8c815230b837e97aee766b46b01c8b4f884afc89979b0bf2846') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-342', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 93', 'శార్దూలవిక్రీడితము

   అరావం బుదయించెఁ దారకముగా నాత్మాభ్రవీధిన్మహా
   కారోకారమకారయుక్తమగు నోంకారాభిధానంబు చే
   న్నారున్విశ్వ మనంగఁ దన్మహిమచే నా నాదబిందుల్సుఖ
   శ్రీరంజిల్లఁ గడంగు నీవదె సుమీ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! అకార, ఉకార మకార స్వరూపమైన ఓంకారరూపుడవు నీవే (''ఓమిత్యేకాక్షరం బ్రహ్మ'' అను ప్రణవోక్తి మూలముగా). నీ మీదనే విశ్వమంతా నడుచుచున్నది. ఆ ఓంకారనాదము అపౌరుషేయమై అభ్రవీధిలో ఉదయించినది.', 'ధూర్జటి', '', NULL, '95a6e278d4b88d9182615785342cafdb716dc9f6ab63f824aa18ea7a3e34748e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-343', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 94', 'శార్దూలవిక్రీడితము

   నీభక్తుల్పదివేలభంగుల నినున్ సేవింపుచున్ వేడఁగా
   లోభంబేటికి వారి కోర్కుల్ కృపాళుత్వంబునన్ తీర్ప రా
   దా భవ్యంబుఁ దలంచిచూడు పరమార్థంబిచ్చి పొమ్మన్న నీ
   శ్రీభండారములోఁ గొఱంతపడునా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! వేలవిధములుగా నీ భక్తులు నిన్ను సేవించుచూ ఉంటే వారికి పరమార్థము దయచేసి వారిని ఆదుకోరాదా ప్రభో? వారికి కోరిన కోర్కెలు తీరిస్తే నీ ఆస్తి ఎమన్నా కరిగిపోతుందా స్వామీ?', 'ధూర్జటి', '', NULL, '65062d29014bcc3a681c80360a94b17fb6bf98cb181468a1dcb265af88176f88') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-344', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 95', 'మత్తేభవిక్రీడితము

   మొదలన్భక్తుల కిచ్చినాఁడవుకదా మోక్షంబునేఁడేమయా
   ముదియంగా ముదియంగఁబుట్టె ఘనమౌమోహంబు లోభంబు న
   న్నది సత్యంబు కృపందలంప వొకపుణ్యాత్ముండు నిన్నాత్మఁ గొ
   ల్చి దినంబుల్మొఱవెట్టగాఁ గటకటా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! మొదలు నిన్ను పూజించిన భక్తులకందరికీ మోక్షమును ఇచ్చినావు అని అంటారే. ఇప్పుడు ఒక పుణ్యాత్ముడు (ధూర్జటి) నిన్ను పదేపదే కొల్చుచుండ ఇంత ఆలసత్వము ఎందుకయ్యా. నాకు వయస్సు మీరి మోహము లోభము (వారికిచ్చితివి నాకు లేదు అని) పెరుగుచున్నవి ప్రభో.', 'ధూర్జటి', '', NULL, '7cd12b62e15ab6f1f32d87fcdf5e73ddf46e8d0651077798a95e64c5eb9a09c7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-345', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 96', 'శార్దూలవిక్రీడితము

   కాలద్వారకవాటబంధనము దుష్కాలప్రమాణక్రియా
   లీలాజాలక చిత్రగుప్త ముఖవల్మీకోగ్రజిహ్వాద్భుత
   వ్యాళవ్యాళ విరోధి మృత్యుముఖదంష్ట్రాహార్యవజ్రంబు ది
   క్చేలాలంకృత నీదునామ మరయన్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! దిక్కుల సరిహద్దులచేతనే తెలుసుకొనదగిన నీ నామము పరికించి చూడగా, నరకద్వారములు మూసివేయగలిగినది. మరణకాలసూచకమగు చిత్రగుప్తుని నాలుకలకు గరుత్మంతుడి వంటిది, కొండలవంటి మృత్యుకోరలకు వజ్రాయుధము వంటిది ప్రభో (జరాజన్మమృత్యు విముక్తి సాధనము అని కవి భావము)', 'ధూర్జటి', '', NULL, 'a12982c74746822ff2edbac58d2f18f71f9bbae8f958af31ca31b5754eed30ee') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-346', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 97', 'మత్తేభవిక్రీడితము

   పదివేలైనను లోకకంటకులచేఁ బ్రాపించు సౌఖ్యంబు నా
   మదికిన్ బథ్యముగాదు సర్వమునకున్ మధ్యస్థుఁడై సత్య దా
   న దయాదుల్గలరాజు నా కొసఁగు మెన్నన్వాని నీయట్ల చూ
   చి దినంబున్ముదమొందుదున్ గడపటన్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఎన్ని చెప్పినా నాకు లోకకంటకులైన రాజుల ప్రాపకము చేయుట ఇష్టము లేదు, సత్య దాన దాయాది గుణములు కలిగిన నీవంటి రాజును చూపించు, నిన్ను కొలిచినత్తే వానిని కూడా సేవించెదను. (అటువంటి రాజు లేదు కనుక నిన్నే సేవించెదనని కవి భావము)', 'ధూర్జటి', '', NULL, '48e774891e6da69e6575480a0836241a45d78e993db88e23c777973b47b33e0b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-347', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 98', 'శార్దూలవిక్రీడితము

   తాతల్తల్లియుఁ దండ్రియున్మఱియుఁ బెద్దల్చావఁగా చూడరో
   భీతిం బొందంగనేల చావునకుఁగాఁ బెండ్లాము బిడ్డల్హిత
   వ్రాతంబున్ బలవింప జంతువులకున్వాలాయమైపోవఁగాఁ
   జేతోవీధినరుండు నిన్గొలువఁడో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! బంధువులు అందరూ నశింపకుందురా? జంతువులకు మరణము తథ్యము అని తెలిసీ జనులు మూర్ఖులై బాధపడుచూ వ్యర్థముగా కాలక్షేపము చేయుదురే కానీ నిన్ను కొలువరు కదా', 'ధూర్జటి', '', NULL, '5c327ef9e724b645b6f41e11fe0f1ab2bc1974ecd38f76d12d82b45bf45bdfc4') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-348', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 99', 'శార్దూలవిక్రీడితము

   జాతుల్సెప్పుట సేవసేయుట మృషల్ సంధించుటన్యాయ వి
   ఖ్యాతిం బొందుట కొండెకాఁడవుట హింసారంభకుండౌట మి
   థ్యా తాత్పర్యములాడుటన్నియుఁ బరద్రవ్యంబు నాశించి యీ
   శ్రీతానెన్ని యుగంబులుండఁగలదో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! జాతకములు చెప్పి, పరుల సేవ చేసి, బొంకులాడి, అన్యాయము చేయుటలో పేరొంది, ఇతరులపై నేరములాక్రోశించి, హింసించి, దొంగసాక్ష్యములు చెప్పి పరద్రవ్యమును కూడబెట్టిన ఆ ధనము ఎన్నో యుగములు ఉండును వారికి అని వృథా ఆలోచనలు చేయుదురే కానీ నీ పాదసంసేవాసక్తి పొందారు కదా జనులు.', 'ధూర్జటి', '', NULL, '4da03f4c58b1bedc3ada085d9b579e8c42f8511544ecd0de96aa5059771a156a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-349', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 100', 'మత్తేభవిక్రీడితము

   చెడుగుల్ కొందఱకూడి చేయఁగఁబనుల్ చీఁకట్లు దూఱఁగఁ
   ల్పడితిం గాని చరింపరాని నిను నొల్లంజాలుఁ బొమ్మంచు ని
   ల్వెడలంద్రోచినఁ జూరుపట్టుకొని నేవ్రేలాడుదుం గోర్కెఁగో
   రెడి యర్థంబులు నాకు వే గలుగావో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! కొందఱు చెడ్డవారితో కూడి నేను పూర్వము కొన్ని పనులు చేసిన మాట నిజమే. కానీ నీ సాన్నిధ్యమును మాత్రము ఎదబాయను. నీవు నన్ను వద్దని మెడ పట్టుకొని గెంటివేసినా నేను మాత్రము నీ చూరు పట్టుకొనే వేలాడుతాను. నేను కోరిన కైవల్యమును నాకు ఎందుకు ప్రసాదించవు ప్రభో?', 'ధూర్జటి', '', NULL, '45c5e92ed1a1076f33874bb27e6c307a59cd335915f0e14ad94b852b1b8a4297') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-350', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 101', 'మత్తేభవిక్రీడితము

   భసితోద్ధూళన ధూసరాంగులో జటాభారోత్తమాంగుల్తపో
   వ్యసనుల్ సాధితపంచవర్ణరసనుల్ వైరాగ్యవంతుల్ నితాం
   త సుఖస్వాంతులు సత్యభాషణ సముద్యద్రత్న రుద్రాక్ష రా
   జి సమేతుల్ తుదనెవ్వరైనఁ గొలుతున్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! భస్మము పూసుకున్నవారు, తలపై జడలు కలిగినవారు, నిత్యమూ తపస్సు చేయువారు, పంచాక్షరీ మంత్రమును జపించువారు, సర్వమూ త్యజించినవారు, బ్రహ్మానందమును పొందినవారు, సత్యము అను రత్నమాలను రుద్రాక్షమాలను ధరించినవారు ఏ వర్ణమైననూ కనబదినచో నేను వారిని నీ స్వరూపులుగా భావించి పూజించెదను.', 'ధూర్జటి', '', NULL, 'a736e89a7db7a176732dbb92c3deeabfae4657e88ae260af1fe4c34436237f02') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-351', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 102', 'మత్తేభవిక్రీడితము

   జలజశ్రీఁ గల మంచినీళ్ళు గలవా చట్రాతిలో బాపురే
   వెలివాడన్మఱి బాపనిల్లు గలదా వేసాలుగా కక్కటా
   నలి నా రెండుగుణంబులెంచి మదిలో నన్నేమిరోయంగ నీ
   చెలువంబైన గుణంబు లెంచుకొనవే శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! తామరపూవులతో కూడిన నీళ్ళు చట్రాయి బావిలో ఉండునా? అదే విధముగా మాలవాడలో బ్రాహ్మణుని ఇల్లు ఉండునా? ఉన్నా కూడా అవన్నీ వేషములే కదా. అదే విధముగా నాలో ఎన్ని దుర్గుణములు ఉన్ననూ, నీకు ఇష్టమైన రెండు గుణములు ఎంచుకుని నన్ను అసహ్యించుకొనక కాపాడు', 'ధూర్జటి', '', NULL, 'a98d279310d486fc5990c751b58cf47a41a4b96b2c9cd7f8ed2e7970dc7d30f1') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-352', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 103', 'మత్తేభవిక్రీడితము

   గడియల్ రెంటికొ మూఁటికో గడియకో కాదేని నేఁ డెల్లియో
   కడఁ నేఁడాదికో యెన్నఁడో యెఱుఁగ మీకాయంబు లీభూమిపైఁ
   బడఁగా నున్నవి ధర్మమార్గమొకటిం బాటింప రీమానవుల్
   చెడుగుల్ నీపదభక్తినిం దెలియరో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఈ జీవితమూ ఈ ఘడియో, రెండో, మూడో ఘడియలకో తీరక తప్పదు. ఇది తెలిసి కూడా మూర్ఖమానవులు నీ పాదములను ఆశ్రయించక ధర్మమార్గమును పాటింపకయుందురు కదా', 'ధూర్జటి', '', NULL, '83ec6071c796872a379f6647054337696f675c2694400492ba7da55a48745629') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-353', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 104', 'మత్తేభవిక్రీడితము

   క్షితిలో దొడ్డతురంగసామజము లేచిత్రమ్ము లాందోళికా
   తతు లే లెక్క విలాసినీజన సువస్త్ర వ్రాతభూషాకలా
   ప తనూజాదిక మేమిదుర్లభము నీ పదమ్ములర్చించుచో
   జిత పంకేరుహపాదపద్మయుగళా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నీ పాదపద్మములపైన సంతత చిత్తము కలిగినవాడికి, ఈ భూమిలో పెద్ద గుఱ్ఱములు, ఏనుగులు, పల్లకీలు, స్త్రీలు, వస్త్రములు, బిడ్డలు వంటి వ్యామోహములు ఏ పాటి', 'ధూర్జటి', '', NULL, 'b44aa5b04ea4c596d54c166c0296858e84962868b3883472eaee16c7bc1f2ae4') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-354', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 105', 'మత్తేభవిక్రీడితము

   సలిలమ్మున్జులుక ప్రమాణమొక పుష్పమ్ము న్భవన్మౌళి ని
   శ్చల భక్తి ప్రతిపత్తిచే నరుఁడు పూజల్సేయఁగా ధన్యుఁడౌ
   నిల గంగానదిఁ జంద్రఖండము దానిందుం దుదిన్గాంచు నీ
   చెలువంబంతయు నీ మహాత్త్యమిదిగా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఇంచుక నీరు, ఒక పుష్పము నీ లింగముపైన భక్తితో ఉంచిన మాత్రముననే నీవు ప్రసన్నుడవై ఆ నరునికి గంగానది మొదలు నీ తలపైని చంద్రఖందమును కూడా చూపెదవు కదా. ఆశుతోషుడవు నీవు అని కవి భావము', 'ధూర్జటి', '', NULL, '847a221a4119bec1dc08d7950add7cef34e5d3c3677e35ebb3c9f35fbd5193fb') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-355', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 106', 'మత్తేభవిక్రీడితము

   తమనేత్రద్యుతిఁ దామెచూడ సుఖమై తదాత్త్యమున్గూర్పఁగా
   విమలమ్ముల్కమలాభముల్జతలసద్విద్యుల్లతా లాస్యముల్
   సుమనోబాణ జయప్రదమ్ములనుచున్జూచున్ జనంబూని హా
   రిమృగాక్షీనివహమ్ము కన్నుఁగవలన్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! తమలో నిన్ను గూర్చి ధ్యానించి ఆత్మసాక్షాత్కారము పొంది తమలో తమనే చూసుకొనక ఈ జనులు స్త్రీలకన్నులను చూసి అవి పద్మములని, లేడి కన్నులని, అందముగా ఉన్నవనీ, మెరుపుతీగలని, మన్మథునికి జయము చేకూర్చేవని భావిస్తారు. అహం బ్రహ్మాస్మి అనే స్థితిని పొందక వీరు ఇటువంటి ఇహబంధములయందు చిక్కుకొని ఉంటారని కవి భావము.', 'ధూర్జటి', '', NULL, 'a11ce2c7c4d0a69ce1c01024b335048b5668a63897e58499999023f0757fb43d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-356', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 107', 'మత్తేభవిక్రీడితము

   పాటవద్రజ్జుభుజంగవ ద్రజత విభ్రాంతిస్ఫురచ్ఛుక్తి వ
   ద్ఘటవాచ్చంద్రశిలా జపాకుసుమ రుక్సాంగత్యవత్తంచు వా
   క్పటిమల్నేర్తురు చిత్సుఖం బనుభావింపన్ లేక దుర్మేధసుల్
   చిటుకన్నం దలపోయజూతు రథముల్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! కొందఱు పండితులు దుర్మేధస్సులై ఆత్మానందసుఖము అనుభవింపలేక ఈ జగత్తు అంతా అశాశ్వతమని, వస్త్రమువంటిది అని, పామువంటి తాడు అనే విభ్రాంతి కలిగించునది అని ముత్యపు చిప్ప వెండి పాత్రగా తోచునటువంటిది అని చంద్రకాన్తామని పక్కన మంకెన పువ్విడగా శిలకు కలుగు ఎఱ్ఱని గుణమువంటిది అని, మఱియు చీమ చిటుక్కుమన్న గూడ దానికి నీవే కారణమనీ పూర్తిగా తెలియని ఉపమానములు చెప్పుతూ కాలము గడిపెదరు.', 'ధూర్జటి', '', NULL, 'd63f1d6a145bcb4d91447b92e829657693cdde3ce53669ecaa2ffac5d422f960') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-357', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 108', 'మత్తేభవిక్రీడితము

   నిను నిందించిన దక్షుపైఁ దెగవో వాణీనాధు శాసింపవో
   చనువా నీ పదపద్మసేవకులఁ దుచ్ఛంబాడు దుర్మార్గులన్
   బెనుప న్నీకుం నీదుభక్తతతికిన్ భేదంబు గానంగ వ
   చ్చేనొ లేకుండిన నూరకుండఁగలవా శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! పూర్వము నిన్ను ధిక్కరించిన దక్షుని, బ్రహ్మదేవుని శిరస్సు నీవు తెంపితివి కదా. కానీ ఇప్పుడు నీ భక్తులను సుర్మార్గులు దుర్భాషలు ఆడుచూ ఉంటే పట్టకుండనట్టు ఉన్నావు. నీవరకూ రాలేదు కదా అని తామసము వహించితివా ప్రభో? లేక నీకూ నీ భక్తులకూ భేదము తలచినావా?', 'ధూర్జటి', '', NULL, '9a4157b15017b120df1121857ec5e6e5c029bc551bd7598a1d9b45c05623c766') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-358', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 109', 'మత్తేభవిక్రీడితము

   కరిదైత్యున్బొరిగొన్న శూలము కరగ్రస్తంబుగాదో రతీ
   శ్వరునిన్గాల్చిన ఫాలలోచన శిఖావర్గంబు చల్లారెనో
   పరనిందాపరులన్వధింప విదియున్ భావ్యంబె వారేమి చే
   సిరి నీకున్ బరమోపకార మరయన్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! పూర్వము నీవు గజాసురుని చంపిన శూలము నీచేతిలో ఇప్పుడు లేదా? మన్మథుని కాల్చిబూడిద చేసిన మూడో కన్ను మంట చల్లరిందా? పరనిందా పరులు విర్రవీగుతూ ఉంటే వారిని శిక్షింపక మౌనము వహించితివేమి? వారు నీకేమైనా మహోపకారము చేసిరా?', 'ధూర్జటి', '', NULL, 'e1300d76a82459c97d44b05a4d90b7787936a46c0c878a9198919fd178affd1b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-359', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 110', 'మత్తేభవిక్రీడితము

   దురమున్దుర్గము రాయబారము మఱిన్దొంగర్కము న్వైద్య
   మున్ నరనాథాశ్రమ మోడబేరమును బెన్మంత్రంబు సిద్ధించినన్
   ఆర్యన్ దొడ్డఫలంబు గల్గు నదిగా కాకార్యమే తప్పినన్
   సిరియుం బోవును బ్రాణహానియునగున్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! యుద్ధము, కోట ముట్టడి, రాయబారము, దొంగతనము, వైద్యము, రాజాశ్రయము, నౌకా వ్యాపారము, మంత్రసాధన, ఇవి సిద్ధించిన మంచి లాభము కలుగును కానీ ఒకవేళ ఇవి కనుక వికటిస్తే ధనము హరించి పోవడమే కాక ప్రాణహాని కూడా కలుగును', 'ధూర్జటి', '', NULL, 'ec4411cb118727280ea9982874fbe623b3474141222c172bc8f0415e1ba8725b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-360', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 111', 'మత్తేభవిక్రీడితము

   తనయుం గాంచి ధనంబులిచ్చి దివిజస్థానంబు గట్టించి వి
   ప్రున కుద్వాహము చేసి సత్కృతికిఁ బాత్రుండై తటాకంబు నే
   ర్పునఁ ద్రవ్వించి వనంబువెట్టి మననీ పోలేఁడు నీ సీవ చే
   సిన పుణ్యాత్ముఁడు పోవులోకమునకున్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఎవరైనా కానీ కొడుకులను కని, దానములు చేసి, గుడి కట్టించి, బ్రాహ్మణులకు మేలు చేసి, వారి దయకు పాత్రుడై, చెరువులు త్రవ్వించి, చేట్లు పెంచి ఇంట మంచి చేసినా కూడా నీ భక్తులు చేరు బ్రహ్మపదమును చేరలేరు.', 'ధూర్జటి', '', NULL, 'ab7ef8a3331c11c961813f377d8c6a66d51a200a16ac37a4e70ac461656e061a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-361', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 112', 'మత్తేభవిక్రీడితము

   క్షితినాథోత్తమ సత్కవీశ్వరుఁడు వచ్చెన్ మిమ్ములం జూడగా
   నతఁడే మేటి కవిత్వవైఖరిని సద్యఃకావ్యనిర్మాత త
   త్ప్రతిభల్మంచివి తిట్టు పద్యములు చెప్పండాతఁడన్నన్ మముం
   గ్రితమే చూచెను బొమ్మటందు రధముల్ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఎవరేని రాజువద్దకు ఒక మంచి కవి రాగా అతని పరిచారకులు ''రాజా, ఇతడు మంచి కవి, మంచి కవిత్వమును చెప్పునే కానీ తిట్టు కవిత్వము కాదు'' అని చెప్తే ఆ రాజాధముడు ఈ కవిని ముందే చూచినాను పొమ్మని చెప్పండి అనువారు ఎక్కువ. (అట్టి రాజాధములను కాక నీ సేవ చేసుకోనెదనని కవి భావము)', 'ధూర్జటి', '', NULL, '2ea1a208064305af5ba860b0e952351a4b02448047b86828254d903957ff5b58') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-362', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 113', 'శార్దూలవిక్రీడితము

   నీకుంగాని కవిత్వమెవ్వరికి నేనీనంచు మీఁదెత్తితిన్
   జేకొంటిం బిరుదంబు కంకణము ముంజేఁ గట్టితిం బట్టితిన్
   లోకుల్ మెచ్చ వ్రతంబు నాతనువుకీలున్ నేర్పులుంగావు చీ
   చీ కాలంబులరీతి దప్పెడుఁ జుమీ శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! నా కవిత్వము నీకు కాక వేరెవ్వరికీ నేను అంకితమివ్వను అని ప్రతిన బూనితిని. దీనికి లోకులు మెచ్చు విధముగా శైవుడనని బిరుదము పొంది కంకణము ముంజేతిలో తొడిగితిని. ఇది నా నేర్పు కాదు నీ మీద భక్తి అని నేను అనుకున్న, లోకము మారి ఇప్పుడు జనులు ఇది మెరమెచ్చుల కోసమని అందురు.', 'ధూర్జటి', '', NULL, 'a536d0a3ec5a38085d3e965365e055f46621ac0c69b75760700a5a94feb11116') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-363', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 114', 'శార్దూలవిక్రీడితము

   నిచ్చల్ నిన్ను భజించి చిన్మయ మహానిర్వాణపీఠంబుపై
   రచ్చల్సేయక యార్జవంబు కుజనవ్రాతంబుచేఁ గ్రాఁగి భూ
   భృచ్చండాలురఁ గొల్చి వారు దనుఁ గోపింపం బుదుండార్తుఁడై
   చిచ్చారం జమురెల్లఁ జల్లుకొనునో శ్రీకాళహస్తీశ్వరా!
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! మంచి పండితులు నిన్ను కొలిచి మహానిర్వాణ పదవిని పొందక, జనుల మాటలు విని, చెడు రాజుల ఆశ్రయము గోరి వారిని భజింపపోదురు. వారు కోపించిన వారి స్థితి మంటలు చల్లార్చుకొనుటకు నూనె మీద పోసుకున్న విధముగా ఉంది.', 'ధూర్జటి', '', NULL, '23a654b26d266f428a60fb2a4cfb5b8599c56b779de8b2aaca141802546528d9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-364', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీకాళహస్తీశ్వర శతకం – పద్యం 115', 'శార్దూలవిక్రీడితము

   దంతంబుల్పడనప్పుడే తనువునందారూఢి యున్నప్పుడే
   కాంతా సంఘము రోయనప్పుడే జరాక్రాంతంబు గానప్పుడే
   వింతల్మేన జరింపనప్పుడే కురుల్వెల్వెల్ల గానప్పుడే
   చింతింపన్వలె నీపదాంబుజములన్ శ్రీకాళహస్తీశ్వరా!
   
తాత్పర్యము: ప్రభో, శ్రీకాళహస్తీశ్వరా! ఇంకా పండ్లు ఊడిపోకమునుపే, శరీరములో సత్త్వము ఉన్నపుడే, స్త్రీలు ముదిమివల్ల తమను అసహ్యించుకోక మునుపే, ముదిమి మీదపడక ముందే, తనువులో వింతలు (క్రొత్త రోగములు) పుట్టకముందే నీ పాదాంబుజములను సేవించవలెను స్వామీ, ప్రభో, శ్రీకాళహస్తీశ్వరా!


|| ధూర్జటి మహాకవి ప్రణీతంబైన శ్రీకాళహస్తీశ్వర శతకము సంపూర్ణము ||', 'ధూర్జటి', '', NULL, '995c0f96a6358fb0630675b6e97c39864c311d31081f197e402b89b12dd38cce') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-365', 'శతకాలమాల', 'జ్ఞానమాల', 'కృష్ణ శతకము – పద్యం 1', 'శ్రీ రుక్మిణీశ కేశవ

నారద సంగీత లోల నగధర శౌరీ

ద్వారక నిలయ జనార్ధన

కారుణ్యము తోడ మమ్ము గావుము కృష్ణా', 'నరసింహ కవి', '', NULL, '8c25f14fa58207f49919d6d8b30c2bf0efc0eee982da37c08429ffdef11a6306') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-366', 'శతకాలమాల', 'జ్ఞానమాల', 'కృష్ణ శతకము – పద్యం 2', 'నీవే తల్లివి దండ్రివి

నీవే నా తోడునీడ నీవే సఖుడౌ

నీవే గురుడవు దైవము

నీవే నా పతియు గతియు నిజముగ కృష్ణా', 'నరసింహ కవి', '', NULL, 'fba87228c8f6110a0f749c3381bf2531c8be47a1b5768bbe69749b70ed1049a6') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-367', 'శతకాలమాల', 'జ్ఞానమాల', 'కృష్ణ శతకము – పద్యం 3', 'నారాయణ పరమేశ్వర

ధారాధర నీలదేహ దానవ వైరీ

క్షీరాబ్ధిశయన యదుకుల

వీరా ననుగావు కరుణ వెలయగ కృష్ణా', 'నరసింహ కవి', '', NULL, '1b8f33be74a9e8d08bbbd2f57e76d78f70f764b743cc80cff75b5b37bd495872') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-368', 'శతకాలమాల', 'జ్ఞానమాల', 'కృష్ణ శతకము – పద్యం 4', 'హరి యను రెండక్షరములు

హరియించును పాతకముల నంబుజనాభా

హరి నీ నామ మహాత్మ్యము

హరి హరి పొగడంగ వశమె హరి శ్రీకృష్ణా', 'నరసింహ కవి', '', NULL, 'f3314376bbee537545efa22e58c2584a2278549493a87014cfbdeb4e4645c3d3') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-369', 'శతకాలమాల', 'జ్ఞానమాల', 'కృష్ణ శతకము – పద్యం 5', 'క్రూరాత్ముడజామీళుఁడు

నారాయణ యనుచు నాత్మనందను బిలువన్

ఏ రీతి నేలుకొంటివి

యేరీ నీసాటి వేల్పు లెందును కృష్ణా', 'నరసింహ కవి', '', NULL, '564e1bfcfb73408c16c76d0ec6eff02057056e666768a45cc7c65e5106dbfceb') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-370', 'శతకాలమాల', 'జ్ఞానమాల', 'కృష్ణ శతకము – పద్యం 6', 'చిలుక నొక రమ఩ణి ముద్దులు

చిలుకను శ్రీరామయనుచు శ్రీపతి పేరుం

బిలిచిన మోక్షము నిచ్చితివ

వలరగ మిము దలఁచు జనులకరుదా కృష్ణా', 'నరసింహ కవి', '', NULL, '451feb53ea34973e83eaae262c770e5e89adaf2281675a7b6e75fa53add5951c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-371', 'శతకాలమాల', 'జ్ఞానమాల', 'కృష్ణ శతకము – పద్యం 7', 'అకౄరవరద! మాధవ!

చక్రాయుధ! ఖడ్గపాణి! శౌరి! ముకుందా!

శక్రాది దివిజ సన్నుత!

శుక్రార్చిత! నన్ను కరుణ జూడుము కృష్ణా!', 'నరసింహ కవి', '', NULL, 'a89053a387017fadda36a438f63a292782da4324662bc256b4a78b2fa05c9990') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-372', 'శతకాలమాల', 'జ్ఞానమాల', 'కృష్ణ శతకము – పద్యం 8', 'నందుని ముద్దుల పట్టిని

మందరగిరిధరుని హరిని మాధవు విష్ణున్

సుందరరూపుని మునిగణ

వందితు నిను దలంతు భక్తవత్సల! కృష్ణా!', 'నరసింహ కవి', '', NULL, '2a3ba1d6de885a1542dca17e779515b455c702135be1117bed208c2408b5ad45') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-373', 'శతకాలమాల', 'జ్ఞానమాల', 'కృష్ణ శతకము – పద్యం 9', 'ఓ కారుణ్య పయోనిధీ!

నా కాధారంబ వగుచు నయముగ బ్రోవన్

నాకేల ఇతర చింతలు

నాకాధిప వినుత! లోకనాయక కృష్ణా!', 'నరసింహ కవి', '', NULL, 'a60a7178b49bbe8b616c29425429b0817408a2805cbadabed26bb176cfedefe4') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-374', 'శతకాలమాల', 'జ్ఞానమాల', 'కృష్ణ శతకము – పద్యం 10', 'వేదంబులు గననేరని

ఆది పరబ్రహ్మమూర్తివనఘ! మురారీ;

