INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-473', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 8', 'నీపుత్రుండు చరాచర ప్రతతుల న్నిర్మించి పెంపారఁగా
