INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-474', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 9', 'బ్రహ్మాండావలిలోన సత్వగుణివై బాహ్యంబునం దాదిమ
