INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-475', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 10', 'ధర సింహాసనమై నభంబు గొడుగై తద్దేవతల్ భృత్యులై
