INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-476', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 11', 'మగమీనాకృతి వార్ధిఁజొచ్చి యసుర న్మర్ధించి యవ్వేదముల్
