INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-481', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 16', 'ధరణిన్ రక్తమహాహ్రదంబు లెలమిం ద్రైలోక్య నిర్దిష్టమై
పరగం బైతృక తర్పణంబుకొఱకై ప్రఖ్యాతిగాఁ దీవ్రతన్
నిరువయ్యొక్కటిమారు క్షత్రమరుల న్నేపార నిర్జించి త
