INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-482', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 17', 'వరుసం దాటకిఁ జంపి కౌశికు మఘస్వాస్థ్యంబు గావించి శం
కరుచాపం బొగిఁద్రుంచి జానకిఁ దగం గల్యాణమై తండ్రి పం
