INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-483', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 18', 'యదువంశంబునఁ గృష్ణు కగ్రజుఁడవై యాభీల శౌర్యోన్నతిన్
మదవద్ధేనుక ముష్టికాద్యసురులన్ మర్ధించి లీలారసా
స్పదకేళీరతి రేవతీవదన కంజాతాంతబృంగంబనన్
