INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-484', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 19', 'పురముల్మూడుఁను మూఁడులోకములు నేప్రొద్దు న్విదారింపఁ ద
