INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-485', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 20', 'కలిధర్మంబునఁ బాపసంకలితులై గర్వాంధులై తుచ్చులై
