INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-486', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 21', 'ఇరవొందన్ సచరాచరప్రతతుల న్నెన్నంగ శక్యంబుకా
