INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-488', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 23', 'జగదాధారక! భక్తవత్సల! కృపాజన్మాలయా పాంగ! భూ
