INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-509', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 44', 'ఉల్లోలంబులుగాఁ గురుల్ నుదుటిపైనుప్పొంగ మోమెత్తి ధ
మ్మిల్లం బల్లలనాడ రాగరస సమ్మిశ్రంబుగా నీవు వ్రే
పల్లెందాడుచు గోపగోనివహ గోపస్త్రీలయుల్లంబు మీ
