INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-510', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 45', 'కసవొప్పన్ పసి మేసి ప్రొద్దుగలుగం గాంతారముం బాసి య
