INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-511', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 46', 'చన్నుల్ మీఁదికి చౌకళింప నడుముం జవ్వాడ కందర్పసం
