INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-512', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 47', 'పెరుగుల్ ద్రచ్చుచు నొక్కగోపిక మిముం బ్రేమంబునం జూచి రా
