INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-513', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 48', 'కేలన్ గోలయు గూటిచిక్కము నొగిం గీలించి నెత్తంబునం
