INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-514', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 49', 'కాళిందీతటభూమి నాలకదుపుల్ కాలూఁది మేయన్ సము
