INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-515', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 50', 'రాణించెన్ గడునంచు నీసహచరుల్ రాగిల్లి సోలంగ మీ
