INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-516', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 51', 'పసులంగాపరి యేమెఱుంగు మధురప్రాయోల్లాసద్వృత్తవా
