INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-517', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 52', 'జడియొంతేఁ దడవయ్యె జెయ్యియలసెన్ శైలంబు మాచేతులం
