INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-518', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 53', 'లలితాకుంచితవేణి యందడవి మొల్లల్ జాఱ ఫాలస్థలిన్
