INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-519', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 54', 'మాపాలం గడుగ్రొవ్వి గోపికలతో మత్తిల్లి వర్తింతువే
