INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-520', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 55', 'ఒక కాంతామణి కొక్కడీవు మఱియున్నొక్కరై కొక్కండవై
