INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-523', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 58', 'రసనాగ్రంబున నీదునామరుచియున్ రమ్యంబుగాఁ జెవ్లుకు
