INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-525', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 60', 'చల్లల్వేఱొకయూర నమ్ముకొను నాసంబొవుచోఁ ద్రోవ నీ
