INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-526', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 61', 'కలయన్వేదములున్ బురాణములు బ్రఖ్యాతంబుగా తెల్పి మీ
