INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-537', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 72', 'వెరవొప్ప న్బహుశాస్త్రమంత్రము లొగి న్వీక్షించి వేతెల్పిమీ
వరనామామృతపూర మానుచుఁ దగన్ వైరాగ్యభావంబునన్
సరి నశ్రాంతముఁ గోరువారు పిదపన్ సంద్సారమాతుఃపయో
