INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-538', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 73', 'వేదంబందు సునిశ్చయుండగు మహా వేల్పెవ్వఁడో యంచు నా
