INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-540', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 75', 'ప్రమదం బారగఁ పుణ్యకాలగతులన్ భక్తిన్ననుష్ఠింపుచున్
