INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-558', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 93', 'నినువర్ణింపనివాఁడు మూఁగ మదిలో నీనామమున్ వీనులన్
విని మోధింపనివాండు చెవ్డుమరినిన్ వేడ్కన్ మనోవీధినిన్
గనిపూజింపనివాఁడు నాశకరుఁడౌ కర్మక్రియారంభుండై
