INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-559', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 94', 'నినువర్ణింపని నీచబంధమతి దానిర్మగ్నమూఢాత్ముఁడై
పెనుదైవంబులఁ గోరి తా మనమునన్ సేవించుచందంబుతా
ననలం బారిన భూతియందు వెలయ న్నాజ్యాహుతుల్ పూనివే
