INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-560', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 95', 'నిను వర్ణింపని జిహ్వదాఁబదటికా? నీలాభ్రదేహాంగకా
నినునాలింపనిచెవులు దాఁబదటికా! నీరజపత్రేక్షణా
నినుఁబూజింపని కేలు దాఁ బదటికా? నిర్వాహకక్ష్మాతలా
