INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-561', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 96', 'నీవేతల్లివి నీవేతండ్రి వరయన్నీవే జగన్నధుఁడౌ
