INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-562', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 97', 'అపరాధంబులు నిన్ను నమ్మి వినుమే నాజన్మపర్యంతమున్
