INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-563', 'శతకాలమాల', 'జ్ఞానమాల', 'నారాయణ  శతకము – పద్యం 98', 'చెల్లంజేసితి పాతకంబులు మదిన్ శ్రీనాధ మీనామముల్
