INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-593', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీ (అలమేలుమంగా) వేంకటేశ్వరశతకము – పద్యం 23', 'ఉ. అందవు కోసి యిమ్ము విరు లంచును జే రలమేలుమంగ ని
న్నందగఁగోరఁ జెక్కులటు నొక్కిన నాకును నందవంచు న
