INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-654', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీ (అలమేలుమంగా) వేంకటేశ్వరశతకము – పద్యం 84', 'ఉ. చక్కదనంబు రాశి నునుసానలన్‌ బట్టినపువ్వుటమ్ములోఁ
