INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-684', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 23', 'కరోమి త్వత్పూజాం సపది సుఖదో మే భవ విభో
