INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-686', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 25', 'స్తవైర్బ్రహ్మాదీనాం జయజయవచోభిః నియమానాం
