INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-687', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 26', 'కదా వా త్వాం దృష్ట్వా గిరిశ తవ భవ్యాంఘ్రియుగలం
