INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-690', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 29', 'త్వత్పాదాంబుజమర్చయామి పరమం త్వాం చిన్తయామ్యన్వహం
