INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-691', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 30', 'వస్త్రోద్ధూత విధౌ సహస్రకరతా పుష్పార్చనే విష్ణుతా
