INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-692', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 31', 'నాలం వా పరమోపకారకమిదం త్వేకం పశూనాం పతే
