INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-693', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 32', 'జ్వాలోగ్రస్సకలామరాతిభయదః క్ష్వేలః కథం వా త్వయా
దృష్టః కిం చ కరే ధృతః కరతలే కిం పక్వ జంబూఫలమ్ ।
జిహ్వాయాం నిహితశ్చ సిద్ధఘుటికా వా కణ్ఠదేశే భృతః
కిం తే నీలమణిర్విభూషణమయం శంభో మహాత్మన్ వద', 'ఆది శంకరాచార్యులు', '', NULL, '3195851cb7205cdfc213b516c46e062c57af5ddc3288dbe7e5610b707bd56923') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-694', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 33', 'నాలం వా సకృదేవ దేవ భవతస్సేవా నతిర్వా నుతిః
పూజా వా స్మరణం కథాశ్రవణమప్యాలోకనం మాదృశామ్ ।
స్వామిన్నస్థిరదేవతానుసరణాయాసేన కిం లభ్యతే
