INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-696', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 35', 'యోగక్షేమధురంధరస్య సకలఃశ్రేయః ప్రదోద్యోగినో
