INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-697', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 36', 'భక్తో భక్తిగుణావృతే ముదమృతాపూర్ణే ప్రసన్నే మనః
కుమ్భే సాంబ తవాంఘ్రిపల్లవ యుగం సంస్థాప్య సంవిత్ఫలమ్ ।
సత్త్వం మన్త్రముదీరయన్నిజ శరీరాగార శుద్ధిం వహన్
