INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-698', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 37', 'ఆమ్నాయాంబుధిమాదరేణ సుమనస్సంఘాఃసముద్యన్మనో
