INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-699', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 38', 'ప్రాక్పుణ్యాచలమార్గదర్శితసుధామూర్తిః ప్రసన్నశ్శివః
