INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-700', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 39', 'ధర్మో మే చతురంఘ్రికః సుచరితః పాపం వినాశం గతం
కామక్రోధమదాదయో విగలితాః కాలాః సుఖావిష్కృతాః ।
జ్ఞానానన్దమహౌషధిః సుఫలితా కైవల్య నాథే సదా
మాన్యే మానసపుణ్డరీకనగరే రాజావతంసే స్థితే', 'ఆది శంకరాచార్యులు', '', NULL, '9a3f2299ae9e27b1a231fd6e462eed268b5ff134ef06d6aabe843708fb0a7260') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-701', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 40', 'ధీయన్త్రేణ వచోఘటేన కవితాకుల్యోపకుల్యాక్రమైః
