INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-703', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 42', 'గాంభీర్యం పరిఖాపదం ఘనధృతిః ప్రాకార ఉద్యద్గుణ
