INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-704', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 43', 'మా గచ్ఛ త్వమితస్తతో గిరిశ భో మయ్యేవ వాసం కురు
