INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-706', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 45', 'ఛన్దశ్శాఖి శిఖాన్వితైః ద్విజవరైః సంసేవితే శాశ్వతే
