INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-707', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 46', 'ఆకీర్ణే నఖరాజికాన్తివిభవైరుద్యత్సుధావైభవైః
ఆధౌతేపి చ పద్మరాగలలితే హంసవ్రజైరాశ్రితే ।
నిత్యం భక్తివధూ గణైశ్చ రహసి స్వేచ్ఛావిహారం కురు
