INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-708', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 47', 'శంభుధ్యానవసన్తసంగిని హృదారామేఅఘజీర్ణచ్ఛదాః
