INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-724', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 63', 'మార్గావర్తిత పాదుకా పశుపతేరఙ్గస్య కూర్చాయతే
