INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-725', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 64', 'వక్షస్తాడనమన్తకస్య కఠినాపస్మార సంమర్దనం
