INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-726', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 65', 'వక్షస్తాడన శంకయా విచలితో వైవస్వతో నిర్జరాః
