INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-727', 'శతకాలమాల', 'జ్ఞానమాల', 'శివానందలహరి – పద్యం 66', 'క్రీడార్థం సృజసి ప్రపంచమఖిలం క్రీడామృగాస్తే జనాః
