INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-796', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 35', 'పరభూపాలుర నోర్చి తెచ్చువసుసంపత్తి న్స్వదేశీయులం
బొరయం జేసిరి పూర్వమందు నృపు; లిప్డో! దేశభాగ్యంబుఁ జె
చ్చెర దూరస్థవిదేశవాసులను నిశ్చితంబుగాఁ జేరని
త్తురు భూభర్త లధర్మకార్యమిది గాదో! రామచంద్ర

