INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-797', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 36', 'నేఁ డుచ్చస్థితి నున్న దేశవిభుఁ డెందేఱేని కేమాత్రమో
తోడై వానిని దాను రాజ్యపదముక్తుం జేసి పాలించు; నా
నాఁ డర్కాత్మజరావణానుజులకు న్సహాయ్యముం జేసి చూ
ఱాడ న్లేదు తదర్థ మీ విఁక మహాత్మా! రామచంద్ర

