INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-798', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 37', 'పరదేశములనుండి రావలయు సర్వంబున్; స్వదేశస్థు లె
వ్వరు నందొండును జేయలేరు; పరికింపంగ న్బరాపేక్ష యు
ద్ధుర మౌచున్న; దశక్తి హెచ్చుకొలఁది న్గుర్భోగవస్త్వశయుం
బెరుఁగం జొచ్చె; నిఁకేమి చేసెదవొసుమ్మీ! రామచంద్ర

