INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-799', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 38', 'ధీమంతుండగు మానవుండు తనబుద్ధి న్లోకబాధాపహం
బై మోదంబును గూర్చు నౌషధములు న్యంత్రంబులు న్జేయనౌ;
నామూలం బిఁకఁ బ్రాణులం గెడపుదుర్యంత్రాదుల న్జేయుటెం
తో మారాత్మకదైత్యకృత్యమగు నయ్యో! రామచంద్ర

రామచంద్రప్రభూ!', 'కూచి నరసింహము', '', NULL, 'fec9de91c33425c8d092ed04b8f36d1e8f39ed379dc078cf703e06f3f2718c5d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-800', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 39', 'ధీరత్వంబున నాత్మతేజమున నుద్దీపించి దేశార్తులన్
బాఱంద్రోల నహింసఁ బూని తమకౌ బాధల్క్షమ న్సైఁచుచున్
బోరంజొచ్చుస్వకీయులన్ ధనముకై పోకార్చి ధర్మంబులన్
గారం బెట్టుట పట్టినీచకృతి యౌగా! రామచంద్ర

