INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-801', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 40', 'ఇతరు ల్గృహము సొచ్చి పాలనము తామే సేయుచుండ, న్స్వతం
త్రతతో నన్నియుఁ జావ, వారొసఁగు ప్రాణత్రాణమాత్రాన్నపుం
బ్రతుకే దీనత నింద్రభోగ మనుచు న్భావించు గేస్తుండు తా
మతిలేనట్టినరుండు గాఁడె? గుణధామా! రామచంద్ర

