INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-802', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 41', 'ప్రజల న్బిడ్డలఁబోలెఁ జూచుకొనుచు న్వారర్థసౌఖ్యాదులం
దు జగత్ఖ్యాతిని బొంద నేలఁగ సమర్థుం డెవ్వఁ డాతండె పో
నిజమౌరా; జిఁక వారిలో జగడము ల్నెక్కొల్పి తామించుఱే
ని జగామ్రుచ్చని కాక రా జనఁగఁ జన్నే? రామచంద్ర

