INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-803', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 42', 'ఆయాసక్షమ, యైకమత్యము, దవీయశ్చింతయు, న్ధైర్యమున్
స్థేయోయత్నము, దేశభక్తియు, నకుంఠితభూతకౌశల్య, మాం
గ్లేయు ల్చూపుదు; రవ్వి మా కెపుడిట న్లేవో! గతంబయ్యెనో!
