INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-804', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 43', 'ఱి నాంగ్లేయులు భూనభంబులకు సంబంధంబుఁ గల్పించి, తెం
