INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-809', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 48', 'పంగుత్వంబును దృష్టిలోపమువలెం బాపస్వభావంబునున్
సంగీతంబున కడ్డురా; దితరమౌ శాస్త్రంబులు న్నీతిలే
మిం గీడ్పాటును జెంద వంతగ నిజంబే, కాని నీభక్తిఁ గాం
చంగంజాలఁడు నీతిబాహ్యుఁడెవఁ డీశా! రామచంద్ర

రామచంద్రప్రభూ!', 'కూచి నరసింహము', '', NULL, '4d24d918cbd1f3fdca11a5418f6ff561aa4d2647ed85932bd770ab50fa23f9e4') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-810', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 49', 'అఱపద్దెంబున ధర్మ మెల్లఁ బ్రతిపాద్యంబౌనటు ల్పూజ్యులౌ
పరుషు ల్పూర్వులు వల్కినారు - కననౌఁ బుణ్యంబు నన్యోపకా
రరతిం, బాపము నన్యపీడన మెనర్పం గోరఁగా - నం చిఁకన్
దరియింపం బెఱబోధ మేల? మహితాత్మా! రామచంద్ర

రామచంద్రప్రభూ!', 'కూచి నరసింహము', '', NULL, 'a84a51212c960e526548864791865c4d4979ebfec95cf22ef899cf324374a328') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-811', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 50', 'తిరమౌ నింద్రియనిగ్రహంబు, దమ, మస్తేయంబు, శౌచంబు క్షాం
తి, రుషాభావము, బుద్ధి, మంచిచదువు, ంధీర్త్వము, న్సత్యమున్
వరధర్మంబులటంచు ఁదొంతి స్మృతి తా వాక్రుచ్చు స్పష్టంబుగాఁ;
దరియింపం బెఱబోధ మేటికి? మహాత్మా! రామచంద్ర

రామచంద్రప్రభూ!', 'కూచి నరసింహము', '', NULL, 'a58747c96822bd8afad63ba44c25387aff9433a74e5ccfab442efa24789d5e5a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-812', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 51', 'ధరణి న్మానవుఁ డేయుపాయముననో తా నెట్టిదౌడేహినో
పొరయంజేయవలె న్ముదం; బదియె యౌ బూర్ణేశ్వరారాధనఁ
బరయంగా; నని శ్లోకమందు నొకధన్యాత్ముండు బోధించెడున్;
ధరియింపం బెఱబోధ మేల? పరమాత్మా! రామచంద్ర

రామచంద్రప్రభూ!', 'కూచి నరసింహము', '', NULL, '6eaea2e476b925e0c80a28f5a131fc415d3b9f188c58207e69465b0e70118bb8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-813', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 52', 'ధరలో శూరుఁ డనంజితేంద్రియుఁడె సద్ధర్మంబుల న్నిత్య మా
చరణంబందునఁ జూపువాఁడె కృతి వాక్శౌండుండు సత్యోక్తియే;
యరయ న్భూతదయాగరుష్ఠుఁడె వదాన్యాగ్రేసరుం డండ్రుగా
తరియింపం బెఱబోధమేటికి మహాత్మా! రామచంద్ర

రామచంద్రప్రభూ!', 'కూచి నరసింహము', '', NULL, '1ac681973c048807aec5baf4b375885abc8b704748a9f51b6f6498994ebcb2a8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-814', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 53', 'అనుశంబు న్సుఖిఁ జూచి మైత్రి, కృప దుఃఖార్తు న్విలోకించి పు
ణ్యుని వీక్షించి ముదం, బపుణ్యుఁ గనుచో సోపేక్షతావృత్తి భా
వనలీమాడ్కిని బోవుచో నొదవు సుస్వాంతప్రసాదం బటం
చను సూత్రం; బదినాకు నీ వొసఁగవయ్యా! రామచంద్ర

రామచంద్రప్రభూ!', 'కూచి నరసింహము', '', NULL, '7c4fcde3328ebe1c6a8360f9ea04f8aad75486d1ce2ad9e1b8eaf2770d18c195') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-815', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 54', 'అది ఇమ్మంచు ని దిమ్మటంచు నిను నే నర్థింపఁగా నాకెదన్
బెదరౌ; దానను నాకు మే లగునొ పిర్వీఁకౌనొకించిజ్జ్జుఁడన్
విదితం బౌ నెటు నాకుఁ? గాన, నెది గావింపంగ నీకిష్టమో,
యదె కానిమ్మని వేఁడుకొందుఁ బరమాత్మా! రామచంద్ర

రామచంద్రప్రభూ!', 'కూచి నరసింహము', '', NULL, '9b39c4ea97899c8bd18a83e8ca7701200ebdd9ed961364109e07b16735404e46') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-816', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 55', 'శివునిం జూడ నటంచు వైష్ణవుఁ, డిఁక న్శ్రీజాని నేఁ జూడ నం
చు విరోధంబున శైవుఁ, డందు; రెదలోఁ జూడంగ లే దిర్వురం
దెవఁడు న్వారియధార్థతత్వ; మదియే వీక్షించుచో నేకమౌ
శివుఁడు న్నీవును సర్వదైవములు న్శ్రీరామచంద్ర

రామచంద్రప్రభూ!', 'కూచి నరసింహము', '', NULL, '86c81308d5a1c199050b6a34566047fd52b343be0aa12a1707415ecd89c525dd') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-817', 'శతకాలమాల', 'జ్ఞానమాల', 'రామచంద్రప్రభు – పద్యం 56', 'మనముం జూడఁ బ్రమేయమైన; దిఁక నీమాహాత్మ్యమో! కాలదే
శనిమిత్తంబుల దాఁటియుండుఁ; గనుక న్స్వాంతంబున న్నిన్నుఁగాం
చ నశక్యం; బది గిద్దలోపలను గుంచంబు న్గుదింపంగఁజూ
