INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-926', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీ యాజ్ఞవల్క్య శతకం – పద్యం 66', '66. ఉ. చింతయె లేని జీవనము సిద్ధిని పొందఁగ మార్గమౌను. ని
