INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-938', 'శతకాలమాల', 'జ్ఞానమాల', 'శ్రీ యాజ్ఞవల్క్య శతకం – పద్యం 78', '78. ఉ. సుతులని, పత్నియంచు, ధనశోభయటంచు మనంబునెంచి, సం
