INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1210', 'కథామాల', 'జ్ఞానమాల', 'మామిడి పండు', 'చెట్టుపై పండు ఉంది.
పిల్లవాడు తిన్నాడు.
తీపిగా ఉంది.
పిల్లవాడు నవ్వాడు.', '1 – 4 సంవత్సరాలు వయస్సు', 'ప్రకృతి ఫలాలు మంచివి.', NULL, 'df7520f752b02ced1ea12ab07b356a9f0e5cb8490db08bd2a85089a74656cb94') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1211', 'కథామాల', 'జ్ఞానమాల', 'చిన్న పాప తలస్నానం', 'అమ్మ తలస్నానం చేయించింది.
పాప నవ్వింది.
శుభ్రంగా అయింది.
అందరూ ఆనందించారు.', '1 – 4 సంవత్సరాలు వయస్సు', 'శుభ్రత మంచిది.', NULL, '46d48441e412fcd5701fa6e3c9a504b1fa1fdf17ca6c1ec73d6976f5975db529') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1212', 'కథామాల', 'జ్ఞానమాల', 'చిన్న బస్సు', 'ఒక బస్సు వచ్చింది.
పిల్లలు ఎక్కారు.
పాటలు పాడారు.
అందరూ సంతోషించారు.', '1 – 4 సంవత్సరాలు వయస్సు', 'ప్రయాణం ఆనందం ఇస్తుంది.', NULL, '907122e43cd6c71839e5c2195fa8bfe9d94fb82464a04da364380eba3fe2f5eb') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1213', 'కథామాల', 'జ్ఞానమాల', 'పసుపు పువ్వు', 'ఒక పసుపు పువ్వు ఉంది.
తేనెటీగ వచ్చింది.
తేనె తీసుకెళ్లింది.
రెండూ సంతోషించాయి.', '1 – 4 సంవత్సరాలు వయస్సు', 'పంచుకోవడం మంచిది.', NULL, 'b2524316fa807bd1bf81eb100fccde5c3ec403cb5e74ee7179059c6d60bf518b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1214', 'కథామాల', 'జ్ఞానమాల', 'చిన్న పాప నృత్యం', 'పాట వినిపించింది.
పాప నాట్యం చేసింది.
అందరూ చూశారు.
అందరూ నవ్వారు.', '1 – 4 సంవత్సరాలు వయస్సు', 'నృత్యం ఆనందం ఇస్తుంది.', NULL, 'b42aa9b3fc0a2383ed7a0796661337cffd38ba06261cfa76d6f188606d774712') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1215', 'కథామాల', 'జ్ఞానమాల', 'తోట', 'ఇంటి తోటలో పువ్వులు ఉన్నాయి.
పిల్లలు నీరు పోశారు.
పువ్వులు నవ్వాయి.
అందరూ సంతోషించారు.', '1 – 4 సంవత్సరాలు వయస్సు', 'మొక్కలను పెంచాలి.', NULL, '1d5fe0fdbcf28ca5244301a7f683dabf1462aa333646b2eeb6f1682f0388366a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1216', 'కథామాల', 'జ్ఞానమాల', 'ఆవు', 'ఒక ఆవు ఉంది.
అది పాలు ఇచ్చింది.
పిల్లలు తాగారు.
అందరూ ఆరోగ్యంగా ఉన్నారు.', '1 – 4 సంవత్సరాలు వయస్సు', 'జంతువులు మనకు సహాయం చేస్తాయి.', NULL, '33e373bcaa049d515ffdebd4b5ba14886fe3a18461e63810275f6c1855a6e73c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1217', 'కథామాల', 'జ్ఞానమాల', 'మొదటి బడి', 'పిల్లవాడు మొదటిసారి బడికి వెళ్లాడు.
టీచర్ నవ్వింది.
స్నేహితులు దొరికారు.
పిల్లవాడు సంతోషించాడు.', '1 – 4 సంవత్సరాలు వయస్సు', 'బడి ఆనందం ఇస్తుంది.', NULL, '37d348ea2a0a00c77710bca1c84763fdd07602f5ec190c7561c5aa5547357e82') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1218', 'కథామాల', 'జ్ఞానమాల', 'తెలివైన కాకి', 'ఒక కాకికి దాహం వేసింది.
కుండలో నీళ్ళు తక్కువగా ఉన్నాయి.
కాకి రాళ్ళు వేసింది.
నీళ్ళు పైకి వచ్చాయి.
కాకి తాగింది.', '5 – 7 సంవత్సరాలు వయస్సు', 'తెలివిగా ఆలోచిస్తే పని అవుతుంది.', NULL, '93a37b74f6c866206f87c1926ccbbe58f380504b2e8bd70b353a7d0c4dd9342d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1219', 'కథామాల', 'జ్ఞానమాల', 'మంచి మాట', 'ఒక పిల్లవాడు తప్పు చేశాడు.
స్నేహితుడు కోపంగా మాట్లాడాడు.
పిల్లవాడు బాధపడ్డాడు.
తర్వాత క్షమాపణ చెప్పాడు.
స్నేహం తిరిగి వచ్చింది.', '5 – 7 సంవత్సరాలు వయస్సు', 'మాటలు జాగ్రత్తగా మాట్లాడాలి.', NULL, '800900ddc4cc32503c5100938e2757220ab023a8a46baa67f58343435335aa60') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1220', 'కథామాల', 'జ్ఞానమాల', 'అమ్మకు సహాయం', 'అమ్మ అలసిపోయింది.
పిల్లవాడు చూశాడు.
గిన్నెలు సర్దాడు.
అమ్మ సంతోషించింది.
ఇద్దరూ నవ్వారు.', '5 – 7 సంవత్సరాలు వయస్సు', 'అమ్మకు సహాయం చేయాలి.', NULL, '6a0e9f4c529f4ccf8cd27648691250094a2987bd8b88a655b8c81c31227cb1f7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1221', 'కథామాల', 'జ్ఞానమాల', 'పండగ సంతోషం', 'దీపావళి వచ్చింది.
పిల్లలు పటాకులు కాల్చారు.
అందరూ మిఠాయిలు పంచారు.
ఇంట్లో దీపాలు వెలిగాయి.
అందరూ సంతోషించారు.', '5 – 7 సంవత్సరాలు వయస్సు', 'పండగలు కలిసి జరుపుకోవాలి.', NULL, 'c9762a8bea69f2121a08620e5fbe060eb0a0628e85121ba74181c4f0b8b2d3d1') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1222', 'కథామాల', 'జ్ఞానమాల', 'అబద్ధం పోయింది', 'ఒక పిల్లవాడు అబద్ధం చెప్పాడు.
తర్వాత భయం వేసింది.
తల్లి దగ్గరకు వెళ్లాడు.
నిజం చెప్పాడు.
అమ్మ ప్రేమగా చెప్పింది.', '5 – 7 సంవత్సరాలు వయస్సు', 'నిజం చెప్పడం మంచిది.', NULL, 'a3d0bae88261f04722a847c0eff4cc028940216c3d895e726a158c470e6a421e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1223', 'కథామాల', 'జ్ఞానమాల', 'పక్షి గూడు', 'ఒక పక్షి గూడు కట్టింది.
గుడ్లు పెట్టింది.
పిల్లలు పుట్టారు.
అమ్మ పక్షి సంతోషించింది.
పిల్లలు పాటలు పాడారు.', '5 – 7 సంవత్సరాలు వయస్సు', 'కుటుంబం విలువైనది.', NULL, 'e4070f6f67b12171aad599f8418de24caa5470559f9d891c83272f3f856f33ae') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1224', 'కథామాల', 'జ్ఞానమాల', 'నీడ చెట్టు', 'ఒక పెద్ద చెట్టు ఉంది.
బాటసారి అలసిపోయాడు.
చెట్టు నీడలో కూర్చున్నాడు.
చల్లగా అనిపించింది.
అతడు సంతోషించాడు.', '5 – 7 సంవత్సరాలు వయస్సు', 'ఇతరులకు సహాయం చేయడం గొప్పది.', NULL, '2e4fb08446a65594ee9f098714763b4edf20d098da443fdaab34423ad6d17f09') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1225', 'కథామాల', 'జ్ఞానమాల', 'అక్క సహాయం', 'తమ్ముడికి హోంవర్క్ అర్థం కాలేదు.
అక్క దగ్గరకు వెళ్లాడు.
అక్క నేర్పించింది.
తమ్ముడికి అర్థమైంది.
ఇద్దరూ సంతోషించారు.', '5 – 7 సంవత్సరాలు వయస్సు', 'అన్నదమ్ముల అక్కచెల్లెళ్ళు సహాయం చేసుకోవాలి.', NULL, 'c047bca823fb6a9d5fb9101cada5965788e3d8d39f2aac4e663b3d511c0eb899') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1226', 'కథామాల', 'జ్ఞానమాల', 'పంట పొలం', 'రైతు పొలం దున్నాడు.
విత్తనాలు వేశాడు.
వర్షం పడింది.
పంట పండింది.
అందరూ తిన్నారు.', '5 – 7 సంవత్సరాలు వయస్సు', 'కష్టం చేస్తే ఫలం దొరుకుతుంది.', NULL, '071aa3bb2ba37145d1d6e27029f2e53a6dd540ef4a04d1227d9bef0ec867b298') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1227', 'కథామాల', 'జ్ఞానమాల', 'దేశభక్తి', 'స్వాతంత్ర్య దినోత్సవం వచ్చింది.
పిల్లలు జెండా ఎగురవేశారు.
పాటలు పాడారు.
తమ దేశాన్ని గుర్తుచేసుకున్నారు.
అందరూ గర్వపడ్డారు.', '5 – 7 సంవత్సరాలు వయస్సు', 'దేశాన్ని ప్రేమించాలి.', NULL, '8230f78d8378d94bf83fa216355fcdf53dc7106ee38db5d04778ef2d21f23dce') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1228', 'కథామాల', 'జ్ఞానమాల', 'మూగ జంతువు', 'ఒక కుక్క నొప్పితో ఉంది.
బాలుడు చూశాడు.
నీళ్ళు, తిండి ఇచ్చాడు.
కుక్క తేరుకుంది.
అది తోకాడించింది.', '5 – 7 సంవత్సరాలు వయస్సు', 'జంతువులపై దయ చూపించాలి.', NULL, '8fc7f69fe899f15356d4045013cfda90611f2943c4ae405e474cf43758939887') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1229', 'కథామాల', 'జ్ఞానమాల', 'మొక్క పెంచడం', 'పిల్లవాడు విత్తనం నాటాడు.
ప్రతిరోజూ నీరు పోశాడు.
మొక్క మొలిచింది.
పువ్వు పూసింది.
పిల్లవాడు సంతోషించాడు.', '5 – 7 సంవత్సరాలు వయస్సు', 'ఓపికగా చేస్తే ఫలం దక్కుతుంది.', NULL, '59901477084811783949035f50841487b850dd746824a24a99974a5ed91bfd78') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1230', 'కథామాల', 'జ్ఞానమాల', 'సంగీత పాఠం', 'బాలిక సంగీతం నేర్చుకుంది.
రోజూ అభ్యాసం చేసింది.
పోటీలో పాల్గొంది.
బహుమతి గెలిచింది.
అందరూ ఆనందించారు.', '5 – 7 సంవత్సరాలు వయస్సు', 'అభ్యాసం మనిషిని గొప్పవాడిని చేస్తుంది.', NULL, '836082bf41ea2f6edd26b5c1327c83fa609dfe0b0a7906b41cbacc91673078d6') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1231', 'కథామాల', 'జ్ఞానమాల', 'బడి స్నేహితుడు', 'కొత్త పిల్లవాడు బడికి వచ్చాడు.
అతడికి భయంగా ఉంది.
ఒక బాలుడు నవ్వాడు.
స్నేహంగా మాట్లాడాడు.
ఇద్దరూ స్నేహితులయ్యారు.', '5 – 7 సంవత్సరాలు వయస్సు', 'కొత్తవారిని స్వాగతించాలి.', NULL, 'b7e58ce5b1f3f73708f23d5200827a6993823f276dd2504894d1ced62ee62d31') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1232', 'కథామాల', 'జ్ఞానమాల', 'నీటి ఆదా', 'నల్లా తెరిచి ఉంది.
నీళ్ళు పోతున్నాయి.
బాలుడు చూశాడు.
వెంటనే మూశాడు.
నీళ్ళు ఆదా అయ్యాయి.', '5 – 7 సంవత్సరాలు వయస్సు', 'నీటిని ఆదా చేయాలి.', NULL, '74a7206c0de7ead54b19f7d94e1b7b112ff277b3ff9210f621901a4814497a7e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1233', 'కథామాల', 'జ్ఞానమాల', 'తాతయ్య కథ', 'తాతయ్య పొద్దస్తమానం కూర్చున్నాడు.
పిల్లలు దగ్గరకు వచ్చారు.
తాతయ్య కథ చెప్పాడు.
పిల్లలు శ్రద్ధగా విన్నారు.
అందరూ ఆనందించారు.', '5 – 7 సంవత్సరాలు వయస్సు', 'పెద్దల అనుభవం విలువైనది.', NULL, '80276ee39ac162d9526197c6f7f0bf98fa2d6f2ae923a9e932cf80b7ef2a7845') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1234', 'కథామాల', 'జ్ఞానమాల', 'రంగుల ఇంద్రధనుసు', 'వర్షం తర్వాత ఇంద్రధనుసు వచ్చింది.
పిల్లలు ఆకాశం చూశారు.
రంగులు లెక్కించారు.
అమ్మకు చెప్పారు.
అందరూ ఆనందించారు.', '5 – 7 సంవత్సరాలు వయస్సు', 'ప్రకృతి అద్భుతంగా ఉంటుంది.', NULL, 'd6d14f212ae5af996e1e9beaf1e57503206c601f9835cc3b150c9568cb2d9ea8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1235', 'కథామాల', 'జ్ఞానమాల', 'దయగల మనసు', 'పిల్లవాడికి బొమ్మ ఉంది.
స్నేహితుడికి ఏమీ లేదు.
పిల్లవాడు పంచుకున్నాడు.
ఇద్దరూ ఆడారు.
ఇద్దరూ సంతోషించారు.', '5 – 7 సంవత్సరాలు వయస్సు', 'దయగలిగి ఉండటం మంచిది.', NULL, '856c64c60d8b2de14b07e8e9b9c6c5112d5aa5251d65483298dd299b30cfbfb1') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1236', 'కథామాల', 'జ్ఞానమాల', 'పరీక్ష సిద్ధం', 'రేపు పరీక్ష ఉంది.
బాలుడు చదివాడు.
పాఠాలు రాశాడు.
పరీక్ష రాశాడు.
మంచి మార్కులు వచ్చాయి.', '5 – 7 సంవత్సరాలు వయస్సు', 'సిద్ధంగా ఉంటే విజయం వస్తుంది.', NULL, '0512015f6b995a5027914cfa56d24b3e0a28f2cc312d5b3d92cda8c3a92e93c1') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1237', 'కథామాల', 'జ్ఞానమాల', 'పెద్దల గౌరవం', 'పెద్దాయన బస్సులో ఉన్నాడు.
సీట్లు నిండిపోయాయి.
బాలుడు లేచాడు.
సీటు ఇచ్చాడు.
పెద్దాయన ఆశీర్వదించాడు.', '5 – 7 సంవత్సరాలు వయస్సు', 'పెద్దలను గౌరవించాలి.', NULL, '69476871cd2d862750f660f3fb4ace5060b5c50b95feb0787811dc0363dd81e2') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1238', 'కథామాల', 'జ్ఞానమాల', 'సందేహం అడగడం', 'పాఠంలో ఒక అంశం అర్థం కాలేదు.
బాలుడు సందేహపడ్డాడు.
టీచర్‌ని అడిగాడు.
టీచర్ వివరించింది.
బాలుడికి అర్థమైంది.', '5 – 7 సంవత్సరాలు వయస్సు', 'సందేహాలు అడగాలి.', NULL, '708fea7126fec4f2ea0f58a94bce3f80b472470830a213b8f3fdcb916c3fe488') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1239', 'కథామాల', 'జ్ఞానమాల', 'వ్యర్థం చేయకు', 'భోజనం మిగిలింది.
పిల్లవాడు పారేయబోయాడు.
అమ్మ చెప్పింది.
మళ్ళీ తిన్నాడు.
తిండి వృథా కాలేదు.', '5 – 7 సంవత్సరాలు వయస్సు', 'తిండిని వృథా చేయకూడదు.', NULL, '81cc8df93785c098dfaf9d2206fbdfdb7e867e10b20e9443ac996c02c25f6bba') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1240', 'కథామాల', 'జ్ఞానమాల', 'ఆటలో సంతోషం', 'పిల్లలు ఆట ఆడారు.
ఒకరు గెలిచారు.
ఒకరు ఓడారు.
అయినా ఇద్దరూ నవ్వారు.
ఆట ఆనందం ఇచ్చింది.', '5 – 7 సంవత్సరాలు వయస్సు', 'ఆటలో ఓడినా గెలిచినా ఆనందించాలి.', NULL, '4ddaab43c7b3e3b28ac7f12ac007febdc40cec36e665efe2e432939644235302') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1241', 'కథామాల', 'జ్ఞానమాల', 'కళ్ళద్దాల అబ్బాయి', 'ఒక అబ్బాయికి కళ్ళద్దాలు ఉన్నాయి.
కొందరు వేళాడించారు.
అతడు బాధపడలేదు.
చదువులో ముందున్నాడు.
అందరూ మెచ్చుకున్నారు.', '5 – 7 సంవత్సరాలు వయస్సు', 'చదువు మనిషిని గొప్పవాడిని చేస్తుంది.', NULL, '559fdd1516e35b63148ea2443dffa89ca784043510571b3db77d49f353177e0e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1242', 'కథామాల', 'జ్ఞానమాల', 'వైద్యుడు', 'బాలుడికి జ్వరం వచ్చింది.
అమ్మ వైద్యుడి దగ్గరకు తీసుకెళ్లింది.
వైద్యుడు మందులు ఇచ్చాడు.
బాలుడు తాగాడు.
బాలుడు తేరుకున్నాడు.', '5 – 7 సంవత్సరాలు వయస్సు', 'ఆరోగ్యమే సంపద.', NULL, 'ce7d2b3e971f94d0c614bf2d95cca9df1c011f0dd0ac73c41b0ee0e9c02c2861') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1243', 'కథామాల', 'జ్ఞానమాల', 'పదాలు నేర్చుకో', 'బాలిక రోజూ పది పదాలు రాసింది.
వాటిని నేర్చుకుంది.
అర్థాలు తెలుసుకుంది.
వాక్యాలు రాసింది.
ఆమె తెలివి పెరిగింది.', '5 – 7 సంవత్సరాలు వయస్సు', 'నేర్చుకోవడం ఆగకూడదు.', NULL, '29b8bb8a6cd103d2bff34dd7cfee325f077732e1d41c37a22a934f2df151a93f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1244', 'కథామాల', 'జ్ఞానమాల', 'ఒంటరి పక్షి', 'ఒక పక్షి ఒంటరిగా ఉంది.
ఇంకో పక్షి వచ్చింది.
ఇద్దరూ మాట్లాడారు.
కలిసి ఆడారు.
ఇక్కడ స్నేహం మొదలైంది.', '5 – 7 సంవత్సరాలు వయస్సు', 'స్నేహం ఒంటరితనాన్ని పోగొడుతుంది.', NULL, 'ef2e37a603f2851657ae3364c98f81c3e956fbde9644f22299ac8ae071405844') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1245', 'కథామాల', 'జ్ఞానమాల', 'మంచి నిద్ర', 'బాలుడు రాత్రి త్వరగా నిద్రపోయాడు.
పొద్దున తొందరగా లేచాడు.
తాజాగా అనిపించింది.
బడిలో శ్రద్ధగా చదివాడు.
అందరూ మెచ్చారు.', '5 – 7 సంవత్సరాలు వయస్సు', 'మంచి నిద్ర ఆరోగ్యం ఇస్తుంది.', NULL, '236e5ec462a69d4a8a019c913772a52f7e3d388972bd862c3be200e190db93d0') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1246', 'కథామాల', 'జ్ఞానమాల', 'పండుగ బట్టలు', 'పండుగకు కొత్త బట్టలు వచ్చాయి.
పిల్లవాడు వేసుకున్నాడు.
అందరూ చూశారు.
స్నేహితుడికి కూడా ఇచ్చాడు.
ఇద్దరూ సంతోషించారు.', '5 – 7 సంవత్సరాలు వయస్సు', 'పంచుకోవడమే ఆనందం.', NULL, '2a58d10e47f0db29f17d9e6393618f004753f6e71da6efae53c7cf9970d5ae44') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1247', 'కథామాల', 'జ్ఞానమాల', 'అక్షరాలు నేర్చుకో', 'చిన్న బాలిక అ ఆ ఇ నేర్చుకుంది.
రోజూ రాసింది.
అమ్మ నేర్పించింది.
పాఠశాలలో మెరిసింది.
టీచర్ మెచ్చుకున్నారు.', '5 – 7 సంవత్సరాలు వయస్సు', 'అక్షర జ్ఞానం పునాది.', NULL, 'e83cf3db96894fd710f6f5aace8f39aace8a8a063acfbedf33ed68d4ad6033d3') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1248', 'కథామాల', 'జ్ఞానమాల', 'బద్ధకస్తుడు మారాడు', 'ఒక బాలుడు బద్ధకంగా ఉండేవాడు.
పనులు వాయిదా వేసేవాడు.
ఒక రోజు నష్టం అనుభవించాడు.
అతడు మారాలని నిశ్చయించుకున్నాడు.
ప్రతి పని సమయానికి చేశాడు.
అందరూ మెచ్చారు.', '8 – 10 సంవత్సరాలు వయస్సు', 'బద్ధకం విడిచిపెట్టాలి.', NULL, '748fc21d9b9ed594534018e56d5ae8f280b8391a4eb4418e7aad87eee2ee4ab6') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1249', 'కథామాల', 'జ్ఞానమాల', 'సముద్రపు కల', 'ఒక బాలుడికి సముద్రం చూడాలని ఉంది.
అతడు చదువులో ముందుండాలని తీర్మానించాడు.
కష్టపడి చదివాడు.
ప్రతిభావంతుడని పేరు వచ్చింది.
అమ్మానాన్న సముద్రం చూపించారు.
అతడు సంతోషించాడు.', '8 – 10 సంవత్సరాలు వయస్సు', 'కలలు కనండి, కష్టపడండి.', NULL, '8e62d9d7d669d16bee76596d115d2ffdd7c4fd8f9bd77e1a5253ec7b3bc3cdf0') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1250', 'కథామాల', 'జ్ఞానమాల', 'అడవి జంతువుల స్నేహం', 'అడవిలో సింహం, జింక స్నేహితులయ్యాయి.
అందరూ ఆశ్చర్యపోయారు.
వారు కలిసి ఉండేవారు.
ఒకరికి ప్రమాదం వస్తే ఇంకొకరు రక్షించేవారు.
అడవంతా ప్రశాంతంగా ఉంది.
స్నేహం అందరినీ కలిపింది.', '8 – 10 సంవత్సరాలు వయస్సు', 'స్నేహం అన్ని భేదాలను తొలగిస్తుంది.', NULL, 'fb87c356aee14e23f711473b86352114a56cf6a8e776489696dc581d151a29a0') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1251', 'కథామాల', 'జ్ఞానమాల', 'గ్రంథాలయం', 'బాలుడు గ్రంథాలయానికి వెళ్లాడు.
వందలాది పుస్తకాలు చూశాడు.
ఒక పుస్తకం తీసుకున్నాడు.
జ్ఞానం పెరిగింది.
మళ్ళీ వెళ్లాలని ఉంది.
పుస్తకాలు అతడి నేస్తాలయ్యాయి.', '8 – 10 సంవత్సరాలు వయస్సు', 'పుస్తక పఠనం జ్ఞానం పెంచుతుంది.', NULL, '608551c962691670d711dd7d6d7293ca6f7b52fda2c06c540ea5284cfcb5f947') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1252', 'కథామాల', 'జ్ఞానమాల', 'వినయం', 'ఒక బాలుడు చాలా తెలివైనవాడు.
కాని అతడు వినయంగా ఉండేవాడు.
అందరితో మెలిగేవాడు.
అందరూ ఇష్టపడేవారు.
పాఠశాలలో అందరూ ఆదర్శంగా చూశారు.
వినయం అతడిని ఉన్నతంగా చేసింది.', '8 – 10 సంవత్సరాలు వయస్సు', 'వినయం మనిషిని ఉన్నతంగా చేస్తుంది.', NULL, '555ecac1b95bd7d958785e01d80d3cac7a6de96ba29d3f1bde9484e9a479567a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1253', 'కథామాల', 'జ్ఞానమాల', 'పర్యావరణ సేవ', 'పాఠశాల ప్రాంగణంలో చెత్త ఉంది.
ఒక బాలుడు శుభ్రం చేయాలని నిర్ణయించాడు.
స్నేహితులను కూడగట్టాడు.
అందరూ కలిసి శుభ్రం చేశారు.
చెట్లు నాటారు.
పాఠశాల పచ్చగా మారింది.', '8 – 10 సంవత్సరాలు వయస్సు', 'పర్యావరణ సేవ మన బాధ్యత.', NULL, '7e9a9630d7015e06d02567a4bcc472e6b9737f58afb5696c6cdf5bdf41b6aa87') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1254', 'కథామాల', 'జ్ఞానమాల', 'అమ్మమ్మ జ్ఞానం', 'పిల్లవాడికి చదువులో ఇబ్బంది వచ్చింది.
అమ్మమ్మ దగ్గరకు వెళ్లాడు.
అమ్మమ్మ అనుభవాలు చెప్పింది.
పిల్లవాడికి స్ఫూర్తి వచ్చింది.
తిరిగి ప్రయత్నించాడు.
సమస్య తీరింది.', '8 – 10 సంవత్సరాలు వయస్సు', 'పెద్దల జ్ఞానం మనకు బాటచూపిస్తుంది.', NULL, 'd264b1c49d8b3b1b1ea91f268068d39e0c6977efd0b81dfc186d4026c2f0e514') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1255', 'కథామాల', 'జ్ఞానమాల', 'క్రీడా స్ఫూర్తి', 'బాలుడు పరిగెత్తే పోటీలో ఓడాడు.
అతడు నిరుత్సాహపడలేదు.
మళ్ళీ సాధన చేశాడు.
తర్వాతి పోటీలో బాగా చేశాడు.
బహుమతి గెలిచాడు.
అందరూ అభినందించారు.', '8 – 10 సంవత్సరాలు వయస్సు', 'ఓటమి తర్వాత మళ్ళీ ప్రయత్నించాలి.', NULL, 'f8f45f38af39ac330f693724be9b398b2be6f58f011ec5b58508ddecc506ffc7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1256', 'కథామాల', 'జ్ఞానమాల', 'నిజాయితీ వ్యాపారి', 'ఒక దుకాణదారు నిజాయితీగా ఉండేవాడు.
తక్కువ లాభానికి అమ్మేవాడు.
అందరూ అతడి దుకాణానికి వచ్చేవారు.
పేరు నలుమూలలా వ్యాపించింది.
వ్యాపారం పెరిగింది.
నిజాయితీ అతడిని అభివృద్ధిలోకి తీసుకెళ్లింది.', '8 – 10 సంవత్సరాలు వయస్సు', 'నిజాయితీ అభివృద్ధికి దారి చూపిస్తుంది.', NULL, 'df9565e9b67aea24c8450e7f2dff35a126e95b694390e99ca55d37da187dcfe7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1257', 'కథామాల', 'జ్ఞానమాల', 'చిన్న మోటివేషన్', 'బాలుడు నిరుత్సాహపడ్డాడు.
టీచర్ మాట్లాడింది.
అతడిలో ఉన్న శక్తిని గుర్తుచేసింది.
బాలుడికి ధైర్యం వచ్చింది.
మళ్ళీ ప్రయత్నించాడు.
విజయం సాధించాడు.', '8 – 10 సంవత్సరాలు వయస్సు', 'ఒక మంచి మాట జీవితాన్ని మార్చగలదు.', NULL, 'dc751cafd29416aac0447469af4f7bdae94f004e222d1ec7c14dd811ee101a0d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1258', 'కథామాల', 'జ్ఞానమాల', 'ఆనలాగ్ vs డిజిటల్', 'బాలుడు ఎప్పుడూ ఫోన్ చూసేవాడు.
అమ్మ పుస్తకం ఇచ్చింది.
మొదట విసుక్కున్నాడు.
తర్వాత చదవడం మొదలుపెట్టాడు.
కథ అద్భుతంగా ఉంది.
పుస్తకాలు ఫోన్ కంటే మెరుగని తెలిసింది.', '8 – 10 సంవత్సరాలు వయస్సు', 'పుస్తకాలు అత్యుత్తమ నేస్తాలు.', NULL, '99b39587cd399ed9300eba18b0717aba2510bf98f3099d40c93ee89aa2d2393b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1259', 'కథామాల', 'జ్ఞానమాల', 'గురువు గొప్పదనం', 'ఒక గురువు తన విద్యార్థుల కోసం కష్టపడ్డాడు.
అందరికీ జ్ఞానం పంచాడు.
నిరుపేద పిల్లలకు పుస్తకాలు ఇచ్చాడు.
అందరూ బాగా చదివారు.
తర్వాత వారు పెద్దవారయ్యారు.
గురువుకు నమస్కరించారు.', '8 – 10 సంవత్సరాలు వయస్సు', 'గురువు జీవితాలను తీర్చిదిద్దుతారు.', NULL, '22a6ae30b811b0f919f29ededa7740ebea4e36579dc2240a62a709526ef5ba59') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1260', 'కథామాల', 'జ్ఞానమాల', 'జల సంరక్షణ', 'ఒక గ్రామంలో నీటి కొరత ఉంది.
పిల్లలు పెద్దలతో చర్చించారు.
వర్షపు నీటిని నిల్వ చేయడం నేర్చుకున్నారు.
చెరువు శుభ్రం చేశారు.
నీళ్ళు వచ్చాయి.
గ్రామం సంతోషించింది.', '8 – 10 సంవత్సరాలు వయస్సు', 'జలాన్ని సంరక్షించడం ముఖ్యం.', NULL, '8c02241335458f121c5480cab2bd00fdad2e2afe18efbc67a728b43c6f61d295') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1261', 'కథామాల', 'జ్ఞానమాల', 'ఫలం కోసం', 'రైతు పిల్లవాడు కష్టాలు చూశాడు.
చదువు మానేయాలని అనిపించింది.
టీచర్ ప్రోత్సహించాడు.
పిల్లవాడు కష్టపడ్డాడు.
స్కాలర్‌షిప్ వచ్చింది.
కుటుంబం గర్వపడింది.', '8 – 10 సంవత్సరాలు వయస్సు', 'కష్టాలు అడ్డుపడనీయకు.', NULL, '047f86324da32ae33231db702a27939e43f6e6799815188a2efd2e000a41cb63') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1262', 'కథామాల', 'జ్ఞానమాల', 'విద్యుత్ ఆదా', 'పిల్లవాడు గది వదిలేటప్పుడు లైట్ వేసి వెళ్లాడు.
తండ్రి చెప్పాడు.
తర్వాత అతడు లైట్ ఆపి వెళ్లాడు.
అలవాటు చేసుకున్నాడు.
విద్యుత్ బిల్లు తగ్గింది.
అందరూ మెచ్చారు.', '8 – 10 సంవత్సరాలు వయస్సు', 'విద్యుత్ ఆదా అందరి బాధ్యత.', NULL, 'be857d9fcfde0146ac567409fe9343cb36eab81fabdabd94d04268b332d6324e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1263', 'కథామాల', 'జ్ఞానమాల', 'అబ్బాయి నాయకత్వం', 'తరగతిలో గొడవ జరిగింది.
ఒక బాలుడు మధ్యవర్తిత్వం చేశాడు.
ఇరువైపులా మాట్లాడాడు.
సమస్య పరిష్కరించాడు.
అందరూ సంతోషించారు.
టీచర్ మెచ్చుకున్నారు.', '8 – 10 సంవత్సరాలు వయస్సు', 'శాంతిగా సమస్యలు పరిష్కరించాలి.', NULL, '1495c19de850aee71baf00bcb3d36f6cada72b5a32464c9aa782fc39bd61d236') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1264', 'కథామాల', 'జ్ఞానమాల', 'చెలిమి', 'ఒక అమ్మాయికి చాలా స్నేహితులు ఉన్నారు.
అందరూ వేరు వేరు అభిరుచులు కలిగినవారు.
ఆమె అందరినీ ఒకే విధంగా చూసేది.
అందరూ కలిసి ఆడేవారు.
తరగతి ఒక కుటుంబంలా తయారైంది.
అందరూ ఆనందించారు.', '8 – 10 సంవత్సరాలు వయస్సు', 'భేదభావం లేకుండా ఉండటం మంచిది.', NULL, '47251a4c20b42f9e2212c6ab63f45ca776185a4e4a8ad0de29febb058138275e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1265', 'కథామాల', 'జ్ఞానమాల', 'గణిత మాంత్రికుడు', 'ఒక బాలుడికి లెక్కలు భయంగా ఉండేవి.
అతడు ప్రతిరోజూ సాధన చేశాడు.
టీచర్ సహాయం తీసుకున్నాడు.
క్రమంగా సులభంగా అనిపించింది.
పోటీలో బాగా చేశాడు.
అందరూ అభినందించారు.', '8 – 10 సంవత్సరాలు వయస్సు', 'సాధన అసాధ్యాన్ని సాధ్యం చేస్తుంది.', NULL, '1bc8df9c1fd49913e7811f1d0fdd71f385cd68c70c4ffa3a93c32f8f55b69f91') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1266', 'కథామాల', 'జ్ఞానమాల', 'ఒక్క అడుగు', 'పెద్ద పర్వతం ముందు నిలబడ్డాడు.
భయం వేసింది.
మొదటి అడుగు వేశాడు.
నెమ్మదిగా ముందుకు వెళ్లాడు.
పైకి చేరాడు.
అతడికి ఆత్మవిశ్వాసం పెరిగింది.', '8 – 10 సంవత్సరాలు వయస్సు', 'మొదటి అడుగే విజయానికి తొలి సోపానం.', NULL, 'fcd4cc4b29a648840550e1e42520827824964a8ce80121ddf86e8b5a9a0cd541') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1267', 'కథామాల', 'జ్ఞానమాల', 'నీతి కథ చదివాడు', 'బాలుడు నీతి కథ చదివాడు.
కథలో మోసగాడు ఓడాడు.
నిజాయితీ పరుడు గెలిచాడు.
బాలుడికి బాగా అనిపించింది.
అతడు నిజాయితీగా ఉండాలని నిర్ణయించాడు.
జీవితంలో దానిని పాటించాడు.', '8 – 10 సంవత్సరాలు వయస్సు', 'కథలు నైతిక విలువలు నేర్పుతాయి.', NULL, '730190dd9aacb4cd547a3b6476ba61c8129800417570b37bd1b8d2aa8e7cbe47') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1268', 'కథామాల', 'జ్ఞానమాల', 'సమాజ సేవ', 'బాలుడు వారాంతంలో ఖాళీగా ఉండేవాడు.
నిరుపేద పిల్లలకు చదువు నేర్పించాలని తలచాడు.
ప్రతి ఆదివారం వెళ్లేవాడు.
పిల్లలు నేర్చుకున్నారు.
తల్లిదండ్రులు సంతోషించారు.
బాలుడికి నిజమైన ఆనందం కలిగింది.', '8 – 10 సంవత్సరాలు వయస్సు', 'సమాజ సేవ నిజమైన ఆనందం ఇస్తుంది.', NULL, '647c6be9e6eccd768e5b419828a178dd9757eda2e6ca9d56e26e220988f32b2d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1269', 'కథామాల', 'జ్ఞానమాల', 'అద్భుత చిత్రకారుడు', 'ఒక బాలుడికి చిత్రకళ ఇష్టం.
అతడు రోజూ గీసేవాడు.
ఒకసారి పోటీలో పాల్గొన్నాడు.
అతడి చిత్రం అందరినీ ఆకట్టుకుంది.
మొదటి స్థానం వచ్చింది.
అతడి కళ అందరికీ స్ఫూర్తిగా నిలిచింది.', '8 – 10 సంవత్సరాలు వయస్సు', 'నచ్చిన విషయంలో శ్రమిస్తే గుర్తింపు వస్తుంది.', NULL, 'fe1c257838535f9dfd4d6b7619899ca851170984792ada514a14287008f1a9de') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1270', 'కథామాల', 'జ్ఞానమాల', 'వంట నేర్చుకో', 'అమ్మ అనారోగ్యంగా ఉంది.
బాలుడు వంట నేర్చుకున్నాడు.
అందరికీ వండాడు.
అమ్మ ఆశ్చర్యపోయింది.
సంతోషించింది.
బాలుడు బాధ్యతగా మారాడు.', '8 – 10 సంవత్సరాలు వయస్సు', 'జీవన నైపుణ్యాలు అవసరం.', NULL, '8444c71f022d0c50049b400ab2a02f0dd0ae8d00c543a5ace836c9ac38191e0d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1271', 'కథామాల', 'జ్ఞానమాల', 'సరైన పని', 'స్నేహితుడు తప్పు చేయమని చెప్పాడు.
బాలుడు అంగీకరించలేదు.
తప్పు చేయడం సరి కాదు అన్నాడు.
ముందు స్నేహితుడు కోపించాడు.
తర్వాత అర్థమైంది.
స్నేహం మరింత బలపడింది.', '8 – 10 సంవత్సరాలు వయస్సు', 'తప్పు చేయడానికి ఒప్పుకోకూడదు.', NULL, '8a2dd0b1861e7fff78da3809242877b44d726266a371881444d7eba970bb95a2') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1272', 'కథామాల', 'జ్ఞానమాల', 'ఊరికి వెళ్లాడు', 'బాలుడు మొదటిసారి ఊరికి వెళ్లాడు.
పొలాలు, చెరువులు చూశాడు.
రైతుల కష్టం అర్థమైంది.
తాను ఆహారాన్ని వృథా చేసేవాడని తెలిసింది.
మారాలని నిశ్చయించుకున్నాడు.
తిండి వృథా చేయడం మానేశాడు.', '8 – 10 సంవత్సరాలు వయస్సు', 'రైతు కష్టాన్ని గుర్తించాలి.', NULL, '5dcc8c20bae68876845b34f3ff7e38d9b2c286d27ef2792167c85856262d2076') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1273', 'కథామాల', 'జ్ఞానమాల', 'డిజిటల్ వ్యసనం', 'ఒక విద్యార్థి ఎప్పుడూ ఫోన్ వాడేవాడు.
చదువు పడిపోయింది.
తల్లిదండ్రులు మాట్లాడారు.
అతడు ఆలోచించాడు.
ఫోన్ వేళలు నిర్ణయించుకున్నాడు.
చదువుపై దృష్టి పెట్టాడు.
ఫలితాలు మెరుగయ్యాయి.
తెలివిగా సాంకేతికత వాడటం నేర్చుకున్నాడు.', '11 – 15 సంవత్సరాలు వయస్సు', 'సాంకేతికతను తెలివిగా వాడాలి.', NULL, '7b55256a9e6c7643d968465f07134516737021f96a7231095f42de1166e67544') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1274', 'కథామాల', 'జ్ఞానమాల', 'మొదటి వ్యాపారం', 'ఒక బాలుడికి వ్యాపారం చేయాలని ఉంది.
వేసవిలో నిమ్మకాయ రసం అమ్మాడు.
మొదట తక్కువ సంపాదన వచ్చింది.
ఆగకుండా ప్రయత్నించాడు.
రుచి మెరుగుపరచాడు.
కస్టమర్లు పెరిగారు.
మంచి సంపాదన వచ్చింది.
చిన్న వయసులోనే వ్యాపార నైపుణ్యం నేర్చుకున్నాడు.', '11 – 15 సంవత్సరాలు వయస్సు', 'ఆలోచించి ప్రయత్నిస్తే ఏ వయసులోనైనా సాధించవచ్చు.', NULL, '67f5acf965a3a168123f826182efc723a26cfcb74f477c13b8e38c6ffaf5bc26') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1275', 'కథామాల', 'జ్ఞానమాల', 'సైబర్ భద్రత', 'ఒక విద్యార్థికి అనుమానమైన సందేశం వచ్చింది.
లింక్ తెరవద్దని స్నేహితుడు హెచ్చరించాడు.
అతడు ఆగాడు.
తల్లిదండ్రులకు చూపించాడు.
అది మోసం అని తేలింది.
డేటా సురక్షితంగా ఉంది.
సైబర్ భద్రత నేర్చుకున్నాడు.
స్నేహితులకు కూడా నేర్పాడు.', '11 – 15 సంవత్సరాలు వయస్సు', 'ఇంటర్నెట్‌లో జాగ్రత్తగా ఉండాలి.', NULL, '3a46380567b3d37d315035b21b94c1442eeeac30585d770dd0c8e76730ace0c0') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1276', 'కథామాల', 'జ్ఞానమాల', 'ఆర్థిక జ్ఞానం', 'తండ్రి పిల్లవాడికి నెలకు కొంత డబ్బు ఇచ్చాడు.
మొదట వెంటనే అన్నీ కొనాలని అనిపించింది.
అమ్మ ఆదా చేయడం నేర్పించింది.
పిల్లవాడు నోట్‌బుక్‌లో లెక్కలు రాశాడు.
అవసరమైనవి మాత్రమే కొన్నాడు.
మూడు నెలలలో చాలా మొత్తం ఆదా అయింది.
ఒక కావలసిన పుస్తకం కొన్నాడు.
ఆర్థిక బాధ్యత అర్థమైంది.', '11 – 15 సంవత్సరాలు వయస్సు', 'డబ్బును తెలివిగా ఆదా చేయడం ముఖ్యం.', NULL, '4d703d0d1ae1acbb6e3000f6d3c166e4e37dae5005db274d63a239ff5937bc58') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1277', 'కథామాల', 'జ్ఞానమాల', 'మానసిక ధైర్యం', 'ఒక విద్యార్థి పరీక్షలో ఫెయిల్ అయ్యాడు.
ఆత్మవిశ్వాసం తగ్గిపోయింది.
కౌన్సెలర్ మాట్లాడారు.
తప్పు ఎక్కడ జరిగిందో గుర్తించాడు.
మళ్ళీ సిద్ధమయ్యాడు.
కష్టపడి చదివాడు.
తర్వాతి పరీక్షలో మంచి మార్కులు వచ్చాయి.
ఓటమి జీవితంలో చివర కాదని నేర్చుకున్నాడు.', '11 – 15 సంవత్సరాలు వయస్సు', 'ఓటమి నుండి నేర్చుకుంటేనే విజయం.', NULL, '105a77ebb3119a00c459994a3d500396bade7565f526406f0f28a919a5740565') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1278', 'కథామాల', 'జ్ఞానమాల', 'పరిశోధనా మనసు', 'ఒక బాలిక అన్నింటినీ ప్రశ్నించేది.
ఎందుకు, ఎలా అని అడిగేది.
సైన్స్ ఫెయిర్‌కు ప్రాజెక్ట్ చేసింది.
నీటి కాలుష్య పరిష్కారం వెతికింది.
ఉపాధ్యాయులు మెచ్చుకున్నారు.
జాతీయ స్థాయి పోటీలో ఎంపికైంది.
అందరూ అభినందించారు.
పరిశోధనలే దేశ భవిష్యత్తు అని స్ఫురించింది.', '11 – 15 సంవత్సరాలు వయస్సు', 'ప్రశ్నించే మనసు ఆవిష్కరణలకు దారి తీస్తుంది.', NULL, 'a065c65c4d4d90ef64135c31ebfb688a1be464610eca4d0900bccc6e0587e978') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1279', 'కథామాల', 'జ్ఞానమాల', 'వేగం కాదు గుణం', 'ఒక విద్యార్థి పనులు వేగంగా ముగించేవాడు.
కాని తప్పులు జరిగేవి.
టీచర్ వివరించింది.
అతడు నెమ్మదిగా జాగ్రత్తగా చేయడం మొదలుపెట్టాడు.
తప్పులు తగ్గాయి.
మార్కులు పెరిగాయి.
అందరూ మెచ్చారు.
నాణ్యత వేగం కంటే ముఖ్యమని తెలిసింది.', '11 – 15 సంవత్సరాలు వయస్సు', 'పని నాణ్యతగా చేయాలి, వేగం కాదు.', NULL, '1b11fda5b6be84809aca823154f0f3eebcc64b7c0851c5d9757395c46214be63') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1280', 'కథామాల', 'జ్ఞానమాల', 'స్నేహపు సీమలు', 'ఇద్దరు స్నేహితులు మంచిగా ఉండేవారు.
ఒకరు తప్పు మార్గం చూపించాడు.
ఇంకొకరు మొదట సందేహపడ్డాడు.
అది తప్పు అని స్పష్టంగా చెప్పాడు.
స్నేహం పోతుందేమో అని భయపడ్డాడు.
కాని నిజమైన స్నేహితుడు అర్థం చేసుకున్నాడు.
ఆగి ఆలోచించాడు.
ఇద్దరూ సరైన మార్గంలో నడిచారు.', '11 – 15 సంవత్సరాలు వయస్సు', 'నిజమైన స్నేహం తప్పు చేయనివ్వదు.', NULL, '4184c6547a377ac1ab545fd0266c01476bdac8971ebaaeee923d5333c2827797') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1281', 'కథామాల', 'జ్ఞానమాల', 'కెరీర్ లక్ష్యం', 'ఒక బాలుడికి ఇంజినీర్ అవ్వాలని ఉంది.
అందుకు ఏం చేయాలో తెలుసుకున్నాడు.
లక్ష్యం నిర్ణయించుకున్నాడు.
ప్రతి విషయాన్ని శ్రద్ధగా చదివాడు.
గణితం, సైన్స్‌లో ముందు నిలిచాడు.
పోటీ పరీక్ష రాశాడు.
మంచి కళాశాలలో సీటు వచ్చింది.
తన కల నిజమైంది.', '11 – 15 సంవత్సరాలు వయస్సు', 'స్పష్టమైన లక్ష్యం విజయానికి మార్గం చూపిస్తుంది.', NULL, 'da31b7738a566c88aeb14b8738b94ba06d1110ff84b29c17341430819ffa05b9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1282', 'కథామాల', 'జ్ఞానమాల', 'సృజనాత్మకత', 'ఒక బాలిక కవితలు రాసేది.
పాఠశాల పత్రికలో ప్రచురించింది.
అందరూ చదివారు.
ఆమె రాసిన కవిత అందరికీ నచ్చింది.
ఒక జాతీయ పోటీలో పాల్గొంది.
ప్రశంసలు అందుకుంది.
ఆమె ఆత్మవిశ్వాసం పెరిగింది.
కళలో ప్రతిభ ఉంటే దానిని వ్యక్తం చేయాలని నేర్చుకుంది.', '11 – 15 సంవత్సరాలు వయస్సు', 'సృజనాత్మకతను పోషించుకోవాలి.', NULL, 'cc35eab9805b95c2a1b92e9c1669d1857bef68e6137abdcda1c1622fd610a2dd') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1283', 'కథామాల', 'జ్ఞానమాల', 'అందరినీ చేర్చుకో', 'తరగతిలో ఒక వికలాంగ విద్యార్థి ఉన్నాడు.
కొందరు దూరంగా ఉన్నారు.
ఒక అమ్మాయి అతడిని స్నేహంగా పలకరించింది.
అతడితో కలిసి పని చేసింది.
అతడి ప్రతిభ అందరికీ తెలిసింది.
తరగతంతా అతడికి నేస్తాలయ్యారు.
అమ్మాయి తీసుకున్న చొరవ అందరినీ ఏకం చేసింది.
భేదభావం తొలగిపోయింది.', '11 – 15 సంవత్సరాలు వయస్సు', 'అందరినీ సమానంగా చూడాలి.', NULL, '3c45a47bd60aac899d7ef9c5408b18b23fb38d8bca83cfecf242bf3c1e17affc') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1284', 'కథామాల', 'జ్ఞానమాల', 'పర్యావరణ నాయకత్వం', 'ఒక విద్యార్థి ఊరిలో కాలుష్యం చూశాడు.
ఒంటరిగా ఏం చేయగలనని అనిపించింది.
కాని ఆగలేదు.
పాఠశాలలో ఒక పర్యావరణ క్లబ్బు పెట్టాడు.
పిల్లలందరినీ చేర్చుకున్నాడు.
వ్యర్థాలను వేరుచేయడం, చెట్లు నాటడం మొదలుపెట్టారు.
ఊరు మారింది.
అతడి చొరవ స్ఫూర్తిగా నిలిచింది.', '11 – 15 సంవత్సరాలు వయస్సు', 'ఒక్క మనిషి చొరవ మార్పుకు నాంది పలుకుతుంది.', NULL, 'e57d35d5dcac2daa6b33d04ac4476c31b56007fbea1e4145c5066ba4cc1db440') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1285', 'కథామాల', 'జ్ఞానమాల', 'ప్రతికూల పరిస్థితి', 'ఒక అమ్మాయి కుటుంబం ఆర్థిక ఇబ్బంది పడింది.
చదువు మానాల్సి వస్తుందేమో అని భయపడింది.
ఆమె హెడ్‌మాస్టర్ దగ్గరకు వెళ్లింది.
తన స్థితి వివరించింది.
స్కాలర్‌షిప్ సహాయం దొరికింది.
ఆమె చదువు ఆగలేదు.
ఫలితాలు అద్భుతంగా వచ్చాయి.
ధైర్యంగా అడిగితే మార్గం దొరుకుతుందని నేర్చుకుంది.', '11 – 15 సంవత్సరాలు వయస్సు', 'సహాయం కోరడం బలహీనత కాదు, ధైర్యం.', NULL, '8d32eb33d3c5132d3f0706626a8af1a6eb13d1611f44663d8fd9d75f7c60713d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1286', 'కథామాల', 'జ్ఞానమాల', 'గ్రూప్ స్టడీ', 'పరీక్ష దగ్గరకు వచ్చింది.
నలుగురు స్నేహితులు కలిసి చదివారు.
ఒకరికి ఒకరు నేర్పించారు.
కష్టమైన అంశాలు సులభమయ్యాయి.
అందరూ పరీక్షలో బాగా చేశారు.
ఫలితాలు అద్భుతంగా వచ్చాయి.
కలిసి చదవడం ఎంత మంచిదో తెలిసింది.
స్నేహమూ, చదువూ రెండూ పెరిగాయి.', '11 – 15 సంవత్సరాలు వయస్సు', 'కలిసి నేర్చుకోవడం శక్తివంతమైనది.', NULL, '652555d77b8ee3db5de50325aeba0f3c01a8e8a877f31f011664b8f9f201122b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1287', 'కథామాల', 'జ్ఞానమాల', 'నిద్రపోతే కలలు మాత్రమే', 'ఒక బాలుడికి పెద్ద కలలు ఉన్నాయి.
కాని చర్య తీసుకోలేదు.
స్నేహితుడు ముందుకు వెళ్లాడు.
బాలుడికి ఉలుకు వచ్చింది.
చర్య తీసుకున్నాడు.
ప్రయత్నించాడు.
నెమ్మదిగా ముందుకు వెళ్లాడు.
కలలు నిజమవ్వడం మొదలైంది.', '11 – 15 సంవత్సరాలు వయస్సు', 'కలలే చాలదు, చర్య తీసుకోవాలి.', NULL, '3a1d326f9e4221d6557d644b54b068110e97e90bcdd43f711681b6829c36bd5b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1288', 'కథామాల', 'జ్ఞానమాల', 'మాతృభాష గర్వం', 'ఒక విద్యార్థి తెలుగు మాట్లాడటానికి సిగ్గుపడేవాడు.
ఇంగ్లీషే గొప్పది అనుకున్నాడు.
ఒక రోజు మాతృభాష ప్రాముఖ్యత గురించి చదివాడు.
గొప్ప తెలుగు కవులను తెలుసుకున్నాడు.
తెలుగు సాహిత్యం చదివాడు.
మాతృభాషపై గర్వం కలిగింది.
తరగతిలో తెలుగు ప్రసంగం చేశాడు.
అందరూ మెచ్చుకున్నారు.', '11 – 15 సంవత్సరాలు వయస్సు', 'మాతృభాషను గౌరవించడం గొప్ప సంస్కారం.', NULL, '01800c08f533f1cf0aeffb6a4c4e3487dde98cee845d406827370c5fe66c6b6b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1289', 'కథామాల', 'జ్ఞానమాల', 'వాలంటీర్ స్ఫూర్తి', 'వరద వచ్చింది.
ఒక విద్యార్థుల బృందం సహాయానికి వెళ్లింది.
తినుబండారాలు పంచారు.
పిల్లలకు పాఠాలు చెప్పారు.
వృద్ధులకు సహాయం చేశారు.
బాధితులు సంతోషించారు.
అధికారులు మెచ్చుకున్నారు.
వాలంటీర్ స్ఫూర్తి అందరికీ పాఠం అయింది.', '11 – 15 సంవత్సరాలు వయస్సు', 'సంక్షోభంలో సహాయం చేయడమే నిజమైన మానవత్వం.', NULL, '69e9677e8f08bed5e65d76109a27a8c0eb704a05b67d19c595623dedbf11daee') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1290', 'కథామాల', 'జ్ఞానమాల', 'నిస్వార్థ స్నేహం', 'ఒక స్నేహితుడికి మంచి అవకాశం వచ్చింది.
ఇంకో స్నేహితుడికి అసూయ వేయలేదు.
అభినందించాడు.
తన స్నేహితుడి విజయంలో సహాయపడ్డాడు.
స్నేహితుడు విజయం సాధించాడు.
తిరిగి మొదటి స్నేహితుడికి కృతజ్ఞత చెప్పాడు.
ఇద్దరూ ఒకరికొకరు సహాయపడ్డారు.
నిస్వార్థ స్నేహం అర్థమైంది.', '11 – 15 సంవత్సరాలు వయస్సు', 'నిస్వార్థంగా ఇచ్చిన సహాయం తిరిగి వస్తుంది.', NULL, '31997d82b03ee67d38d7818007ec18fac07501d69ac24c354b1e16a3046bbd73') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1291', 'కథామాల', 'జ్ఞానమాల', 'ఒత్తిడి నిర్వహణ', 'పరీక్షల సమయంలో బాలుడికి చాలా ఒత్తిడి వచ్చింది.
నిద్ర సరిగ్గా లేదు.
తల నొప్పి వచ్చింది.
అమ్మ గమనించింది.
నిద్ర, వ్యాయామం, చదువు సమతుల్యం చేయమని చెప్పింది.
బాలుడు పాటించాడు.
ఒత్తిడి తగ్గింది.
ఆరోగ్యంగా పరీక్ష రాశాడు.', '11 – 15 సంవత్సరాలు వయస్సు', 'ఆరోగ్యం లేకుండా విద్య ఫలించదు.', NULL, 'bdab88e7538f7685289edd604b60886debc6aa6cb3c14a58071f02d5a2776ccd') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1292', 'కథామాల', 'జ్ఞానమాల', 'నాటకంలో విలువలు', 'పాఠశాల నాటకంలో ఒక బాలుడికి పాత్ర వచ్చింది.
ప్రతి రోజూ సాధన చేశాడు.
పాత్ర అర్థం చేసుకున్నాడు.
వేదికపై అద్భుతంగా నటించాడు.
అందరూ అభినందించారు.
నటన కళ ఆత్మవిశ్వాసాన్ని పెంచింది.
కమ్యూనికేషన్ నేర్చుకున్నాడు.
కళలు జీవన నైపుణ్యాలని అర్థమైంది.', '11 – 15 సంవత్సరాలు వయస్సు', 'కళలు వ్యక్తిత్వాన్ని తీర్చిదిద్దుతాయి.', NULL, '6b7c3a4009a646d99d1065250187c5da0933f0078e8d463636613690d2d684f4') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1293', 'కథామాల', 'జ్ఞానమాల', 'చిన్న తాబేలు', 'ఒక తాబేలు నెమ్మదిగా నడిచింది.
కుందేలు నవ్వింది.
తాబేలు ఆగలేదు.
చివరకు తాబేలు గెలిచింది.', '1 – 4 సంవత్సరాలు వయస్సు', 'ఆగకుండా ప్రయత్నించాలి.', NULL, 'ab29bd5df467f444df59614509772b0ed30e29ecc525a7c9be4403af0439d3cd') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1294', 'కథామాల', 'జ్ఞానమాల', 'దానశీలి', 'ఒక బాలుడి దగ్గర అదనపు పెన్సిళ్ళు ఉన్నాయి.
స్నేహితుడికి ఒక్కటీ లేదు.
బాలుడు ఇచ్చాడు.
స్నేహితుడు సంతోషించాడు.
ఇద్దరూ కలిసి చదివారు.', '5 – 7 సంవత్సరాలు వయస్సు', 'ఇవ్వడం అందరినీ సంతోషపెడుతుంది.', NULL, '3f091ef1a4553d2a4ec523737639a37fe4171290fe72db7a756ce0cbaaecc4d5') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1295', 'కథామాల', 'జ్ఞానమాల', 'ఊహించని నేర్పు', 'బాలుడు వంట నేర్చుకోవడం అవసరం లేదనుకున్నాడు.
ఒక రోజు ఒంటరిగా ఉన్నాడు.
ఆకలి వేసింది.
చూసినదానితో సాధారణ వంట చేశాడు.
తిన్నాడు.
ఏ నైపుణ్యమైనా ఉపయోగపడుతుందని తెలిసింది.', '8 – 10 సంవత్సరాలు వయస్సు', 'ప్రతి నైపుణ్యమూ విలువైనదే.', NULL, 'f8f94709d109e35ad7f2df1eb685cf40c8ce31d5e5c8b54842e0a5d74259124a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1296', 'కథామాల', 'జ్ఞానమాల', 'సోషల్ మీడియా జాగ్రత్త', 'ఒక అమ్మాయి సోషల్ మీడియాలో తన వ్యక్తిగత వివరాలు పెట్టింది.
ఒక అపరిచిత వ్యక్తి మాట్లాడడం మొదలుపెట్టాడు.
ఆమె తల్లిదండ్రులతో చెప్పింది.
వారు వివరించారు.
ఆమె అకౌంట్ ప్రైవేట్ చేసింది.
అపరిచిత వారితో మాట్లాడడం మానింది.
పరిచయస్తులతో మాత్రమే కనెక్ట్ అయింది.
భద్రత ఎంత ముఖ్యమో నేర్చుకుంది.', '11 – 15 సంవత్సరాలు వయస్సు', 'సోషల్ మీడియాలో వ్యక్తిగత సమాచారం జాగ్రత్తగా పంచాలి.', NULL, '16bc3de4040cc95d9ab857a0af9366d638ff6581eb569afed5c1ff46ae75b48e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1297', 'కథామాల', 'జ్ఞానమాల', 'తెలుగు సాహిత్యం', 'ఒక విద్యార్థి తెలుగు సాహిత్యం పట్ల ఆసక్తి పెంచుకున్నాడు.
పోతన, తిక్కన రచనలు చదివాడు.
భాషలో అందమైన పదాలు నేర్చుకున్నాడు.
స్వయంగా కవిత రాశాడు.
పాఠశాల పత్రికలో ప్రచురించాడు.
తెలుగు ఉపాధ్యాయులు ప్రోత్సహించారు.
మరిన్ని రచనలు చేశాడు.
భాషను ప్రేమించడం వల్ల జ్ఞానం పెరిగింది.', '11 – 15 సంవత్సరాలు వయస్సు', 'మాతృభాష సాహిత్యం చదవడం సంస్కారానికి దారి చూపిస్తుంది.', NULL, 'd029f4df0c34315e5151183e909e9a149393bea131c94dd52e396ccddb923e21') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1298', 'కథామాల', 'జ్ఞానమాల', 'కోడ్ రాసిన అమ్మాయి', 'ఒక అమ్మాయికి కంప్యూటర్ అంటే చాలా ఇష్టం.
ఇంట్లో అందరూ అమ్మాయిలకు కోడింగ్ అవసరమా అని అడిగారు.
ఆమె నవ్వి మళ్ళీ చదవడం మొదలుపెట్టింది.
ఆన్‌లైన్ కోర్సు నేర్చుకుంది.
ఒక చిన్న యాప్ తయారు చేసింది.
పాఠశాల పిల్లలకు హోంవర్క్ సహాయపడే యాప్ అది.
జిల్లా స్థాయి సైన్స్ ఫెయిర్‌లో మొదటి బహుమతి వచ్చింది.
అందరూ ఆశ్చర్యపోయారు, ఆమె నవ్వింది.', '11-16 వయస్సు', 'జెండర్ అడ్డుపడదు, సంకల్పం ముందుకు తీసుకెళ్తుంది.', NULL, '0dabd8bd115dd57122ad47f208f95109921aaf723eb888fa33266595a6b38ffb') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1299', 'కథామాల', 'జ్ఞానమాల', 'మొబైల్ వదిలాడు', 'రాహుల్ రోజూ ఆరు గంటలు ఫోన్ చూసేవాడు.
చదువు పడిపోయింది, నిద్ర తగ్గింది.
అమ్మ మాటలు పట్టించుకోలేదు.
ఒక రోజు పరీక్షలో చాలా తక్కువ మార్కులు వచ్చాయి.
అతడికి నిజంగా బాధ కలిగింది.
ఫోన్ స్క్రీన్ టైం రోజుకు ఒక గంటకు తగ్గించాడు.
చదువుకు మూడు గంటలు కేటాయించాడు.
మూడు నెలలలో ఫలితాలు అద్భుతంగా మారాయి.', '11-16 వయస్సు', 'సాంకేతికత సేవకుడు కావాలి, యజమాని కాదు.', NULL, '03882289e82ad0de3d14ca8a75b0e3816deec0439e317c755be30e4aeebed343') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1300', 'కథామాల', 'జ్ఞానమాల', 'నిరుపేద టాపర్', 'ప్రభ అనే అమ్మాయి రోజూ నాలుగు కిలోమీటర్లు నడిచి బడికి వెళ్ళేది.
ఇంట్లో వెలుతురు లేదు, కిరోసిన్ దీపంలో చదివేది.
ఎవరైనా అడిగితే ''పర్వాలేదు'' అని నవ్వేది.
పదవ తరగతిలో జిల్లాలో మొదటి స్థానం వచ్చింది.
పత్రికలలో ఫోటో వచ్చింది.
స్కాలర్‌షిప్ లభించింది.
అమ్మానాన్న కళ్ళలో నీళ్ళు వచ్చాయి.
కష్టాలు ఆమెను ఆపలేకపోయాయి.', '11-16 వయస్సు', 'పరిస్థితులు ప్రతిభను ఆపలేవు.', NULL, 'cace9d36097c48b499ecbc77624239c0025715ae51fd92a2a223c58cadeba9fd') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1301', 'కథామాల', 'జ్ఞానమాల', 'సైబర్ బుల్లీయింగ్', 'శ్రేయ సోషల్ మీడియాలో చాలా వేధింపులు ఎదుర్కొంది.
తెలియని వ్యక్తులు దురుసు వ్యాఖ్యలు చేశారు.
ఆమె మొదట భయపడింది, ఒంటరిగా అనిపించింది.
కాని తల్లిదండ్రులకు చెప్పాలని ధైర్యం చేసింది.
తల్లిదండ్రులు పోలీసులకు ఫిర్యాదు చేశారు.
ఆమె అకౌంట్ ప్రైవేట్ చేసింది.
బడిలో కౌన్సెలర్ సహాయంతో తేరుకుంది.
తర్వాత ఆమె సైబర్ సేఫ్టీ అవగాహన క్లబ్బు స్థాపించింది.', '11-16 వయస్సు', 'సమస్య దాచుకోకు, విశ్వాసమైన వారికి చెప్పు.', NULL, 'b9f48e81a4e89665b960b6b72142ff075897182ec1ee7dd1fb13a6e70e935430') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1302', 'కథామాల', 'జ్ఞానమాల', 'రైతు కొడుకు', 'ఆదిత్య రైతు కుటుంబంలో పుట్టాడు.
స్నేహితులు వేళాడించేవారు.
అతడు సిగ్గుపడేవాడు.
ఒక రోజు తండ్రితో పొలానికి వెళ్లాడు.
ఆ కష్టం, ఆ నేల వాసన, ఆ చెమట చూసి కళ్ళు చెమ్మగిల్లాయి.
తండ్రి మాట్లాడకుండానే జవాబు చెప్పాడు.
తర్వాత బడిలో ''మా నాన్న రైతు'' అని గర్వంగా చెప్పాడు.
అందరూ చప్పట్లు కొట్టారు.', '11-16 వయస్సు', 'రైతు కష్టం దేశానికి పునాది.', NULL, '40c005aaceb4434bec93c151088843edf6a133da0d51be2ff3a31137ebb2c41c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1303', 'కథామాల', 'జ్ఞానమాల', 'పర్యావరణ యోధుడు', 'వికాస్ తన పట్టణంలో ప్లాస్టిక్ మేటలు చూసి చలించిపోయాడు.
ఒంటరిగా ఏం చేయగలనని అనిపించింది.
కాని ఇన్‌స్టాగ్రామ్‌లో ''గ్రీన్ టౌన్'' పేరిట పేజీ తెరిచాడు.
నెల రోజులలో వందమంది చేరారు.
ప్రతి ఆదివారం శుభ్రత కార్యక్రమం చేశారు.
మేయర్ స్వయంగా వచ్చి అభినందించాడు.
జాతీయ పత్రికలో వార్త వచ్చింది.
వికాస్‌కు పదిహేనేళ్ళు మాత్రమే.', '11-16 వయస్సు', 'వయస్సు కాదు, సంకల్పం మార్పు తీసుకొస్తుంది.', NULL, '1942b5cde69291ebedb48945f6de711ea27076cbc5a045886fb35faf24780564') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1304', 'కథామాల', 'జ్ఞానమాల', 'పరీక్ష కాపీ', 'పరీక్ష హాల్‌లో అందరూ కాపీ చేస్తున్నారు.
అర్జున్‌కు అవకాశం ఉంది.
చేయి ముందుకు పోయింది, ఆగింది.
నాన్న మొహం గుర్తొచ్చింది.
నేనే రాశాను అని తనకు తాను చెప్పుకున్నాడు.
తక్కువ మార్కులు వచ్చాయి, కాని ఆత్మసంతృప్తి ఉంది.
తర్వాత కష్టపడి చదివాడు.
తదుపరి పరీక్షలో స్వయంగా మంచి మార్కులు తెచ్చుకున్నాడు.', '11-16 వయస్సు', 'నిజాయితీగా తెచ్చుకున్న మార్కు, కాపీ మార్కు కంటే వంద రెట్లు విలువైనది.', NULL, '442707e23078f27e1fa0b9c221762086f41689c15d8d8cf4a3e9570a89d931a8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1305', 'కథామాల', 'జ్ఞానమాల', 'మానసిక ఆరోగ్యం', 'సాయి చాలా రోజులుగా లోపల్లోపల బాధపడుతున్నాడు.
బయటకు నవ్వేవాడు, లోపల ఏడ్చేవాడు.
స్నేహితుడు గమనించాడు.
మాట్లాడమని అడిగాడు.
సాయి నెమ్మదిగా చెప్పాడు.
కౌన్సెలర్ దగ్గరకు వెళ్లాడు.
రెండు నెలలలో తేరుకున్నాడు.
మానసిక ఆరోగ్యం శారీరక ఆరోగ్యంతో సమానమని నేర్చుకున్నాడు.', '11-16 వయస్సు', 'మనసు బాధను దాచుకోకు, మాట్లాడడం చికిత్స.', NULL, '362f0af60c83a390c5b7916e39de7174b789e427b161131abaaa973ae6908834') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1306', 'కథామాల', 'జ్ఞానమాల', 'వ్యాపార మేధ', 'నందన సెలవుల్లో బోర్ అనిపించింది.
అమ్మమ్మ చేసే ఊరగాయలు చాలా రుచిగా ఉంటాయని తెలుసు.
పక్కింటివారికి పంపింది.
వారు మరిన్ని కావాలని అడిగారు.
చిన్న అమ్మకాలు మొదలుపెట్టింది.
WhatsApp గ్రూప్‌లో చేర్చింది.
నెలలో ఐదు వేల రూపాయలు సంపాదించింది.
అమ్మమ్మతో పంచుకుంది, ఇద్దరూ సంతోషించారు.', '11-16 వయస్సు', 'అవకాశం వెతికితే ఇంట్లోనే దొరుకుతుంది.', NULL, '3cba1fbc397d1ec4121c6748b37e0ecc7df5701ab86caaf35f0b1475803cb1a7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1307', 'కథామాల', 'జ్ఞానమాల', 'తెలుగు గర్వం', 'ఒక విద్యార్థి ఇంగ్లీషు మాట్లాడటానికే గర్వపడేవాడు.
తెలుగు పేలవమైనది అనుకునేవాడు.
ఒక రోజు తిక్కన, పోతన రచనలు చదివాడు.
భాష లోతు అర్థమైంది.
తెలుగు శాస్త్రీయ హోదా గురించి తెలుసుకున్నాడు.
తరగతిలో తెలుగులో ప్రసంగం చేశాడు.
అందరూ మంత్రముగ్ధులయ్యారు.
మాతృభాష పట్ల గర్వం జాగృతమైంది.', '11-16 వయస్సు', 'మాతృభాష అమ్మ లాంటిది, గౌరవించాలి.', NULL, 'b0df5e592d019091a1761b9d902b2114be67fa9b7b35795cad7b2c21db882efb') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1308', 'కథామాల', 'జ్ఞానమాల', 'క్రీడా మనోబలం', 'అనన్య రాష్ట్ర స్థాయి బ్యాడ్మింటన్ పోటీలో ఓడింది.
కోచ్ వదిలేయమని చెప్పలేదు.
ఆమె రోజూ ఒంటరిగా ఆడి సాధన చేసింది.
బలహీనతలు గుర్తించి సరిచేసుకుంది.
తర్వాతి సంవత్సరం మళ్ళీ పోటీలో దిగింది.
ఫైనల్‌కు చేరింది.
రజత పతకం గెలిచింది.
ఆ పతకం ఆమె కన్నీళ్ళతో తడిసింది.', '11-16 వయస్సు', 'ఓటమి ముగింపు కాదు, సాధనకు మొదలు.', NULL, 'df47a7d36a8bb19f3e784195c8cb207746fcabf3ea07da87f3a69610460ac48c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1309', 'కథామాల', 'జ్ఞానమాల', 'ఆర్థిక పాఠం', 'తండ్రి ప్రతి నెలా జేబు డబ్బు ఇచ్చేవాడు.
అర్జున్ వెంటనే అన్నీ కొని అయిపోయేవాడు.
ఒక రోజు అవసరమైన పుస్తకం కొనే డబ్బు లేదు.
తండ్రి అప్పుడు ఒక నోట్‌బుక్ ఇచ్చి ''ఖర్చులు రాయి'' అన్నాడు.
అర్జున్ రాయడం మొదలుపెట్టాడు.
అనవసరమైన ఖర్చులు అర్థమయ్యాయి.
మూడు నెలలలో చిన్న మొత్తం ఆదా చేశాడు.
తన మొదటి పిగ్గీ బ్యాంక్‌లో వేశాడు.', '11-16 వయస్సు', 'సంపాదించడం కంటే తెలివిగా ఖర్చు చేయడం నేర్చుకోవాలి.', NULL, '697cae740e67ae34b8a56d128c9bdd0f61dd459e58baf6c3c15aebe5b5aec27f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1310', 'కథామాల', 'జ్ఞానమాల', 'సమాజ సేవ', 'ఒక బాలుడు ప్రతి ఆదివారం వృద్ధాశ్రమానికి వెళ్ళేవాడు.
వృద్ధులతో మాట్లాడేవాడు, కథలు విన్నేవాడు.
స్నేహితులు సమయం వృథా అన్నారు.
అతడు మారలేదు.
వృద్ధులు అతడికి జీవిత అనుభవాలు చెప్పారు.
ఆ జ్ఞానం బడిలో రాదని అర్థమైంది.
ఒక వృద్ధుడు తన పాత పుస్తకాల సేకరణ బహుమతిగా ఇచ్చాడు.
ఆ పుస్తకాలు అతడి జీవితాన్ని మార్చాయి.', '11-16 వయస్సు', 'ఇతరులకు ఇచ్చిన సమయం మనకు జ్ఞానంగా తిరిగి వస్తుంది.', NULL, '9d245c1507c1e642b66bb01e322d2eef3b1b7fb05ccc4e8a4c54b22493be856e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1311', 'కథామాల', 'జ్ఞానమాల', 'అభిప్రాయ ధైర్యం', 'తరగతిలో టీచర్ అడిగిన ప్రశ్నకు అందరూ ఒకే జవాబు చెప్పారు.
కావ్యకు వేరే అభిప్రాయం ఉంది.
తప్పు అంటారని భయపడింది.
కాని చేయి ఎత్తి మాట్లాడింది.
ఆమె దృక్కోణం వేరుగా ఉంది కాని సరైనది.
టీచర్ ''బ్రేవో'' అన్నారు.
తరగతి ఆలోచనలు పెరిగాయి.
వేరే అభిప్రాయం వ్యక్తం చేయడం ధైర్యమని అందరికీ అర్థమైంది.', '11-16 వయస్సు', 'అందరూ చెప్పినదే నిజం కాదు, ఆలోచించి మాట్లాడు.', NULL, 'a1aac52753035e23660d23ac46e16dd4812a2a1a91f3d91b063d6d760192f318') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1312', 'కథామాల', 'జ్ఞానమాల', 'విద్యార్థి నాయకుడు', 'పాఠశాల యూనియన్ ఎన్నికలు వచ్చాయి.
రోహన్ నాయకుడిగా నిలిచాడు.
ఊరికే మాటలు చెప్పలేదు.
ప్రతి విద్యార్థి సమస్య వినాడు.
పరిష్కారాలు సూచించాడు.
అందరి ఓట్లతో గెలిచాడు.
గెలిచిన తర్వాత ప్రజలకు ఇచ్చిన మాట పాటించాడు.
నిజమైన నాయకత్వం అంటే మాటలు కాదు, చేతలు అని నిరూపించాడు.', '11-16 వయస్సు', 'నాయకత్వం అంటే బాధ్యత, అధికారం కాదు.', NULL, '0f70f44095eee23d1d1013efec1abce6e09892d134f2da6b0ce91ddfe6d193c0') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1313', 'కథామాల', 'జ్ఞానమాల', 'కళలో బ్రతుకు', 'అమ్మానాన్న ఇంజనీర్ అవ్వమని చెప్పారు.
మేఘన కు డ్రాయింగ్ అంటే ప్రాణం.
రోజూ స్కెచ్‌బుక్ నింపేది.
ఒక రోజు ఆమె చిత్రం రాష్ట్ర స్థాయి పోటీలో మొదటి బహుమతి తెచ్చింది.
ప్రముఖ ఆర్ట్ కళాశాల నుండి పిలుపు వచ్చింది.
అప్పుడు అమ్మానాన్న అర్థం చేసుకున్నారు.
ఆమె కలలు వాస్తవమయ్యాయి.
నచ్చిన పని చేస్తే జీవితం అర్థవంతం అవుతుందని నేర్చుకుంది.', '11-16 వయస్సు', 'మనసుకు నచ్చిన పనిలో ప్రతిభ వికసిస్తుంది.', NULL, 'c11da2ecac544060a107c847304b25a6107c8aedbf2602418cc72f5f9575bd19') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1314', 'కథామాల', 'జ్ఞానమాల', 'వ్యర్థాలతో కళ', 'కార్తీక్ వ్యర్థ వస్తువులు చూసి ఆలోచించాడు.
పాత బాటిళ్ళు, కాగితాలతో అందమైన వస్తువులు చేశాడు.
స్నేహితులకు చూపించాడు.
పాఠశాలలో ఒక ప్రదర్శన పెట్టాడు.
ఉపాధ్యాయులు మెచ్చుకున్నారు.
స్థానిక పత్రికలో వార్త వచ్చింది.
ఆర్డర్లు వచ్చాయి.
చెత్తతో సంపద అవుతుందని నిరూపించాడు.', '11-16 వయస్సు', 'వ్యర్థం అని వదిలేయకు, ఆలోచిస్తే అది ఆస్తి.', NULL, 'd6fa1a0e99814ff39b01ef0922e7ef012d449366f17ffefeefe017c7dc928e48') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1315', 'కథామాల', 'జ్ఞానమాల', 'గ్రూప్ ప్రెజర్', 'స్నేహితులందరూ తప్పు పని చేయమని ఒత్తిడి చేశారు.
అక్బర్ మొదట ఊగిసలాడాడు.
చేస్తే స్నేహం అని చెప్పారు.
అతడు ఒక్క క్షణం ఆగి ఆలోచించాడు.
నా నిర్ణయం నాది అని స్పష్టంగా చెప్పాడు.
ముందు ఒంటరిగా అనిపించింది.
తర్వాత నిజమైన స్నేహితులు చేరారు.
తప్పు స్నేహం కంటే ఒంటరిగా ఉండటం మేలు అని తెలిసింది.', '11-16 వయస్సు', 'ఒత్తిడికి తలవంచకు, నిజమైన స్నేహం ఒత్తిడి పెట్టదు.', NULL, '809ad504f8b41552e6bd97dea9576d88a3a8608d4f527892e970b3e722c494ee') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1316', 'కథామాల', 'జ్ఞానమాల', 'సైన్స్ కల', 'ఒక బాలుడికి అంతరిక్షం అంటే అమితమైన ఆసక్తి.
రోజూ నక్షత్రాలు చూసేవాడు.
నోట్‌బుక్‌లో ఆబ్జర్వేషన్లు రాసేవాడు.
ఇస్రో వెబ్‌సైట్‌లో పిల్లల పోటీ చూశాడు.
ఒక రాకెట్ మోడల్ తయారు చేశాడు.
పోటీలో ఎంపిక అయ్యాడు.
బెంగళూరులో ఇస్రో శాస్త్రవేత్తలను కలిశాడు.
అది అతడి జీవితంలో మర్చిపోలేని రోజు అయింది.', '11-16 వయస్సు', 'కలను నోట్‌బుక్‌లో రాస్తే అది నిజమవ్వడానికి దగ్గరవుతుంది.', NULL, 'db168de7433dc714fdd34eecc0fb501944c7924c196275ea68f911c4b02b9375') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1317', 'కథామాల', 'జ్ఞానమాల', 'ఇంట్లో పెద్ద', 'తండ్రి అనారోగ్యంగా ఉన్నాడు.
పదహారేళ్ళ సురేష్ కుటుంబానికి పెద్ద అయ్యాడు.
చదువు మానలేదు.
పొద్దున బడి, సాయంత్రం చిన్న పని చేశాడు.
అమ్మకు ధైర్యం చెప్పాడు.
తమ్ముడు అక్కకు సహాయం చేశాడు.
తండ్రి తేరుకున్నారు.
కష్ట సమయంలో కుటుంబం ఒక్కటిగా నిలిచింది.', '11-16 వయస్సు', 'కుటుంబ బాధ్యత వయస్సు చూడదు, మనసు చూస్తుంది.', NULL, '75613e2510b7098eaa7864f9b30f3449e8ddf524fe16d594f1fb62e37a85d486') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1318', 'కథామాల', 'జ్ఞానమాల', 'ఫేక్ న్యూస్', 'WhatsApp లో ఒక వార్త వచ్చింది.
అందరూ షేర్ చేశారు.
దివ్య ఆగింది.
అది నిజమా అని సోర్స్ వెతికింది.
అది అబద్ధమని తేలింది.
గ్రూప్‌లో అందరికీ చెప్పింది.
కొందరు ఆశ్చర్యపోయారు.
ఇకపై ఏ వార్తా వెరిఫై చేయకుండా షేర్ చేయకూడదని నిర్ణయించుకున్నారు.', '11-16 వయస్సు', 'ఆలోచించకుండా షేర్ చేయకు, ఒకసారి వెరిఫై చేయి.', NULL, '19b2821ffa9b470683c67bfe07a00ef37be7cad071d0dd40a6edaa895983b291') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1319', 'కథామాల', 'జ్ఞానమాల', 'అర్థం అయిన తప్పు', 'తారిణి తన స్నేహితురాలి పుస్తకం పోగొట్టింది.
మొదట దాచింది.
రాత్రి నిద్ర రాలేదు.
తెల్లవారు జామున లేచి స్నేహితురాలికి ఫోన్ చేసింది.
నిజం చెప్పింది.
కొత్త పుస్తకం కొని ఇచ్చింది.
స్నేహితురాలు క్షమించింది.
నిజంగా ఏడ్చి మన్నించిన స్నేహం మరింత బలపడింది.', '11-16 వయస్సు', 'తప్పు అంగీకరించడం బలహీనత కాదు, గొప్ప ధైర్యం.', NULL, '0f4df30f3a05343ecca4caabc30a477db8f2e2888159b3330f2c0f95949ea188') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1320', 'కథామాల', 'జ్ఞానమాల', 'చదువుకు ఆడంబరం వద్దు', 'రాహుల్ పాత ఫోన్‌తో చదివేవాడు.
స్నేహితులు కొత్త గాడ్జెట్లు చూపించేవారు.
అతడికి అసూయ కలిగింది కాని అదే ధ్యాసలో ఉండలేదు.
పాత నోట్సు, సింపుల్ రొటీన్‌తో చదివాడు.
జాతీయ స్థాయి పరీక్షలో మంచి ర్యాంక్ వచ్చింది.
స్నేహితులు ఆశ్చర్యపోయారు.
రహస్యం అడిగారు.
రహస్యం లేదు, ఫోకస్ ఉంది అన్నాడు.', '11-16 వయస్సు', 'గాడ్జెట్లు కాదు, దృష్టి చదువును మెరుగుపరుస్తుంది.', NULL, '995eed09583c83fec23a80654b314604357527efd03af06d22d47d761b5d60a6') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1321', 'కథామాల', 'జ్ఞానమాల', 'మానవత్వం', 'వర్షంలో ఒక వృద్ధుడు తడుస్తున్నాడు.
అందరూ గొడుగులు పట్టుకుని వేగంగా వెళ్ళారు.
కిరణ్ ఆగాడు.
తన గొడుగు పట్టుకుని ఆ వృద్ధుడి దగ్గరకు వెళ్లాడు.
ఇంటి వరకు తీసుకెళ్లాడు.
తాను తడిశాడు కాని అతడికి పట్టలేదు.
ఇంటికి వచ్చాక అమ్మ కళ్ళు చెమ్మగిల్లాయి.
మానవత్వం పుస్తకంలో కాదు, హృదయంలో ఉంటుంది.', '11-16 వయస్సు', 'సహాయం చేయడానికి సమయం కాదు, మనసు కావాలి.', NULL, '2efa391a7cba436a8d80685d408c3b5d94d5a371119b48d9cf6ed9572fa3a13e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1322', 'కథామాల', 'జ్ఞానమాల', 'డాక్టర్ కావాలి', 'నీలిమ చిన్నప్పటి నుండి డాక్టర్ అవ్వాలని కలగన్నది.
నిరుపేద కుటుంబం, ఆర్థిక ఇబ్బందులు.
కాని ప్రతి పరీక్షలో టాప్ చేసింది.
ఒక NGO ఆమెకు స్కాలర్‌షిప్ ఇచ్చింది.
మెడికల్ కాలేజీలో సీటు వచ్చింది.
తన ఊరిలోనే ఆసుపత్రి తెరవాలని నిర్ణయించింది.
ఆమె తల్లిదండ్రులు తలలు నిటారుగా నిలిపారు.
ఆమె ప్రతి కష్టం ఒక మెట్టు అయింది.', '11-16 వయస్సు', 'కల స్పష్టంగా ఉంటే మార్గం దొరుకుతుంది.', NULL, '1f69add62bfe124f1f664f15af3585a92e6bcc12d329196e94daccc90abb1a94') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1323', 'కథామాల', 'జ్ఞానమాల', 'ఆత్మగౌరవం', 'పాఠశాలలో ఒక బృందం రోహిణిని వేళాడించేది.
ఆమె సాదాగా ఉంటుందని, పాత బట్టలు వేసుకుంటుందని.
ఆమె మొదట బాధపడింది.
తర్వాత తనకు తాను చెప్పుకుంది, నా విలువ నా బట్టలు కాదు.
చదువులో, కళలో ముందుండింది.
ఒక వేదికపై ప్రసంగించింది.
అందరూ మెచ్చుకున్నారు.
వేళాడించిన వారే అభినందించారు.', '11-16 వయస్సు', 'ఆత్మగౌరవం బయటి వస్తువులలో కాదు, లోపలి బలంలో ఉంటుంది.', NULL, '8f29287b15e1c67d49318b9848ae2e41a541ae9c71aa25f9baa724019545a0bc') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1324', 'కథామాల', 'జ్ఞానమాల', 'సమయ నిర్వహణ', 'ఒక విద్యార్థికి చదువు, క్రీడలు, కళలు అన్నీ ఉన్నాయి.
అన్నింటినీ బ్యాలెన్స్ చేయడం కష్టంగా ఉంది.
అతడు ఒక వారపు షెడ్యూల్ రాసుకున్నాడు.
ప్రతి పనికి సమయం కేటాయించాడు.
క్రమంగా అన్నీ సాధ్యమయ్యాయి.
పరీక్షలలో మంచి మార్కులు వచ్చాయి.
జిల్లా క్రీడలలో పాల్గొన్నాడు.
ప్లానింగ్ ఒక గొప్ప జీవన నైపుణ్యమని తేలింది.', '11-16 వయస్సు', 'సమయాన్ని ప్లాన్ చేస్తే అన్ని కలలూ సాధ్యమవుతాయి.', NULL, '300e9fe4d3b127f6a8fd29cbde4d82674f67a80396ede3941d6ba33ebe5f7338') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1325', 'కథామాల', 'జ్ఞానమాల', 'పల్లె జ్ఞానం', 'పట్టణంలో పెరిగిన అమ్మాయి తాతగారి ఊరికి వెళ్ళింది.
అక్కడ మొబైల్ నెట్‌వర్క్ లేదు.
మొదట విసుక్కుంది.
తర్వాత పొలాలలో నడిచింది, నక్షత్రాలు చూసింది.
తాత తో కూర్చుని మాట్లాడింది.
ప్రకృతి, జీవితం గురించి అద్భుతమైన జ్ఞానం నేర్చుకుంది.
ఒక వారంలో మనసు చాలా తేలికపడింది.
నెట్‌వర్క్ లేకున్నా ఆ ఊరే అసలు కనెక్షన్ ఇచ్చింది.', '11-16 వయస్సు', 'జ్ఞానం పుస్తకాల్లోనే కాదు, ప్రకృతిలోనూ ఉంటుంది.', NULL, 'e4978d81003c5d9fa97a17f36426421705df706e2368b637bf91cc44ae80dacf') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1326', 'కథామాల', 'జ్ఞానమాల', 'వికలాంగ స్నేహితుడు', 'కొత్తగా చేరిన విద్యార్థి వీల్ చెయిర్‌పై వచ్చాడు.
కొందరు అతడివైపు చూసి తప్పుకున్నారు.
అభిలాష్ అతడి దగ్గరకు వెళ్లాడు.
హాయ్ చెప్పాడు, పరిచయం చేసుకున్నాడు.
క్రమంగా అందరూ చేరారు.
ఆ కొత్త విద్యార్థి అద్భుతంగా గణితం చేశాడు.
తరగతి ప్రాజెక్ట్‌కు గ్రూప్ లీడర్ అయ్యాడు.
అభిలాష్ చొరవ తరగతిలో విభజన తొలగించింది.', '11-16 వయస్సు', 'వ్యత్యాసాలు చూసి దూరం కాకు, దగ్గరకు వెళ్ళు.', NULL, '8542977a0fd5aea70deb0793c5cba08b43dede9be97cf81870058bbdf3dc1bed') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-1327', 'కథామాల', 'జ్ఞానమాల', 'రేపటి తరం', 'పాఠశాల వీడ్కోలు సభలో టీచర్ అడిగారు: ''మీరు ఏమవ్వాలనుకుంటున్నారు?''
ఒకరు డాక్టర్, ఒకరు ఇంజినీర్, ఒకరు ఆర్టిస్ట్ అన్నారు.
చివరిగా అమర్ అన్నాడు: ''నేను మంచి మనిషి అవ్వాలనుకుంటున్నాను.''
అందరూ నవ్వారు.
టీచర్ నవ్వలేదు, చప్పట్లు కొట్టారు.
''మంచి మనిషి అయితే మిగిలినవన్నీ అదే వస్తాయి'' అన్నారు.
అందరూ ఆలోచించారు.
ఆ మాటలు అందరి హృదయాల్లో నిలిచిపోయాయి.', '11-16 వయస్సు', 'గొప్ప వృత్తి కంటే గొప్ప వ్యక్తిత్వం ముఖ్యం.', NULL, '078f2b0786d998345d0943eedc6dfd60d9d2df5ae584edcf789561c2e472d562') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
