INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2087', 'సామెతలమాల', 'జ్ఞానమాల', 'అత్తకూతురని అరవకూడదు, నిండుమనిషిని కొట్టకూడదు', '', '"అ" అక్షరం', '', NULL, '2da502556cfea05f61bafb0c53532f1026d852cf0674be436b1455766b5cd322') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2088', 'సామెతలమాల', 'జ్ఞానమాల', 'అత్తమీద కోపం దుత్తమీద తీర్చుకున్నట్లు.', '', '"అ" అక్షరం', '', NULL, 'a7ba95b1a4d7887f29b5831b589dca023cd1eefb18f9ab029ec690024eb0a6af') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2089', 'సామెతలమాల', 'జ్ఞానమాల', 'అత్తరు పన్నీరు గురుగురులు దాని దగ్గరకు పోతే లబలబలు', '', '"అ" అక్షరం', '', NULL, '55cbd6150caed98021c61f08505de3285a2711b7022e20a7db4bdab3987694a7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2090', 'సామెతలమాల', 'జ్ఞానమాల', 'అత్తలేని కోడలు ఉత్తమురాలు కోడలు లేని అత్త గుణవంతురాలు', '', '"అ" అక్షరం', '', NULL, '3a48dbf13c93448677082132f8e20b52a23245fcad2dd8d70db40647cf7fa56e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2091', 'సామెతలమాల', 'జ్ఞానమాల', 'అత్తా ఒక ఇంటి కోడలే, మామా ఒకింటి అల్లుడే', '', '"అ" అక్షరం', '', NULL, 'd78cf62eac219007a7c0352a623c5b579607231ac499e51563ed512546f35c3f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2092', 'సామెతలమాల', 'జ్ఞానమాల', 'అత్తసొమ్ము అల్లుడు దానం చేసినట్లు', '', '"అ" అక్షరం', '', NULL, 'd19e44065f6cf6fbf9e9156dcc15e97ba05394d58479a27da0b60f35d9ac5764') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2093', 'సామెతలమాల', 'జ్ఞానమాల', 'అదిగో తెల్లకాకి అంటే ఇదిగో పిల్ల కాకి అన్నట్లు', '', '"అ" అక్షరం', '', NULL, 'd12afade3c956d526c9336a942e64b920abf19d9518b94a93c2f796c5ec1a6df') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2094', 'సామెతలమాల', 'జ్ఞానమాల', 'అదిగో పులి అంటే ఇదిగో తోక అన్నట్టు', '', '"అ" అక్షరం', '', NULL, 'd685db7fc4819d1b32c1993e91d3a4e92dec44ec3f387bf0700838ba83ca9b92') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
