INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2096', 'సామెతలమాల', 'జ్ఞానమాల', 'అనగా అనగా రాగం తినగా తినగా రోగం', '', '"అ" అక్షరం', '', NULL, '4b68d5b71a5f014d38913181bf95bec744ce70c2ca094e6271f403aaabcf3957') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2097', 'సామెతలమాల', 'జ్ఞానమాల', 'అనువుగాని చోట అధికుల మన రాదు', '', '"అ" అక్షరం', '', NULL, 'ed6374fdd1d6ca0f5471974a97eee0b6c2bdac56b5f656b51e3ba0447e1f7747') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2098', 'సామెతలమాల', 'జ్ఞానమాల', 'అనుమానం పెనుభూతం', '', '"అ" అక్షరం', '', NULL, 'b2b5046bb463b1016e6f109569acbded7df71d83f2f2cf569ff984a545d67f41') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2099', 'సామెతలమాల', 'జ్ఞానమాల', 'అన్నవస్త్రాల కోసం పోతే ఉన్న వస్త్రాలు ఊడిపోయాయట', '', '"అ" అక్షరం', '', NULL, 'd0f26280f8a1e40df833bc14c87a4ee91ea882247b86b66aea2f52b52fbe03aa') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2100', 'సామెతలమాల', 'జ్ఞానమాల', 'అన్నవారు బాగున్నారు, పడినవారు బాగున్నారు మధ్యనున్న వారే నలిగిపోయారన్నట్లు', '', '"అ" అక్షరం', '', NULL, 'f38366c1d8f87af274359e551800e506697f0d366d8c79b58b288deb11dda239') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2101', 'సామెతలమాల', 'జ్ఞానమాల', 'అన్నం పెట్టేవాడు దగ్గరుండాలి దణ్ణం పెట్టేవాడు దూరంగా ఉన్నా పర్వాలేదు', '', '"అ" అక్షరం', '', NULL, '04b1a12a002b5fa9c241500884d51c5081c31239a64f302a6d981eff3d85cc3f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2102', 'సామెతలమాల', 'జ్ఞానమాల', 'అన్నం చొరవే గానీ అక్షరం చొరవ లేదు', '', '"అ" అక్షరం', '', NULL, '2e53ad835a6bd087fefcbe8fd626ed697f97d9292778b9c7457c892e2f8503c6') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2103', 'సామెతలమాల', 'జ్ఞానమాల', 'అన్నం పెట్టే వాడికన్నా సున్నం పెట్టే వాళ్లే ఎక్కువ', '', '"అ" అక్షరం', '', NULL, '45d7df9ab0b32b17665f4fdac461be36ef8657057cff06cbfd7438cb18f1917c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2104', 'సామెతలమాల', 'జ్ఞానమాల', 'అన్నీ ఉన్న ఆకు అణగి మణగి ఉంటుంది. ఏమీ లేని ఆకు ఎగిరెగిరి పడుతుంది', '', '"అ" అక్షరం', '', NULL, '5fb68dece0346bc9e4b3f02797cbe189629bd12ca4958bdfdb3fbc9d9a48d7e9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2105', 'సామెతలమాల', 'జ్ఞానమాల', 'అన్నీ సాగితే రోగంమంత భోగము లేదు', '', '"అ" అక్షరం', '', NULL, '0d77d0d199e40115024fb75317e6aeedacf70d0b57cc20b84e18067193316df1') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2106', 'సామెతలమాల', 'జ్ఞానమాల', 'అపానవాయువును అణిచిపెడితే ఆవులింతలు ఆగుతాయా?', '', '"అ" అక్షరం', '', NULL, 'fde90f8c6604fff0634abad30024b6b00b3418799c67e88be26c28da90e1709c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2107', 'సామెతలమాల', 'జ్ఞానమాల', 'అప్పటికి దుప్పటిచ్చాముగానీ కలకాలం ఇస్తామా?', '', '"అ" అక్షరం', '', NULL, '74023b59a4cf73b2707717c0a5c53f78046bcf9c1140a6ce0f221e434006cfd4') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2108', 'సామెతలమాల', 'జ్ఞానమాల', 'అప్పనుచూడబోతే రెప్పలు పోయినై', '', '"అ" అక్షరం', '', NULL, 'a455c6cd40bd20f9ae33490e3ffad37772c1405eb2b4d15766ae79c6b8aae374') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2109', 'సామెతలమాల', 'జ్ఞానమాల', 'అప్ప సిరిచూసుకొని మాచి మడమలు తొక్కింది', '', '"అ" అక్షరం', '', NULL, '591a57fc7ba2332912123cf2a2f99e41b65bd47ecd7c01b254289e0fe0f9ff40') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
