INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2125', 'సామెతలమాల', 'జ్ఞానమాల', 'అమ్మకి కూడు పెట్టనివాడు, పెద్దమ్మకి కోక పెడతానన్నాడు', '', '"అ" అక్షరం', '', NULL, 'eee6c7f507923826249f50a7dc79659aee75be2213ed1c8fb5c3ab029bc6c6e5') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
