INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2141', 'సామెతలమాల', 'జ్ఞానమాల', 'అర్దరాత్రి మద్దెల దరువు', '', '"అ" అక్షరం', '', NULL, 'd190c487fbf2c2cb85a02ef68c5b1874db0f4b3bcfc3a583f8e4dc372acc6f7c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2142', 'సామెతలమాల', 'జ్ఞానమాల', 'అలకాపురికి రాజైతే మాత్రం అమితంగా ఖర్చు చేస్తాడా...', '', '"అ" అక్షరం', '', NULL, '97fea3c211f9a17fcae1caaf93d3dec73b1812629ac4167fb83cd81aba8280d3') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2143', 'సామెతలమాల', 'జ్ఞానమాల', 'అల్లుడికి ఐశ్వర్యం వస్తే అర్ధరాత్రి గొడుగు పట్టమన్నాడట', '', '"అ" అక్షరం', '', NULL, '2b9a5ffefe3c18c9209abb6d35df50c580f36b5b7738d430c50b9b349a6853bc') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
