INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2162', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆకు వెళ్ళి ముల్లు మీద పడ్డా, ముల్లు వెళ్ళి ఆకు మీద పడ్డా ఆకుకే నష్టం', '', '"ఆ" అక్షరం', '', NULL, 'f2973c3494b624d94d8bcd4feb099c03ca6617552fc92cc7720bd4a8f6e47b3b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2163', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆకులు నాకేవాడింటికి మూతులు నాకేవాడు వాచ్చాడట', '', '"ఆ" అక్షరం', '', NULL, '2589211f4eab55faa116037d5bb6472cabd0c4ebde018701b6bee7770755b43a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2164', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆకులేని పంట అరవైఆరు పుట్లు...', '', '"ఆ" అక్షరం', '', NULL, 'ad6cd33cf6e9404262d62964e95d6ed9c5313d5d489f971b5155b4bd588e8bd8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2165', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆడది తిరిగి చెడుతుంది,మగవాడు తిరక్క చెడతాడు', '', '"ఆ" అక్షరం', '', NULL, 'fb23d3a449d489a419fdf9c97639155100218ed23594ac767d7f69eebefd682d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2166', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆడపిల్ల పెళ్ళి, అడుగు దొరకని బావి అంతం చూస్తాయన్నట్లు...', '', '"ఆ" అక్షరం', '', NULL, 'c619e7810f24b9568fe73f8041082afc787839d9162c2d29eb24ac859fe06b18') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2167', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆడబోయిన తీర్థమెదురైనట్లు', '', '"ఆ" అక్షరం', '', NULL, 'dbcce07c0652b4a7b4f65e16c417f8cda87efa2f227d543a1ba43ccf62cdc3c9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2168', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆడలేక మద్దెల ఓడు అన్నట్లు', '', '"ఆ" అక్షరం', '', NULL, 'fde485825803c23c6b3344a5f6fc9aa745dc08c72cb7f9cd1f9958f5cb6d9cfb') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2169', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆత్రగాడికి బుద్ది మట్టం', '', '"ఆ" అక్షరం', '', NULL, '0f23e4a180f1d0adfd1304a9cdcc3a66f1866e7a33362c1f20fd939425d6f2ee') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2170', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆత్రపు పెళ్ళికొడుకు అత్త మెళ్ళో తాళి కట్టినట్లు', '', '"ఆ" అక్షరం', '', NULL, '539f15cfa3daa7ce271a21e5eaa82889beb7ee7420739bf290f9f097c31d5a5d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2171', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆరాటపు పెళ్ళికొడుకు పెరంటాళ్ళ వెంట పడ్డ్డాడట', '', '"ఆ" అక్షరం', '', NULL, 'ee57b7cd2f828489b52a7ae3db8eef053b61c5d12e610b86b8fc1bfea068d1d2') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2172', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆదిలోనే హంసపాదు', '', '"ఆ" అక్షరం', '', NULL, '3d93f5c91108d8200249dcbd7881d4520621fa5dd6a6a6a4d42df4bdba22cca4') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2173', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆపదలో మొక్కులు... సంపదలో మరపులు', '', '"ఆ" అక్షరం', '', NULL, '0b17337d53d79893dd0d6f45c3182b12c55e3b1c694cf2ade528b55ff3cb311c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2174', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆమడదూరం నుంచి అల్లుడు వస్తే మంచం కింద ఇద్దరు, గోడమూల ఒకరు దాగుంటారు', '', '"ఆ" అక్షరం', '', NULL, '8c38926339b39ae311b30ca8a9cf763841b1d87fd35a6de47cf4a4483a8f2e13') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2175', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆ మరకా ఈ మరకా అడ్డగోడకి, ఆ మాటా ఈ మాటా పెద్దకోడలకి', '', '"ఆ" అక్షరం', '', NULL, '741a13063faf3e2a053d9f473c96847ffe099b3c7cc81a597467680f7be6b85d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2176', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆయనే ఉంటే మంగలి ఎందుకు', '', '"ఆ" అక్షరం', '', NULL, 'a2804808e569d43dafe7fa70de09aa19b900590889d44dde3b18e0d9bee6f69f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2177', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆరిపోయే దీపానికి వెలుగెక్కువ', '', '"ఆ" అక్షరం', '', NULL, '798ae1d22082ce52f211907f12774376755dfdc1286e799e11e25e910f2bd3b3') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2178', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆరు నెలలు సావాసం చేస్తే వారు వీరవుతారు', '', '"ఆ" అక్షరం', '', NULL, '58073090a6b82b8a081e816245befef6768056990143d63bccb9d3682815c78d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2179', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆరోగ్యమే మహాభాగ్యం', '', '"ఆ" అక్షరం', '', NULL, 'a2bab070216608395b0f91c9c45733cc30bf6a3411fcea8e864a4fb24abb912f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2180', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆలస్యం అమృతం విషం', '', '"ఆ" అక్షరం', '', NULL, 'd8e40093ef0a7c51562d6dc1f8dd6c71ef065e786be4daf906e809e93f4d661c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2181', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆలి బెల్లమాయె తల్లి అల్లమాయె', '', '"ఆ" అక్షరం', '', NULL, 'd3f8b0ba0835dea5e9de008bb49286273eba3d8caa3eabee9291c0c43a485ab8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2182', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆలికి అన్నంపెట్టి, ఊరికి ఉపకారంచేసినట్లు చెప్పాట్ట', '', '"ఆ" అక్షరం', '', NULL, 'be983d51470f5f627ddf775b1140797a60531eb281c6a054bc5568aa675df297') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2183', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆలు బిడ్డలు అన్నానికి ఏడుస్తుంటే... చుట్టానికి బిడ్డలు లేరని రామేశ్వరం పోయాడట.', '', '"ఆ" అక్షరం', '', NULL, '396b572d16786cb02f8192246c557715bad0d4fcf35205b70051915786df5dcb') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2184', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆలూలేదు చూలులేదు కొడుకుపేరు సోమలింగం', '', '"ఆ" అక్షరం', '', NULL, '4b3df835fb3cdcb5f02179ecf5b581ab8e3d1c5d599c8ca2b641603a703fd122') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2185', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆవు చేలో మేస్తే, దూడ దుగాన/గట్టున మేస్తుందా?', '', '"ఆ" అక్షరం', '', NULL, '796b2177e7eca7ccd56fe902cb1ae90c1413a7ddbc725139c4e0da0f67159da3') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2186', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆవుకు, దూడకు లేని బాధ గుంజకెందుకో?', '', '"ఆ" అక్షరం', '', NULL, 'c98ce84b16f8d5054e618e8d04bf73b6cb011ae088836fe0418332573143404c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2187', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆవులింతకు అన్నలు ఉన్నారు కాని, తుమ్ముకు తమ్ముడు లేడు', '', '"ఆ" అక్షరం', '', NULL, '5658aaff35e48d18f6d00a79da08bc53056204a9a17585bdc1f2af4dbc395a32') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2188', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆవులిస్తే ప్రేగులు లెక్క పెట్టే రకం', '', '"ఆ" అక్షరం', '', NULL, '837bfd230e945d95a2f9823705d69fc011af738a33d3d655fae753030a230863') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2189', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆశగలమ్మ దోషమెరుగదు... పూటకూళ్లమ్మ పుణ్యమెరుగదు', '', '"ఆ" అక్షరం', '', NULL, '4b29362942114b4f6b003efd5dd297752d3b53d0f8d9baee89e74e4745e850df') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2190', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆశపడి ఆరు లంఖణాలు చేస్తే, ఆ వేళా జొన్న కూడే గతి అయినట్టు', '', '"ఆ" అక్షరం', '', NULL, '6814b05eb8453b676a12a8773315f867250aa009f14bc2ce4852497564811b1d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2191', 'సామెతలమాల', 'జ్ఞానమాల', 'ఆవు చేల్లో మేస్తే దూడ గట్టున మేయునా?', '', '"ఆ" అక్షరం', '', NULL, '3f7cd2af16b92b115b838697f0bf153638084051ca9466a1e4d57963fb76418d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
