INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2200', 'సామెతలమాల', 'జ్ఞానమాల', 'ఇరుపోటీలతోటి ఇల్లు చెడె, పాత నొప్పులతోటి ఒళ్ళు చెడె', '', '"ఇ" అక్షరం', '', NULL, 'fb769a1bad97827b39b06d433e7ba281d9fb6c5dd761235a3dfb4212eb12e85a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
