INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2243', 'సామెతలమాల', 'జ్ఞానమాల', 'ఎత్తిపోయే కాపురానికి ఏ కాలు పెడితేనేమి?', '', '"ఎ" అక్షరం', '', NULL, '32c118818a9c97b2fd8c9ea55a0397910f975a1f95d368476b85c4c0d32a4d9b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2244', 'సామెతలమాల', 'జ్ఞానమాల', 'ఎద్దు ఈనిందని ఒకడంటే, దూడను గాట కట్టెయ్యమని మరోడన్నాడంట', '', '"ఎ" అక్షరం', '', NULL, 'de1c5705920b5d5b1fef4f40c3121d6d8681a87d7623a9276601db1a4a6578fd') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2245', 'సామెతలమాల', 'జ్ఞానమాల', 'ఎద్దు కేమి తెలుసు అటుకుల రుచి?', '', '"ఎ" అక్షరం', '', NULL, 'c87b9ef25c6c7c8689ea276842daf539664771212f2b748caa5f133c4e951d34') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2246', 'సామెతలమాల', 'జ్ఞానమాల', 'ఎద్దు పుండు కాకికి ముద్దు', '', '"ఎ" అక్షరం', '', NULL, '7988c2657f899529511b3fefed178e0f5bdcac28491c5ecdd6c5a94caa2eee00') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2247', 'సామెతలమాల', 'జ్ఞానమాల', 'ఎద్దుగా ఏడాది బతకడం కంటే ఆంబోతుగా ఆర్నెల్లు బతకడం మేలు', '', '"ఎ" అక్షరం', '', NULL, '9c73e90da92397770cc7fcd10807fb3848b626e1ff5c6c413989a272334841ba') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2248', 'సామెతలమాల', 'జ్ఞానమాల', 'ఎద్దుగా ఏడాది బతికే కంటే ఆబోతుగా ఆరునెలలు బతికినా చాలు', '', '"ఎ" అక్షరం', '', NULL, '99dcd8282fe2342da4b2c2d2aa8726883bb37149df37250cdb7184403af7c48f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2249', 'సామెతలమాల', 'జ్ఞానమాల', 'ఎలుక తోక తెచ్చి ఎన్నినాళ్ళు ఉతికినా నలుపు నలుపే కానీ తెలుపు కాదు', '', '"ఎ" అక్షరం', '', NULL, '4842e5595463ff2c2da888f6982b18a89f9d0daf84b0bc96862336be4bfa5093') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2250', 'సామెతలమాల', 'జ్ఞానమాల', 'ఎలుకలున్నాయని ఇల్లు తగలబెట్టినట్లు', '', '"ఎ" అక్షరం', '', NULL, '3fce22d3a7e44c2d7bd9eaf33d9039a26a766ed3107ec550e197c9faa85e3874') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2251', 'సామెతలమాల', 'జ్ఞానమాల', 'ఎవడి బ్లాగుకు వాడే సుమన్ అని', '', '"ఎ" అక్షరం', '', NULL, 'a0773910a32001c8777dd0cc5e6b7576eb84d0e8235b69873a45917cd20a5837') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2252', 'సామెతలమాల', 'జ్ఞానమాల', 'ఎరువు సొమ్ము బరువు చేటు', '', '"ఎ" అక్షరం', '', NULL, 'ee660fdcf45d5fc82ebb786b70c7029e2bb08d322e55739515a3105bf4691fa4') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2253', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏ', '', '"ఏ" అక్షరం', '', NULL, '8359357ae1bf4cde547d6a7223ecbf8c2bdc4c95bab97a437c48a8446d6b0f66') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2254', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏకులా వచ్చి మేకులా తగులుకున్నట్టు', '', '"ఏ" అక్షరం', '', NULL, '8a216739f8c73b473c0fefc15655535c78f5b61f4c53c0543b50af7a7a8ae784') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2255', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏ మొగుడు దొరక్కుంటే అక్క మొగుడే దిక్కన్నట్లు', '', '"ఏ" అక్షరం', '', NULL, '0015ea351fe83994e02a6dfda18f90b2ecf38a59599d0795058e178e4cbe1df3') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2256', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏ ఎండకి ఆ గొడుగు పట్టాలన్నట్లు', '', '"ఏ" అక్షరం', '', NULL, '103afc098f3c7dad0c5e8e1c789b6fc1bfcc6dd83399193e24fe8fad7d9da7d8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2257', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏ చెట్టూ లేని చోట, ఆముదం చెట్టే మహా వృక్షము', '', '"ఏ" అక్షరం', '', NULL, 'ce39ee46f3a06018e4abddc283768de8c6bef4c5291546d55689461fd8fc4e37') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2258', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏటి ఇసుక ఎంచలేం తాటి మాను తన్నలేం, ఈత మాను విరచలేం', '', '"ఏ" అక్షరం', '', NULL, '43069a610d5d3b5813f1a59000eddda65af67dfae1389e8c7e4ce4b7c9e5298b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2259', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏడ్చే మగాడిని నవ్వే ఆడదాన్ని నమ్మరాదు', '', '"ఏ" అక్షరం', '', NULL, 'b71aad73167e37f6bd9a75ce2090cfea302395b63aedb6d47650a6615f6d9203') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2260', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏడ్చే వాడికి ఎడమ పక్కన, కుట్టే వాడికి కుడి పక్కన కూర్చున్నట్లు', '', '"ఏ" అక్షరం', '', NULL, 'c3913f287edec22078e79c76ff66a08562f7766d98d30930c3e46f0ad331b8e7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2261', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏదుం తిన్నా ఏకాసే, పందుం తిన్నా పరగడుపే', '', '"ఏ" అక్షరం', '', NULL, '77ab8589e3af169fbe9ec47f84c2e443147fbc04c7df8e991d4c15dd1ef887c8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2262', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏనుగుల్ని తినే స్వాములోరికి పచ్చ గడ్డి పలహారం అన్నట్లు', '', '"ఏ" అక్షరం', '', NULL, '4b007650373b64cb3c50a1e49e1e357e0aba1726bca629b821eb73b6315a1afc') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2263', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏనుగులు మింగేవాడికి పీనుగల పిండాకూడు', '', '"ఏ" అక్షరం', '', NULL, 'c432da17fb414421539794272c9c9e060913028b316e908ae6e7d5168ffd181b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2264', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏనుగు చచ్చినా బ్రతికినా వెయ్యే', '', '"ఏ" అక్షరం', '', NULL, '11f56893c8eaaefe779de93a0513b19ef7ab4f74b4a49e66634c9e3910946963') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2265', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏనుగు నెత్తి మీద ఏనుగే మన్ను పోసుకున్నట్లు', '', '"ఏ" అక్షరం', '', NULL, 'd0979b62891fc0cf7fb88264242d50342dc2ae2c2b4ec1dbdad885f9bc11dfcb') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2266', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏనుగులు పడితే ఏనుగులే లేపాలి కాని పీనుగుల వల్ల కాదు', '', '"ఏ" అక్షరం', '', NULL, 'a3b948e871403877f6cb5aef569ccc770e91d85fa1f76a8a066dc02aa713100c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2267', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏమండీ కరణం గారూపాతర లో పడ్డారే అంటే, కాదు మషాకత్తు చేస్తున్నాను అన్నాడట', '', '"ఏ" అక్షరం', '', NULL, '306f55901599b3faf08fbec5b9b654775932e28e5fd3d3c31894ac37ad216317') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2268', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏమీ లేని విస్తరాకు ఎగిరెగిరి పడుతుంది,అన్నీ ఉన్న ఆకు అణిగిమణిగి ఉంటుందని', '', '"ఏ" అక్షరం', '', NULL, '2653dbf0409c0999f4b73bc382df4010a0a70d72e4a5d3f8c20679b8a2b21307') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2269', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏరు ఏడామడ ఉండగానే చీర విప్పి చంకన బెట్టుకొందట', '', '"ఏ" అక్షరం', '', NULL, '69349bdd7bbda392480ea6c0a3acc92c165c3e399d8430727c412ca656b2dbb1') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2270', 'సామెతలమాల', 'జ్ఞానమాల', 'ఏరు దాటిన తరువాత తెప్ప తగలేసినట్లు', '', '"ఏ" అక్షరం', '', NULL, '91b9df42b6a72dc2e6004d201209637995b5a5dbf232e94b8c143609ac2205fe') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
