INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2275', 'సామెతలమాల', 'జ్ఞానమాల', 'ఒల్లని భార్య చేయి తగిలినను ముప్పే, కాలు తగిలినను తప్పే', '', '"ఒ" అక్షరం', '', NULL, 'bf6cff8c7cef9bb5aaf3654c6f8493e1faea5e981dd999f5175733d9dffdc0a5') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
