INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2297', 'సామెతలమాల', 'జ్ఞానమాల', 'అంగడి వీధిలో అబ్బా! అంటే, ఎవడికి పుట్టేవురా కొడుకా? అన్నట్లు', '', '"అం" అక్షరం', '', NULL, '28d6f136a3e42042a817ba4c529cc51b9c8b2e0949ea33d3aceb192e2859cf03') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2298', 'సామెతలమాల', 'జ్ఞానమాల', 'అంగడినుంచి తెచ్చే ముందర పెట్టుక ఏడ్చే', '', '"అం" అక్షరం', '', NULL, 'b1188d8e0c5886e5ceecafa91821a314c21a2dbd1c9f797a1a8afc58dd5ecce7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2299', 'సామెతలమాల', 'జ్ఞానమాల', 'అంచు డాబే కాని, పంచె డాబు లేదు', '', '"అం" అక్షరం', '', NULL, '9f074b875e67bdd4475723fc9d7110a221b97f771f46ee71b55cfd48787ed68d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2300', 'సామెతలమాల', 'జ్ఞానమాల', 'అంటుకోను ఆముదం లేదుకాని,మీసాలకు సంపెంగ నూనె.', '', '"అం" అక్షరం', '', NULL, '061b721d51d951b738e0bdf69b309454300678e7126fc0510044885921622e48') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2301', 'సామెతలమాల', 'జ్ఞానమాల', 'అంత పెద్ద పుస్తకం చంకలోవుంటే, పంచాంగం చెప్పలేవా అన్నట్లు.', '', '"అం" అక్షరం', '', NULL, '81236a795c458cc66725903fdf241728cb5acf77e4e35817c166c3420aefee6d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2302', 'సామెతలమాల', 'జ్ఞానమాల', 'అంతంత కోడికి అర్థశేరు మసాలా.', '', '"అం" అక్షరం', '', NULL, 'd1bfc888bfdb23e78ebfb0cd7d995e39a9d647e03dce25a8d9603c253cb24e84') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2303', 'సామెతలమాల', 'జ్ఞానమాల', 'అంతనాడు లేదు, ఇంతనాడు లేదు, సంతనాడు కట్టింది ముంతాత కొప్పు', '', '"అం" అక్షరం', '', NULL, '440cb28f9ed79e77b8ed458ab65d7161a94a4aace6869d1e17b08ef0e6fe2041') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2304', 'సామెతలమాల', 'జ్ఞానమాల', 'అంత ఉరుము ఉరుమి ఇంతేనా కురిసింది అన్నట్లు', '', '"అం" అక్షరం', '', NULL, 'e0af4b9686488b039fedeb3cb184f4dfbefc9600310c3e338d51c8b91f77d9ef') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
