INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2306', 'సామెతలమాల', 'జ్ఞానమాల', 'అంత్య నిష్ఠూరం కన్నా, ఆది నిష్ఠూరం మేలు.', '', '"అం" అక్షరం', '', NULL, '78d51e7ef7a2b5899b8ee7829b897d2f1e75044f60653444c32cf087ee238c96') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
