INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2320', 'సామెతలమాల', 'జ్ఞానమాల', 'కంచానికి ఒక్కడు - మంచానికి ఇద్దరు', '', '"క" అక్షరం', '', NULL, '7e7b5afefb39746a1b7299e7b9ccb36708c9a8937412f65ca7c3acf847c86592') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
