INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2507', 'సామెతలమాల', 'జ్ఞానమాల', 'తడిగుడ్డలతో గొంతులు తెగకోస్తాడు', '', '"త" అక్షరం', '', NULL, '03935d2c3e4ea3436023b30fd1d35ff774eb5c81d4e3555887d3ed5fe60687c5') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2508', 'సామెతలమాల', 'జ్ఞానమాల', 'తడిశిగాని గుడిశె కట్టడు, తాకిగానీ మొగ్గడు', '', '"త" అక్షరం', '', NULL, '6183f8effff92e0734a99c529c23cfb44133676c84bdb4e7d8ccfc187a95b729') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2509', 'సామెతలమాల', 'జ్ఞానమాల', 'తడిశిన కుక్కి బిగిశినట్టు', '', '"త" అక్షరం', '', NULL, '0c7cee8cdf951e03729ba7e0c32edd58c54716777a3f17d199bc65ea3ffc9100') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2510', 'సామెతలమాల', 'జ్ఞానమాల', 'తడిశి ముప్పందుం మోశినట్టు', '', '"త" అక్షరం', '', NULL, '25327e5c12be6032d87ac5fcce05e83d137acb7325be79eb5091995b3d335f45') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2511', 'సామెతలమాల', 'జ్ఞానమాల', 'తణుకుకు పోయి మాచవరం వెళ్ళినట్లు', '', '"త" అక్షరం', '', NULL, '50589031de6b9f9e71dce1711e1022489a353e6832eca99edfca7146e45bc8b8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2512', 'సామెతలమాల', 'జ్ఞానమాల', 'తద్దినము కొని తెచ్చుకొన్నట్టు', '', '"త" అక్షరం', '', NULL, 'f5c3c7594f7a0c75f25672cab67335a3fb1a7678c4c31a387ee3cf8f2ad20bda') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2513', 'సామెతలమాల', 'జ్ఞానమాల', 'తనకంపు తనకింపు, పరులకంపు తనకు వొకిలింపు', '', '"త" అక్షరం', '', NULL, '992c811fcc126ef6d3e43a233b00d6b6be3afbb03c46355e504a62e0cca22e89') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2514', 'సామెతలమాల', 'జ్ఞానమాల', 'తన కలిమి ఇంద్రబోగము, తనలేమి లోకదారిద్ర్యము', '', '"త" అక్షరం', '', NULL, '59f087e307fd5101ecdb7dc90f46a8e803d617345d667af9745471f44496e73c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2515', 'సామెతలమాల', 'జ్ఞానమాల', 'తన కాళ్లకు బంధాలు తానే తెచ్చుకొన్నట్టు', '', '"త" అక్షరం', '', NULL, '709eab04bcd37f3b87468f95b377c48f1c99627f70b1cc8f8b7c32289fee242b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2516', 'సామెతలమాల', 'జ్ఞానమాల', 'తనకు అని తవ్వెడు తవుడు వుంటే, ఆకటి వేళకు ఆరగించవచ్చును', '', '"త" అక్షరం', '', NULL, 'd263d7774f47da803af9f5493268b9d37882c7d94488fc6eab060cf46825674f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2517', 'సామెతలమాల', 'జ్ఞానమాల', 'తనకు కానిది గూడులంజ', '', '"త" అక్షరం', '', NULL, '08bb43f914fc5b75b7067af4997a75e5a662f08b17d9905c1f5770655548bae0') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2518', 'సామెతలమాల', 'జ్ఞానమాల', 'తగువెలా వస్తుంది జంగందేవరా అంటే బిచ్చం పెట్టవే బొచ్చుముండ అన్నాడుట', '', '"త" అక్షరం', '', NULL, 'acc3a6fdf86034b0b58a42ff3110d5c6d1478f898d0cf0169caf05265c3c5237') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2519', 'సామెతలమాల', 'జ్ఞానమాల', 'తడి గుడ్డతో గొంతులు కొయ్యడం', '', '"త" అక్షరం', '', NULL, 'd5ed8fad0e0a568746b94daa0d1f9b56dcd9cd877765edb1b5f2d06d56deda3d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2520', 'సామెతలమాల', 'జ్ఞానమాల', 'తండ్రికి తిండి లేక తవుడు తింటుంటే కొడుకొచ్చి కోవాబిళ్ళ కావాలన్నాడట', '', '"త" అక్షరం', '', NULL, '3e528ad8888018e24326665b06df72daa1d6467348f0db766118f988d2de9934') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2521', 'సామెతలమాల', 'జ్ఞానమాల', 'తంతే బూరెల బుట్టలో పడ్డట్టు', '', '"త" అక్షరం', '', NULL, '3bca4bd0e3d6e408aebbb4c68a952748d28b2a463859c0fb78d7be5e5fec5b3c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2522', 'సామెతలమాల', 'జ్ఞానమాల', 'తనది కాకపోతే కాశీదాకా దేకమన్నాడట', '', '"త" అక్షరం', '', NULL, 'e17f890ce017b1d25668ce2cc362c6adf35903efb17924ccf8f54780b05c585f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2523', 'సామెతలమాల', 'జ్ఞానమాల', 'తమలపాకుతో నీవొకటిస్తే తలుపు చెక్కతో నేనొకటిస్తా', '', '"త" అక్షరం', '', NULL, '6dc995c9021500b0008f6ce12189ffda91fd530c7cc57cabb21684f026155d74') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2524', 'సామెతలమాల', 'జ్ఞానమాల', 'తమ్ముడు తమ్ముడే పేకాట పేకాటే', '', '"త" అక్షరం', '', NULL, '8557b32bc124fd173971e7749f25dd4a621bb63944b9f584c2f3458a5da2fa4b') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2525', 'సామెతలమాల', 'జ్ఞానమాల', 'తల లేదు కానీ చేతులున్నాయి... కాళ్లు లేవు కానీ కాయం ఉంది?', '', '"త" అక్షరం', '', NULL, 'fedaf0a7da04dadf0f35a355ff1f022b1d45cf990201309623e64f0dfec6d2d7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2526', 'సామెతలమాల', 'జ్ఞానమాల', 'తల ప్రాణం తోకకి వచ్చినట్లు', '', '"త" అక్షరం', '', NULL, 'd72bf6ca69fd1fd8190e72f817949a73ef4592c34c48906e139228f16fc79bc8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2527', 'సామెతలమాల', 'జ్ఞానమాల', 'తలనుంచి పొగలు చిమ్ముచుండు భూతము కాదు, కనులెర్రగనుండు రాకాసి కాదు, పాకిపోవుచుండు పాముకాదు', '', '"త" అక్షరం', '', NULL, 'e1272ee264c50d5fb866b59a3928cc064abe420ed587a871828327b565136fc5') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2528', 'సామెతలమాల', 'జ్ఞానమాల', 'తల్లి కడుపు చూస్తుంది, పెళ్ళాం జేబు చూస్తుంది', '', '"త" అక్షరం', '', NULL, 'ad97b40a36adccef7214cb0e845a39f0409760e9092d2a0e2153757dfe19dbc8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2529', 'సామెతలమాల', 'జ్ఞానమాల', 'తవుడు తింటూ వయ్యారమా?', '', '"త" అక్షరం', '', NULL, 'b699c572dd27b5688917b87f1ea3a4cbba0df1427f7e293b5a8a395974c65481') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2530', 'సామెతలమాల', 'జ్ఞానమాల', 'తాను వలచినది రంభ, తాను మునిగింది గంగ', '', '"త" అక్షరం', '', NULL, '4434e7811f436d2239a4f8033002a8ba5a8d6868a589defabd63dcf87e8f0c7e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2531', 'సామెతలమాల', 'జ్ఞానమాల', 'తా(ను) పట్టిన కుందేటికి మూడే కాళ్లు', '', '"త" అక్షరం', '', NULL, '593632172fbc83a126a01da24a1e3528e1df96420ae525813a5133c2356a0367') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2532', 'సామెతలమాల', 'జ్ఞానమాల', 'తానొకటి తలిస్తే దైవమొకటి తలిచాడట', '', '"త" అక్షరం', '', NULL, '3a43f0903d9688b392ecdbd6252660c8b1c2919f1735fdb026ee3ec2fce3cde6') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
