INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2645', 'సామెతలమాల', 'జ్ఞానమాల', 'పట్టుకోక ఇచ్చినమ్మ పీటకోడు పట్టుకు తిరిగిందంట', '', '"ప" అక్షరం', '', NULL, '1f15406850eb98234894dbc6d8dbc3ddc2b3759a034dd20ef68b6608a09e5624') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2646', 'సామెతలమాల', 'జ్ఞానమాల', 'పని లేని మంగలి పిలిచి తల గొరిగినట్లు', '', '"ప" అక్షరం', '', NULL, '3e21f8ff7ad49e91d40266d12092a9bda450012608c2e1472841bb462a468ff8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
