INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2651', 'సామెతలమాల', 'జ్ఞానమాల', 'పల్లాన పండింది; మెరకన ఎండింది; వాడికుప్ప కాలింది; వాడి అప్పుతీరింది. అయితే ఎవరు వాడు?', '', '"ప" అక్షరం', '', NULL, '45e1e3ed700a32b3995fc71f3b16fb77cbc0537487879302956f7d31ad8c16dd') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
