INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2718', 'సామెతలమాల', 'జ్ఞానమాల', 'మంచోడు, మంచోడు అంటే, మంచమెక్కి తూలుతున్నడు', '', '"మ" అక్షరం', '', NULL, '90cde32f6e536d4df6c6ed0640b3f1751a96be71882b82535ae5663ed5498a18') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2719', 'సామెతలమాల', 'జ్ఞానమాల', 'మంచోళ్ళకు మాటలతోను, మొండోళ్ళకు మొట్టికాయ వేసి చెప్పాలి', '', '"మ" అక్షరం', '', NULL, 'bd0f67b30d972555fa6c5375e68cf7b284844dc7419919eb5619bcfe40d27d2d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2720', 'సామెతలమాల', 'జ్ఞానమాల', 'మంత్రాలకు చింతకాయలు రాలుతాయా?', '', '"మ" అక్షరం', '', NULL, '85337b724ab0049cfcf011163e20af0d72bc47349fccfe6b397f73cc2f995d93') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2721', 'సామెతలమాల', 'జ్ఞానమాల', 'మందెక్కువైతే, మజ్జిగ పల్చనవుతుంది', '', '"మ" అక్షరం', '', NULL, '2e7e7e0ea2a00927ebec288ee8c1e5384b0459be6c2eef9e4ba7a2dda9371902') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2722', 'సామెతలమాల', 'జ్ఞానమాల', 'మజ్జిగకి గతిలేనివాడు పెరుగుకి చీటీ రాసేడంట', '', '"మ" అక్షరం', '', NULL, '9826949c3e53294584fbe6c3e66518d4bfcb6f519c97e35e165b222986a79a7c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2723', 'సామెతలమాల', 'జ్ఞానమాల', 'మన బంగారం మంచిదైతే ఊళ్ళో వాళ్ళని అనుకోవడం దేనికి?', '', '"మ" అక్షరం', '', NULL, '0c160338a3d22bad07f28708e3a9081498ddce521f637aaa473217f5aa612948') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2724', 'సామెతలమాల', 'జ్ఞానమాల', 'మనిషి మర్మం, మాను చేవ బైటికి తెలియవు', '', '"మ" అక్షరం', '', NULL, '54607a092085ab730fac6ba20714f5c42499f840ab910a8bead60efd8f8fbf82') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2725', 'సామెతలమాల', 'జ్ఞానమాల', 'మంచి మనిషికొక మాట మంచి గొడ్డుకొక దెబ్బ', '', '"మ" అక్షరం', '', NULL, 'b9a25203ebca1af1105eac35539b78118f2b9e4b9272adcd3a6bb3b6b72a4365') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2726', 'సామెతలమాల', 'జ్ఞానమాల', 'మందుకని పంపిస్తే మాసికం నాటికి వచ్చే రకం', '', '"మ" అక్షరం', '', NULL, 'fab02e1eb9686ec225d607efdfe1caf208225fad2b13024a797788580208c591') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2727', 'సామెతలమాల', 'జ్ఞానమాల', 'మబ్బుల్లో నీళ్ళు చూసి ముంత వలక బోసుకున్నట్లు', '', '"మ" అక్షరం', '', NULL, '78fd4c2569b89c4c5f72944643c68a708d158356b8d55d3893d4bf656ad4aecf') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2728', 'సామెతలమాల', 'జ్ఞానమాల', 'మా తాతలు నేతులు తాగారు, మా మూతులు వాసన చూడమన్నట్లు', '', '"మ" అక్షరం', '', NULL, 'ba822ab565e48ded98158ed3b25c941f272a111d8c6d60df840872d6bbb9a6c8') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2729', 'సామెతలమాల', 'జ్ఞానమాల', 'మా బావ బజారుకెళ్ళి తొడిమెలేని వంకాయ తెచ్చాడు', '', '"మ" అక్షరం', '', NULL, 'fa01604023710befdea3cf0251dc296ec0297dd0642186099f44b3279d83b1e4') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2730', 'సామెతలమాల', 'జ్ఞానమాల', 'మాటకు మా ఇంటికి... కూటికి మీ ఇంటికి అన్నట్లు', '', '"మ" అక్షరం', '', NULL, '413961075e3ddba50da1d7e24bf336208e8672ae487326444d3d7d5fe1a2b772') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2731', 'సామెతలమాల', 'జ్ఞానమాల', 'మాటలు కోటలు దాటుతాయి కాని కాళ్ళు గడప దాటనట్లు', '', '"మ" అక్షరం', '', NULL, '43ff0c2e009450c76e119b41c0092515e4bffd09e0abceec5bb6b859516d86b3') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2732', 'సామెతలమాల', 'జ్ఞానమాల', 'మింగ మెతుకు లేదు మీసాలకి సంపెంగ నూనె', '', '"మ" అక్షరం', '', NULL, 'd8ac626fb8ffb4babc04a5938650b43cb3cf78f17ecf95ae133b5a2ea1bc16e2') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2733', 'సామెతలమాల', 'జ్ఞానమాల', 'మింగ లేక మంగళవారం అన్నాడట', '', '"మ" అక్షరం', '', NULL, '61d6906fdb050898e45243052a03cf791ac9242f7003249ffb33bff3b82c4159') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
