INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2744', 'సామెతలమాల', 'జ్ఞానమాల', 'మూతి కాలినా కుంపటే ముద్దు అన్నట్లు', '', '"మ" అక్షరం', '', NULL, 'e8285671ea6b31f20f194bf3725c4dfb429ee1dd6417119ce4ed7249a38a8f43') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2745', 'సామెతలమాల', 'జ్ఞానమాల', 'మూల విగ్రహానికే ఈగలు దోలుతుంటే,.. ఉత్సవ విగ్రహం వచ్చి ఊరేగింపు ఎప్పుడని అడిగినట్టు', '', '"మ" అక్షరం', '', NULL, 'b430d8e262acd2bf904268a12c3638ba8eeffe4be18a8fc852b54fc40e9a77fd') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2746', 'సామెతలమాల', 'జ్ఞానమాల', 'మూరెడు పొంగటం ఎందుకు బారెడు కుంగటం ఎందుకు?', '', '"మ" అక్షరం', '', NULL, '953c347571a9e0e15ab7ee80555d13e976bed7d93f6bb4dc9eb827b7e422f45f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2747', 'సామెతలమాల', 'జ్ఞానమాల', 'మూలిగే నక్కపై తాటిపండు పడ్డట్టు', '', '"మ" అక్షరం', '', NULL, '7dab1a85e2bf2a5f3337c018558eedf183041a3001b7e46c07326051ab87dac7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2748', 'సామెతలమాల', 'జ్ఞానమాల', 'మొండివాడు రాజు కన్నా బలవంతుడు', '', '"మ" అక్షరం', '', NULL, 'a2ca3f28ceb554aec7824413bb16eb6ff2a367f137b7b69feb3dd513a504dbf5') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2749', 'సామెతలమాల', 'జ్ఞానమాల', 'మొక్కయి వంగనిది, మానయ్యాక వంగునా?', '', '"మ" అక్షరం', '', NULL, 'f118eaa715fa9b07b740aaa462459e3798692011d95cbf76567fbc2245312321') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2750', 'సామెతలమాల', 'జ్ఞానమాల', 'మొగుడు కొట్టినందుకు కాదు బాధ, తోటి కోడలు నవ్వినందుకు', '', '"మ" అక్షరం', '', NULL, '4f2398f948a521f4131d47bf11d5e40afc2ddf23de5b6e7ef136f3690a780ba9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2751', 'సామెతలమాల', 'జ్ఞానమాల', 'మొగుడు పోయి తానేడుస్తుంటే మిండమొగుడు రమ్మని రాళ్ళేశాడంట', '', '"మ" అక్షరం', '', NULL, 'c9cda6d501e4c5357c6800b236d11a20db8ddac0fccddd66ce960348518d03a2') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2752', 'సామెతలమాల', 'జ్ఞానమాల', 'మొగుణ్ణి కొట్టి మొగసాల కెక్కినట్టు', '', '"మ" అక్షరం', '', NULL, 'e57dd40adfd36e6d0930e5f71d35bd130753646e928d3a353597e1487ddadbc7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2753', 'సామెతలమాల', 'జ్ఞానమాల', 'మొదులు లేదు మొగుడా అంటే పెసర పప్పు లేదే పెళ్ళామా అన్నట్లు', '', '"మ" అక్షరం', '', NULL, 'b464c53af6575e56f6ceb69a78276761a1017680aa567e56f31c22fb7cb74602') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2754', 'సామెతలమాల', 'జ్ఞానమాల', 'మొరటోడికి మల్లెపూలు ఇస్తే మడిచి యాడనో పెట్టుకున్నాడంట', '', '"మ" అక్షరం', '', NULL, '4310102dd6e8e867321b2b39c1210beee0cb07b3441c778625aadae788288eee') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
