INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2756', 'సామెతలమాల', 'జ్ఞానమాల', 'మోకాలుకీ బోడి గుండుకు ముడి వేసినట్టు', '', '"మ" అక్షరం', '', NULL, 'af2e14a403657b725c4b1ddf20c81c6e27b065de615eefec37d48bf97e50e478') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
