INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2759', 'సామెతలమాల', 'జ్ఞానమాల', 'మొదటి దానికి మొగుడు లేడు కాని, కడదానికి కళ్యాణము అన్నట్లు', '', '"మ" అక్షరం', '', NULL, 'e52b0c4c0d5d6096e806a47d8e18a9f5200571c88f1f393db884b59ca147e712') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2760', 'సామెతలమాల', 'జ్ఞానమాల', 'ముహూర్తం చూసుకుని యాత్రకు బయల్దేరితే ముందరి మొగుడు ఎదురు వచ్చాడట', '', '"మ" అక్షరం', '', NULL, '1deadf7a2f9ea58e0be28d956c5119d50fa094c01eff5e39dc88352404e58ce0') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
