INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2763', 'సామెతలమాల', 'జ్ఞానమాల', 'రాజ్యాలు పోయినా కిరీటాలు వదల్లేదని.....', '', '"ర" అక్షరం', '', NULL, '4265753ed58fcaf9fa2bf0957e97ae5ca870f3a4bf341ff2a5f9b3f5b2f74b5f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2764', 'సామెతలమాల', 'జ్ఞానమాల', 'రాజు తలచుకొంటే దెబ్బలకు కొదవా?', '', '"ర" అక్షరం', '', NULL, 'fb21f0bcb9afd0a632d53ae6bceb6fe0dbb00e7ef17680b93de148c2c773f9b6') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2765', 'సామెతలమాల', 'జ్ఞానమాల', 'రాజుని చూసిన కంటితో మొగుడిని చూస్తే, మొత్తబుద్ది అవుతుంది', '', '"ర" అక్షరం', '', NULL, '4155665c8a260b06aec807493de9de9c8268638be3521e5db8f9de29a4143717') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2766', 'సామెతలమాల', 'జ్ఞానమాల', 'రాజుల సొమ్ము రాళ్ళ పాలు,దొరల సొమ్ము దొంగల పాలు', '', '"ర" అక్షరం', '', NULL, '8403771e1fb73239d473b61286644c48bd24597fa8f76a4e191ec6e268974ff9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
