INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2868', 'సంధిమాల', 'జ్ఞానమాల', 'సురారులు', 'సుర + అరులు → సురారులు
సూత్రం: అ / ఇ / ఉ / ఋ + సవర్ణ అచ్చు → దీర్ఘం', 'సవర్ణదీర్ఘ సంధి (స్వర సంధి)', 'అ, ఇ, ఉ, ఋ లకు సవర్ణములగు అచ్చులు పరమైనపుడు వాని దీర్ఘములు ఏకాదేశంబగును', NULL, 'c9a73dffaf9e6f2af2f6ab7d769498584c73dabdd6683003bbc039a7128c9b50') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
