INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2875', 'సంధిమాల', 'జ్ఞానమాల', 'అత్యంత', 'అతి + అంత → అత్యంత
సూత్రం: ఇ / ఉ / ఋ + అసవర్ణ అచ్చు → య / వ / ర', 'యణాదేశ సంధి (స్వర సంధి)', 'ఇ,ఉ,ఋ లకు అసవర్ణములగు అచ్చులు పరమగునపుడు వరుసగా య,వ,ర లు ఆదేశముగా వచ్చెను', NULL, '13fc30b93573d05bb05b803e2921c016bcd37a0af148be2a6c432289a5352ddf') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
