INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2885', 'సంధిమాల', 'జ్ఞానమాల', 'వేనుడనంగ', 'వేనుడు + అనంగ → వేనుడనంగ
సూత్రం: ఉ + అచ్చు → నిత్యం', 'ఉకార సంధి (తెలుగు సంధి)', 'ఉత్తున కచ్చు పరంబగునపుడు సంధి యగు (నిత్యము)', NULL, 'bb2e9b096ba03632838ba5331a74f8e42658452597035ce2ce994f303e92d4cc') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2886', 'సంధిమాల', 'జ్ఞానమాల', 'మాయమ్మ', 'మా + అమ్మ → మాయమ్మ
సూత్రం: అచ్చు + అచ్చు → య్ ఆగమం', 'యడాగమ సంధి (ఆగమ సంధి)', 'సంధిలేని చోట స్వరంబుకంటే పరంబయిన స్వరంబునకు యడాగమంబగు', NULL, '139bf99899f1e38f6d92d0e1f66933b77e0c271d98a2d44b180c4202387240ea') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2887', 'సంధిమాల', 'జ్ఞానమాల', 'ఏమేమి', 'ఏమి + ఏమి → ఏమేమి
సూత్రం: అచ్చు + ఆమ్రేడితం → సంధి', 'ఆమ్రేడిత సంధి (తెలుగు సంధి)', 'అచ్చునకు ఆమ్రేడితము పరమగునపుడు సంధి తరచుగానగును', NULL, '70c3d350082469b02446c7340220d8d7eeaa82440ce3f566da61c7053135f29c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2888', 'సంధిమాల', 'జ్ఞానమాల', 'అత్తెఱంగు', 'ఆ + తెఱంగు → అత్తెఱంగు
సూత్రం: ఆ / ఈ / ఏ + అసంయుక్త హల్లు → ద్విత్వం', 'త్రిక సంధి (తెలుగు సంధి)', 'ఆ,ఈ,ఏ సర్వనామములకు (త్రికము) మీది హల్లు పరమైన ద్విత్వంబు బహుళంగా వస్తుంది', NULL, '99ae1cdb48b1e3d10d50cf77135ce4da5f2dfd747470eddddd10f1ab75a9b7e7') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2889', 'సంధిమాల', 'జ్ఞానమాల', 'ఎచ్చోటు', 'ఏ + చోటు → ఎచ్చోటు
సూత్రం: ఆ / ఈ / ఏ + అసంయుక్త హల్లు → ద్విత్వం', 'త్రిక సంధి (తెలుగు సంధి)', 'ఆ,ఈ,ఏ సర్వనామములకు (త్రికము) మీది హల్లు పరమైన ద్విత్వంబు బహుళంగా వస్తుంది', NULL, '015ec599c3865dde6716f8128e3062d40880869344b803aff80c9cdf3c2cba57') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2890', 'సంధిమాల', 'జ్ఞానమాల', 'రాముఁడుఁదాను', 'రాముఁడు + తాను → రాముఁడుఁదాను
సూత్రం: ప్రథమ విభక్తి + క / చ / ట / త / ప → గ / స / డ / ద / వ', 'గసడదవాదేశ సంధి (తెలుగు సంధి)', 'ప్రథమము మీది పరుషములకు గ,స,డ,ద,వ లు బహుళములగును', NULL, '21d37c958502e4d6fb919fea1594daf3529c48b8dd62134148c899ef68921f8d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2891', 'సంధిమాల', 'జ్ఞానమాల', 'వాటపుమాట', 'వాటము + మాట → వాటపుమాట
సూత్రం: సువర్ణం + కర్మధారయం → పుంపు', 'పుంప్వాదేశ సంధి (సమాస సంధి)', 'కర్మధారయ సమాసమున సువర్ణమునకు పుంపు లగును', NULL, '349d2978a441e1b5377a346af754318027bd06238c6594294888433a38e41dfd') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2892', 'సంధిమాల', 'జ్ఞానమాల', 'పేదరాలు', 'పేద + ఆలు → పేదరాలు
సూత్రం: పేద / ముద్దు + ఆలు → ర ఆగమం', 'రుగాగమ సంధి (ఆగమ సంధి)', 'పేదాదుల కాలు పరమయినపుడు రగాగము వచ్చును', NULL, '015b4748eb4a3a39248e270dfffdd2fae07e0d960ecbe966ad4919ff06bc766c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2893', 'సంధిమాల', 'జ్ఞానమాల', 'ముద్దరాలు', 'ముద్దు + ఆలు → ముద్దరాలు
సూత్రం: పేద / ముద్దు + ఆలు → ర ఆగమం', 'రుగాగమ సంధి (ఆగమ సంధి)', 'పేదాదుల కాలు పరమయినపుడు రగాగము వచ్చును', NULL, 'f3c411083fc917c7c2d4b9adfd3cc4570b00eb62b0c3aff706b335669cfe49dc') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2894', 'సంధిమాల', 'జ్ఞానమాల', 'భయపడి', 'భయము + పడి → భయపడి
సూత్రం: సువర్ణం + పడ్వాది → లోపం / బిందువు', 'పడ్వాది సంధి (తెలుగు సంధి)', 'పడ్వాదులు పరమగునపుడు సువర్ణమునకు లోప పూర్ణబిందువులు వికల్పములగును', NULL, 'c0c815513834fabe96e8b33cc605c3df78b6e322863f07f1d2ac355fca2006fc') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2895', 'సంధిమాల', 'జ్ఞానమాల', 'చిగురుటాకు', 'చిగురు + ఆకు → చిగురుటాకు
సూత్రం: ఉ-కారాంతం + అచ్చు → ట ఆగమం', 'టుగాగమ సంధి (ఆగమ సంధి)', 'కర్మధారయ సమాసమునందు ఉకారాంత పదమునకు అచ్చు పరమైనపుడు టుగాగమంబగు', NULL, '1c9bf26f1aa4ed7770db7b8c37831a163d80021ac48c53aaee73ea0bad9be35c') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2896', 'సంధిమాల', 'జ్ఞానమాల', 'చేయునతడు', 'చేయు + అతడు → చేయునతడు
సూత్రం: ఉ / ఋ కారాంతం + అచ్చు → న ఆగమం', 'నుగాగమ సంధి (ఆగమ సంధి)', 'షష్టీ తత్పురుష సమాసమునందు ఉకార ఋకారాంత శబ్దములకు అచ్చు పరమగునపుడు నుగాగమము వచ్చును', NULL, '251444b933499ee93adfdf9f609be20b156166590071b028306abf8334346284') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2897', 'సంధిమాల', 'జ్ఞానమాల', 'తెలియునప్పుడు', 'తెలియు + అప్పుడు → తెలియునప్పుడు
సూత్రం: ఉ / ఋ కారాంతం + అచ్చు → న ఆగమం', 'నుగాగమ సంధి (ఆగమ సంధి)', 'షష్టీ తత్పురుష సమాసమునందు ఉకార ఋకారాంత శబ్దములకు అచ్చు పరమగునపుడు నుగాగమము వచ్చును', NULL, '382ea95386a33ea2c5813a3427053176c2482dbbfbb10d75d34e021bf1b1a5dd') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2898', 'సంధిమాల', 'జ్ఞానమాల', 'క్రొత్తయగుచు', 'క్రొత్త + అగుచు → క్రొత్తయగుచు
సూత్రం: ప్రాతాది + ఏదైనా → లోపం', 'ప్రాతాది సంధి (తెలుగు సంధి)', 'సమాసములందు ప్రాతాదుల తొలి అచ్చుమీది వర్ణములకెల్ల లోపంబు బహుళముగానగును', NULL, '6898c674ea772d0ad02fcd3d42259905b74a45defb13e84a76ce5e6e8ae042af') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2899', 'సంధిమాల', 'జ్ఞానమాల', 'మాధుర్యమునఁదేలు', 'మాధుర్యమునన్ + తేలు → మాధుర్యమునఁదేలు
సూత్రం: ద్రుతం + పరుషం → సరళం', 'ద్రుత సంధి (తెలుగు సంధి)', 'ద్రుత ప్రకృతికముల మీద పరుషములకు సరళమగును', NULL, 'f31fcef76af8efef9bdb99485b7bcc55f7687e385a5a3af19d71ec34f2af182a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2900', 'సంధిమాల', 'జ్ఞానమాల', 'ముల్లోకములు', 'మూడు + లోకములు → ముల్లోకములు
సూత్రం: డు-వర్ణం + ఉత్తరపదం → లోపం + ద్విత్వం', 'ద్విగు సమాస సంధి (సమాస సంధి)', 'సమానాధికారణంబగు ఉత్తరపదంబు పరంబగునపుడు మూడు శబ్దములలో డు వర్ణమునకు లోపంబగును', NULL, 'd2c34fc6f50d89e5b1bc56db7a2fc08f73dfab9fa7129c9c6ba46d775bd97468') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2901', 'సంధిమాల', 'జ్ఞానమాల', 'అలరుబోడి', 'అలరు + మేను → అలరుబోడి
సూత్రం: ఉపమానం + మేను → బోడి', 'బహువ్రీహి సమాస సంధి (సమాస సంధి)', 'బహువ్రీహిని స్త్రీ వాచ్యంబునగుచో ఉపమానంబు మీది మేనునకు బోడి అగును', NULL, 'b617ea5ad208516943878614ac636584b20632c1ba8c412348a784ffbe58b860') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2902', 'సంధిమాల', 'జ్ఞానమాల', 'నాది', 'నా + అది → నాది
సూత్రం: అది / అవి + సమాసం → అ-లోపం', 'అల్లోప సంధి (తెలుగు సంధి)', 'అది, అవి శబ్దముల అకారమునకు సమాసమున లోపము బహుళముగానగు', NULL, '63e6e25764553c43cd684bc2ad273e91e817bfd7e16fd1e14a0ffaf58752008f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2903', 'సంధిమాల', 'జ్ఞానమాల', 'నీదుసుస్వరూపము', 'నీ + సుస్వరూపము → నీదుసుస్వరూపము
సూత్రం: నీ / నా / తన + ఉత్తరపదం → దు ఆగమం', 'దుగాగమ సంధి (ఆగమ సంధి)', 'నీ,నా,తన శబ్దములకు ఉత్తర పదము పరమగునపుడు దుగాగమము వికల్పముగా వచ్చును', NULL, '2f9c521f579ca0685bc982b5228d14f0e991a367e882a44b0564e18c1ebd9a55') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2904', 'సంధిమాల', 'జ్ఞానమాల', 'కుట్టుసురు', 'కుఱు + ఉసురు → కుట్టుసురు
సూత్రం: కుఱు / చిఱు / కడు / నిడు / నడు + అచ్చు → ట్ట ద్విత్వం', 'ద్విరుక్తటకార సంధి (తెలుగు సంధి)', 'కుఱు,చిఱు,కడు,నిడు,నడు శబ్దములందలి ఱ,డ లకు అచ్చు పరమగునప్పుడు ద్విరుక్త టకారంబగు', NULL, 'e3d9099270607a1c9797f29a44e2ea1a95f26062ad53fde4b0ed5e8d5cff9e8f') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2905', 'సంధిమాల', 'జ్ఞానమాల', 'చిట్టడవి', 'చిఱు + అడవి → చిట్టడవి
సూత్రం: కుఱు / చిఱు / కడు / నిడు / నడు + అచ్చు → ట్ట ద్విత్వం', 'ద్విరుక్తటకార సంధి (తెలుగు సంధి)', 'కుఱు,చిఱు,కడు,నిడు,నడు శబ్దములందలి ఱ,డ లకు అచ్చు పరమగునప్పుడు ద్విరుక్త టకారంబగు', NULL, 'e43e912d7137a9b38b5e8533a411448e4f7c3f13983c1de58e1e79d7a1fc7252') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2906', 'సంధిమాల', 'జ్ఞానమాల', 'నట్టడవి', 'నడు + అడవి → నట్టడవి
సూత్రం: కుఱు / చిఱు / కడు / నిడు / నడు + అచ్చు → ట్ట ద్విత్వం', 'ద్విరుక్తటకార సంధి (తెలుగు సంధి)', 'కుఱు,చిఱు,కడు,నిడు,నడు శబ్దములందలి ఱ,డ లకు అచ్చు పరమగునప్పుడు ద్విరుక్త టకారంబగు', NULL, '2be0a6431ec93e687a1b0b4700d1ec7a2d2cf3d370d95d9e07176d19df872d52') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2907', 'సమాసముమాల', 'జ్ఞానమాల', 'అర్ధ రాజ్యము', '= రాజ్యము యొక్క అర్ధభాగము', 'తత్పురుష సమాసము · ప్రథమా తత్పురుష', 'ఉత్తర పదార్థము ప్రధానముగా గలది తత్పురుష సమాసము. మొదటి పదము లోపించిన విభక్తి పేరు సమాసమునకు వచ్చును.', NULL, '0e0133e264fee1a8c481a7c5de0aafd7eaf179d3024cf347cac8fb657ab229e0') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2908', 'సమాసముమాల', 'జ్ఞానమాల', 'కృష్ణశ్రితుడు', '= కృష్ణుని ఆశ్రయించిన వాడు', 'తత్పురుష సమాసము · ద్వితీయా తత్పురుష', 'ఉత్తర పదార్థము ప్రధానముగా గలది తత్పురుష సమాసము. మొదటి పదము లోపించిన విభక్తి పేరు సమాసమునకు వచ్చును.', NULL, 'bf0d68110729548b6d81290042f39cd7b4935b90c594456ca5dc0355e112a174') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2909', 'సమాసముమాల', 'జ్ఞానమాల', 'గుణహీనుడు', '= గుణము చేత హీనుడు', 'తత్పురుష సమాసము · తృతీయ తత్పురుష', 'ఉత్తర పదార్థము ప్రధానముగా గలది తత్పురుష సమాసము. మొదటి పదము లోపించిన విభక్తి పేరు సమాసమునకు వచ్చును.', NULL, '1790f419926a1fa4ab2b13bd3701080a4e77fb6c400b48baa1d7d5df7d00a22e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
