INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2918', 'సమాసముమాల', 'జ్ఞానమాల', 'అజ్ఞానము', '= జ్ఞానము లేనిది', 'తత్పురుష సమాసము', 'ఉత్తర పదార్థము ప్రధానముగా గలది తత్పురుష సమాసము. మొదటి పదము లోపించిన విభక్తి పేరు సమాసమునకు వచ్చును.', NULL, '159925c7a6d37d4f6174306c4c1730bde73b679d7ce18f2ffe1086a640ddadf9') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2919', 'సమాసముమాల', 'జ్ఞానమాల', 'పెద్ద గుఱ్ఱము', '= పెద్దదైన గుఱ్ఱము', 'కర్మధారయ సమాసము · విశేషణ పూర్వపద', 'విశేషణ, విశేష్యముల తో ఏర్పడు సమాసము కర్మధారయ సమాసము. ఇది సమానాధికరణ సమాసము.', NULL, '64deb4028558b2e5d39f8c0483a6f36c482d581f6a7a6d2db3c42e1e2dd7d8f2') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2920', 'సమాసముమాల', 'జ్ఞానమాల', 'బ్రాహ్మణ వృద్ధుడు', '= వృద్ధుడైన బ్రాహ్మణుడు', 'కర్మధారయ సమాసము · విశేషణ ఉత్తరపద', 'విశేషణ, విశేష్యముల తో ఏర్పడు సమాసము కర్మధారయ సమాసము. ఇది సమానాధికరణ సమాసము.', NULL, '85b12f05a5dd587fdd554b3876906d919fb0e19bd1a333ac4c6c6860ef972015') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2921', 'సమాసముమాల', 'జ్ఞానమాల', 'చిగురు కేలు', '= చిగురువంటి కేలు', 'కర్మధారయ సమాసము · ఉపమాన పూర్వపద', 'విశేషణ, విశేష్యముల తో ఏర్పడు సమాసము కర్మధారయ సమాసము. ఇది సమానాధికరణ సమాసము.', NULL, '71280326615f2f12fdd7f26b13df7ad767c01a98ebd9afd8edf044d7fbf644f3') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
