INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2928', 'సమాసముమాల', 'జ్ఞానమాల', 'విద్యాధనము', '= విద్యయనెడి ధనము', 'కర్మధారయ సమాసము', 'విశేషణ, విశేష్యముల తో ఏర్పడు సమాసము కర్మధారయ సమాసము. ఇది సమానాధికరణ సమాసము.', NULL, '67237289b4da1eb6d54b60420929566aa20db44c317f542badd6732e3ffa2062') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
