INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2930', 'సమాసముమాల', 'జ్ఞానమాల', 'షాణ్మాతురుడు', '= ఆఱుగురు తల్లుల కొడుకు', 'ద్విగు సమాసము · తద్ధితార్థ ద్విగువు', 'సంఖ్యా వాచకపదము పూర్వమున కలది ద్విగు సమాసము. ఇందు సంఖ్య మొదటి పదముగా ఉంటుంది.', NULL, 'a905c1829e68135cca2e820508b7ad8d604eacb29773c7d70fb054682d4b3823') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
