INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2935', 'సమాసముమాల', 'జ్ఞానమాల', 'అష్టదిక్కులు', '= ఎనిమిది దిక్కుల సమాహారము', 'ద్విగు సమాసము', 'సంఖ్యా వాచకపదము పూర్వమున కలది ద్విగు సమాసము. ఇందు సంఖ్య మొదటి పదముగా ఉంటుంది.', NULL, 'b0f48ff519bc751d6c543c009cb1bbd123bc452ce9d149f34cfe0ff38b9bffb3') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2936', 'సమాసముమాల', 'జ్ఞానమాల', 'సప్తర్షులు', '= ఏడుగురు ఋషుల సమాహారము', 'ద్విగు సమాసము', 'సంఖ్యా వాచకపదము పూర్వమున కలది ద్విగు సమాసము. ఇందు సంఖ్య మొదటి పదముగా ఉంటుంది.', NULL, 'b3598a67b31bf41a5968279a960ac7747ada28d7efe52ac61cc29e4d8268354e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2937', 'సమాసముమాల', 'జ్ఞానమాల', 'రామకృష్ణులు', '= రాముడును కృష్ణుడును', 'ద్వంద్వ సమాసము · ద్విపద ద్వంద్వము', 'ఉభయ పదముల అర్ధము ప్రధానముగా గలది ద్వంద్వ సమాసము. విగ్రహ వాక్యమున ''ను'' అను సంయోజకం చేర్చబడును.', NULL, '4ebc76c3b6094bbe2dec3c5d5c0499474dbe523ba1fe831a714e8b6cf5d66761') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2938', 'సమాసముమాల', 'జ్ఞానమాల', 'ధర్మార్థకామమోక్షాలు', '= ధర్మము అర్థము కామము మోక్షము', 'ద్వంద్వ సమాసము · బహుపద ద్వంద్వము', 'ఉభయ పదముల అర్ధము ప్రధానముగా గలది ద్వంద్వ సమాసము. విగ్రహ వాక్యమున ''ను'' అను సంయోజకం చేర్చబడును.', NULL, 'e4ed86e6c34447912350bf368c915849ea793a8a51bc94438c25258ca2740996') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2939', 'సమాసముమాల', 'జ్ఞానమాల', 'రాధాకృష్ణులు', '= రాధ యును కృష్ణుడును', 'ద్వంద్వ సమాసము', 'ఉభయ పదముల అర్ధము ప్రధానముగా గలది ద్వంద్వ సమాసము. విగ్రహ వాక్యమున ''ను'' అను సంయోజకం చేర్చబడును.', NULL, 'a0806f8e9a518b4391497074831fc4b67095f37dda232e8d9f99c8ac6ed74e64') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2940', 'సమాసముమాల', 'జ్ఞానమాల', 'తల్లిదండ్రులు', '= తల్లి యును తండ్రి యును', 'ద్వంద్వ సమాసము', 'ఉభయ పదముల అర్ధము ప్రధానముగా గలది ద్వంద్వ సమాసము. విగ్రహ వాక్యమున ''ను'' అను సంయోజకం చేర్చబడును.', NULL, '50b8b007876419b94c25814612c074fcc2a9924d7748009a3498e9ab903e89e2') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2941', 'సమాసముమాల', 'జ్ఞానమాల', 'సీతారాములు', '= సీత యును రాముడును', 'ద్వంద్వ సమాసము', 'ఉభయ పదముల అర్ధము ప్రధానముగా గలది ద్వంద్వ సమాసము. విగ్రహ వాక్యమున ''ను'' అను సంయోజకం చేర్చబడును.', NULL, '9046d347eb4a572354fd98559c7a7ad70cc3e78f5864ca8c2873b2b1b1f2b326') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2942', 'సమాసముమాల', 'జ్ఞానమాల', 'శివకేశవులు', '= శివుడును కేశవుడును', 'ద్వంద్వ సమాసము', 'ఉభయ పదముల అర్ధము ప్రధానముగా గలది ద్వంద్వ సమాసము. విగ్రహ వాక్యమున ''ను'' అను సంయోజకం చేర్చబడును.', NULL, '7f946c779add6d24f2375e5b710c497e252006a72b22d1c1645f47d12eb60c1e') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2943', 'సమాసముమాల', 'జ్ఞానమాల', 'పీతాంబరుడు', '= పచ్చని వస్త్రము కలవాడు (విష్ణువు)', 'బహువ్రీహి సమాసము · సామాన్య బహువ్రీహి', 'రెండు పదముల అర్థము లేక వేరైన మరొక అర్థము ప్రధానమైన సమాసము బహువ్రీహి. అన్యపదార్థము ప్రధానమైనది.', NULL, 'c4b1bf1292cd349211f24dee91509033a2321d10ad882fe725614cf91fc4f803') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2944', 'సమాసముమాల', 'జ్ఞానమాల', 'పద్మాలయ', '= పద్మము నిలయముగా కలది (లక్ష్మి)', 'బహువ్రీహి సమాసము · స్త్రీ వాచ్య బహువ్రీహి', 'రెండు పదముల అర్థము లేక వేరైన మరొక అర్థము ప్రధానమైన సమాసము బహువ్రీహి. అన్యపదార్థము ప్రధానమైనది.', NULL, 'e8ad012326d7cdc2e0b4730fe523bfaa33f14da80460c1a55052578fd6c084f5') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2945', 'సమాసముమాల', 'జ్ఞానమాల', 'పీతాంబరుడు', '= పచ్చని వస్త్రము కలవాడు', 'బహువ్రీహి సమాసము', 'రెండు పదముల అర్థము లేక వేరైన మరొక అర్థము ప్రధానమైన సమాసము బహువ్రీహి. అన్యపదార్థము ప్రధానమైనది.', NULL, '18c2567d8e08d62b9541edecca96c64bf464537b4408f022d569b187eed998ef') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2946', 'సమాసముమాల', 'జ్ఞానమాల', 'కమలాక్షుడు', '= కమలముల వంటి కన్నులు కలవాడు', 'బహువ్రీహి సమాసము', 'రెండు పదముల అర్థము లేక వేరైన మరొక అర్థము ప్రధానమైన సమాసము బహువ్రీహి. అన్యపదార్థము ప్రధానమైనది.', NULL, 'a3c9aba6cd160a173ebc8b8f00ec83f118cf0d8541079b3a53d8133615b7fbbf') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2947', 'సమాసముమాల', 'జ్ఞానమాల', 'చతుర్భుజుడు', '= నాలుగు భుజములు కలవాడు', 'బహువ్రీహి సమాసము', 'రెండు పదముల అర్థము లేక వేరైన మరొక అర్థము ప్రధానమైన సమాసము బహువ్రీహి. అన్యపదార్థము ప్రధానమైనది.', NULL, 'd13c24d5050c938e39c2ca901fab85fd212d0b7c6d808ca5196695baa4d09933') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2948', 'సమాసముమాల', 'జ్ఞానమాల', 'గజాననుడు', '= గజము వంటి ముఖము కలవాడు', 'బహువ్రీహి సమాసము', 'రెండు పదముల అర్థము లేక వేరైన మరొక అర్థము ప్రధానమైన సమాసము బహువ్రీహి. అన్యపదార్థము ప్రధానమైనది.', NULL, '822d495fe298aaaecf1e74725e0e20aa985c5ebcc2fda10d59d31290aadea032') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2949', 'సమాసముమాల', 'జ్ఞానమాల', 'యథావిధి', '= విధినతిక్రమింపక', 'అవ్యయీభావ సమాసము · యథా అవ్యయీభావము', 'లింగ, వచన, విభక్తులు లేని అవ్యయములు. అవ్యయము పూర్వపదముగా కలది అవ్యయీభావ సమాసము. తెలుగులో ఇది చాలా తక్కువగా వాడబడును.', NULL, 'bc2ce92a233dc9224a2727ba6c264336a5644e25434446331eb949c5146e2941') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2950', 'సమాసముమాల', 'జ్ఞానమాల', 'ప్రతిదినము', '= దినము దినము', 'అవ్యయీభావ సమాసము · ప్రతి అవ్యయీభావము', 'లింగ, వచన, విభక్తులు లేని అవ్యయములు. అవ్యయము పూర్వపదముగా కలది అవ్యయీభావ సమాసము. తెలుగులో ఇది చాలా తక్కువగా వాడబడును.', NULL, '4e6d43adc261495f356c19ada13abcec2957ac3af658e5c517124884762ba625') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2951', 'సమాసముమాల', 'జ్ఞానమాల', 'యథావిధి', '= విధి ప్రకారం', 'అవ్యయీభావ సమాసము', 'లింగ, వచన, విభక్తులు లేని అవ్యయములు. అవ్యయము పూర్వపదముగా కలది అవ్యయీభావ సమాసము. తెలుగులో ఇది చాలా తక్కువగా వాడబడును.', NULL, '4e615837f959815ce571a02a5a072168b6cf0a4596634c2524af8b84b830a3a4') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2952', 'సమాసముమాల', 'జ్ఞానమాల', 'ప్రతిదినము', '= దినము దినము', 'అవ్యయీభావ సమాసము', 'లింగ, వచన, విభక్తులు లేని అవ్యయములు. అవ్యయము పూర్వపదముగా కలది అవ్యయీభావ సమాసము. తెలుగులో ఇది చాలా తక్కువగా వాడబడును.', NULL, '53124493f6ea68a8bfff66617aad1525c1f29b25752165b430a6f030e74a3d3d') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2953', 'సమాసముమాల', 'జ్ఞానమాల', 'ప్రత్యహము', '= ప్రతి రోజు', 'అవ్యయీభావ సమాసము', 'లింగ, వచన, విభక్తులు లేని అవ్యయములు. అవ్యయము పూర్వపదముగా కలది అవ్యయీభావ సమాసము. తెలుగులో ఇది చాలా తక్కువగా వాడబడును.', NULL, '173b62a8e8495586ec0394f9f6268a0b5185957349b40b2dcab790055139906a') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();
INSERT INTO gnanamala (source_key, mala, mala_group, title, content, source, details, link, content_hash) VALUES ('gnanamala-2954', 'సమాసముమాల', 'జ్ఞానమాల', 'యథాశక్తి', '= శక్తిని అనుసరించి', 'అవ్యయీభావ సమాసము', 'లింగ, వచన, విభక్తులు లేని అవ్యయములు. అవ్యయము పూర్వపదముగా కలది అవ్యయీభావ సమాసము. తెలుగులో ఇది చాలా తక్కువగా వాడబడును.', NULL, '116693a81edf8d49cf657132661e8dea52c89a619db1ce5be1c05b4c2b5702fe') ON CONFLICT (source_key) DO UPDATE SET mala=EXCLUDED.mala, mala_group=EXCLUDED.mala_group, title=EXCLUDED.title, content=EXCLUDED.content, source=EXCLUDED.source, details=EXCLUDED.details, content_hash=EXCLUDED.content_hash, updated_at=NOW();

COMMIT;
